export const extraKnowledgeGroups:KnowledgeCard[][]=[
 [{"topic": "കല, സാഹിത്യം, കായികം", "title": "പ്രരോദനം: എ.ആർ.-ന്റെ വിയോഗത്തിൽ ആശാൻ", "body": "എ.ആർ. രാജരാജവർമ്മയുടെ മരണത്തിൽ ദുഃഖിച്ച് കുമാരനാശാൻ എഴുതിയ വിലാപകാവ്യമാണ് 'പ്രരോദനം'. ആശാന്റെ 'ചണ്ഡാലഭിക്ഷുകി'യിലെ നായിക മാതംഗി ആനന്ദഭിക്ഷുവിനെ ശ്രാവസ്തിയിൽ കണ്ടുമുട്ടുന്നു.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Kumaran_Asan"},
  {"topic": "കല, സാഹിത്യം, കായികം", "title": "ഉള്ളൂർ: ഉമാകേരളവും സാഹിത്യചരിത്രവും", "body": "കവിത്രയത്തിലെ ഉള്ളൂർ എസ്. പരമേശ്വരയ്യരുടെ മഹാകാവ്യമാണ് 'ഉമാകേരളം' (1914). അദ്ദേഹം രചിച്ച സമഗ്ര സാഹിത്യചരിത്രം 'കേരളസാഹിത്യ ചരിത്രം' അഞ്ചു വാല്യങ്ങളായി മരണശേഷം തിരുവിതാംകൂർ സർവകലാശാല പ്രസിദ്ധീകരിച്ചു.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Ulloor_S._Parameswara_Iyer"},
  {"topic": "കല, സാഹിത്യം, കായികം", "title": "ആദ്യ ജ്ഞാനപീഠം: ജി. ശങ്കരക്കുറുപ്പ്", "body": "1965-ലെ ആദ്യ ജ്ഞാനപീഠ പുരസ്കാരം മലയാള കവി ജി. ശങ്കരക്കുറുപ്പിന് 'ഓടക്കുഴൽ' എന്ന കവിതാസമാഹാരത്തിന് ലഭിച്ചു. ഓടക്കുഴൽ 1950-ലാണ് പ്രസിദ്ധീകരിച്ചത്.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Jnanpith_Award"},
  {"topic": "കല, സാഹിത്യം, കായികം", "title": "എസ്.കെ. പൊറ്റെക്കാട്ട്: ജ്ഞാനപീഠം 1980", "body": "'ഒരു ദേശത്തിന്റെ കഥ' എന്ന നോവലിന് എസ്.കെ. പൊറ്റെക്കാട്ടിന് 1980-ലെ ജ്ഞാനപീഠം ലഭിച്ചു. അതിരാണിപ്പാടം എന്ന ദേശത്തിന്റെ കഥ പറയുന്ന ഈ നോവലിന് 1972-ൽ കേന്ദ്ര സാഹിത്യ അക്കാദമി അവാർഡും ലഭിച്ചിരുന്നു.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Oru_Desathinte_Katha"},
  {"topic": "കല, സാഹിത്യം, കായികം", "title": "രണ്ടാമൂഴം: എം.ടി.ക്ക് വയലാർ അവാർഡ്", "body": "ഭീമനെ നായകനാക്കി എം.ടി. വാസുദേവൻ നായർ എഴുതിയ 'രണ്ടാമൂഴം' എന്ന നോവലിന് 1985-ലെ വയലാർ അവാർഡ് ലഭിച്ചു. 1995-ൽ എം.ടി.ക്ക് സമഗ്ര സംഭാവനയ്ക്ക് ജ്ഞാനപീഠവും ലഭിച്ചു.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Vayalar_Award"},
  {"topic": "കല, സാഹിത്യം, കായികം", "title": "ഒ.എൻ.വി. കുറുപ്പ്: ജ്ഞാനപീഠം 2007", "body": "ഒ.എൻ.വി. കുറുപ്പിന് 2007-ലെ ജ്ഞാനപീഠ പുരസ്കാരം സമഗ്ര സംഭാവനയ്ക്ക് ലഭിച്ചു (2008 അല്ല). ജി. ശങ്കരക്കുറുപ്പ്, എസ്.കെ. പൊറ്റെക്കാട്ട്, തകഴി (1984), എം.ടി. (1995) എന്നിവർക്കു ശേഷം ജ്ഞാനപീഠം നേടിയ അഞ്ചാമത്തെ മലയാളി.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Jnanpith_Award"},
  {"topic": "കല, സാഹിത്യം, കായികം", "title": "അക്കിത്തം: ജ്ഞാനപീഠം 2019", "body": "അക്കിത്തം അച്യുതൻ നമ്പൂതിരിക്ക് 2019-ലെ ജ്ഞാനപീഠം ലഭിച്ചു; പുരസ്കാരം നേടിയ ആറാമത്തെ മലയാളി. ജി., എസ്.കെ., തകഴി, എം.ടി., ഒ.എൻ.വി. എന്നിവരാണ് മുൻഗാമികൾ.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Jnanpith_Award"},
  {"topic": "കല, സാഹിത്യം, കായികം", "title": "എഴുത്തച്ഛൻ പുരസ്കാരം: ആദ്യം ശൂരനാട്", "body": "1993-ൽ ആരംഭിച്ച എഴുത്തച്ഛൻ പുരസ്കാരം ആദ്യമായി ലഭിച്ചത് ശൂരനാട് കുഞ്ഞൻപിള്ളയ്ക്കാണ്. 5 ലക്ഷം രൂപയും പ്രശസ്തിപത്രവുമാണ് സമ്മാനം. 2012-ൽ ആറ്റൂർ രവിവർമ്മ, 2013-ൽ എം.കെ. സാനു എന്നിവർക്ക് ലഭിച്ചു.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Ezhuthachan_Puraskaram"},
  {"topic": "കല, സാഹിത്യം, കായികം", "title": "ആദ്യ വയലാർ അവാർഡ്: അഗ്നിസാക്ഷി", "body": "വയലാർ രാമവർമ്മ മെമ്മോറിയൽ ട്രസ്റ്റ് 1977-ൽ ഏർപ്പെടുത്തിയ വയലാർ അവാർഡ് ആദ്യമായി ലഭിച്ചത് ലളിതാംബിക അന്തർജ്ജനത്തിന്റെ 'അഗ്നിസാക്ഷി' എന്ന നോവലിനാണ്. 2014-ൽ കെ.ആർ. മീരയുടെ 'ആരാച്ചാർ'ക്ക് ലഭിച്ചു.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Vayalar_Award"},
  {"topic": "കല, സാഹിത്യം, കായികം", "title": "കേരള സാഹിത്യ അക്കാദമി: ആദ്യ അധ്യക്ഷൻ", "body": "1956-ൽ സ്ഥാപിതമായ കേരള സാഹിത്യ അക്കാദമി തിരുവിതാംകൂർ മഹാരാജാവ് ചിത്തിര തിരുനാൾ കനകക്കുന്ന് കൊട്ടാരത്തിൽ ഉദ്ഘാടനം ചെയ്തു. ആദ്യ പ്രസിഡന്റ് സർദാർ കെ.എം. പണിക്കർ. ആസ്ഥാനം ഇപ്പോൾ തൃശ്ശൂർ.", "source": "Kerala Tourism", "url": "https://www.keralatourism.org/destination/kerala-sahitya-academi/576/"}],
 [{"topic": "മലയാള ഭാഷ", "title": "മലയാളത്തിന് ശ്രേഷ്ഠഭാഷാ പദവി: 2013", "body": "2013 മെയ് 23-ന് കേന്ദ്രമന്ത്രിസഭ മലയാളത്തിന് ശ്രേഷ്ഠഭാഷാ (ക്ലാസിക്കൽ) പദവി അംഗീകരിച്ചു. തമിഴ്, സംസ്കൃതം, കന്നഡ, തെലുങ്ക് എന്നിവയ്ക്ക് ശേഷം പദവി ലഭിച്ച അഞ്ചാമത്തെ ഭാഷ; 2024-ഓടെ ആകെ 11 ശ്രേഷ്ഠഭാഷകൾ.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Classical_languages_of_India"},
  {"topic": "മലയാള ഭാഷ", "title": "കേരളപാണിനീയം: എ.ആർ. രാജരാജവർമ്മ", "body": "ആധുനിക മലയാള വ്യാകരണത്തിന്റെ അടിസ്ഥാനഗ്രന്ഥമായ 'കേരളപാണിനീയം' 1896-ൽ ആദ്യമായി പ്രസിദ്ധീകരിച്ചു. കർത്താവ് എ.ആർ. രാജരാജവർമ്മ 'കേരളപാണിനി' എന്നറിയപ്പെടുന്നു.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Kerala_Panineeyam"},
  {"topic": "മലയാള ഭാഷ", "title": "ഗുണ്ടർട്ട് നിഘണ്ടു: 1872", "body": "ഹെർമൻ ഗുണ്ടർട്ട് തയ്യാറാക്കിയ മലയാളം-ഇംഗ്ലീഷ് നിഘണ്ടു 1872-ൽ പ്രസിദ്ധീകരിച്ചു. തലശ്ശേരിക്കടുത്ത ഇല്ലിക്കുന്നിൽ ബാസൽ മിഷൻ പ്രവർത്തകനായിരുന്ന അദ്ദേഹം 'മലയാള ഭാഷാ വ്യാകരണം' എന്ന വ്യാകരണഗ്രന്ഥവും രചിച്ചു.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Hermann_Gundert"},
  {"topic": "മലയാള ഭാഷ", "title": "രാജ്യസമാചാരം: ആദ്യ മലയാള പത്രം, 1847", "body": "1847 ജൂണിൽ ഹെർമൻ ഗുണ്ടർട്ട് തലശ്ശേരി ഇല്ലിക്കുന്നിൽനിന്ന് പ്രസിദ്ധീകരിച്ച 'രാജ്യസമാചാരം' ആണ് കേരളത്തിലെ ആദ്യ മലയാള പത്രം. ലിത്തോഗ്രാഫ് അച്ചിൽ സൗജന്യമായി വിതരണം ചെയ്തു; 1850 ഡിസംബറിൽ നിലച്ചു.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Rajyasamacharam"},
  {"topic": "മലയാള ഭാഷ", "title": "പശ്ചിമോദയം: ഗുണ്ടർട്ടിന്റെ മാസിക", "body": "രാജ്യസമാചാരത്തിനു പിന്നാലെ 1847 ഒക്ടോബറിൽ ഹെർമൻ ഗുണ്ടർട്ട് തലശ്ശേരിയിൽനിന്ന് 'പശ്ചിമോദയം' എന്ന മാസിക ആരംഭിച്ചു. 'പടിഞ്ഞാറിന്റെ ഉദയം' എന്നാണ് പേരിന്റെ അർത്ഥം.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Hermann_Gundert"},
  {"topic": "മലയാള ഭാഷ", "title": "സന്ധി നാലുവിധം: കേരളപാണിനീയം", "body": "വർണ്ണവികാരം അടിസ്ഥാനമാക്കി കേരളപാണിനി സന്ധിയെ ലോപം, ആഗമം, ആദേശം, ദ്വിത്വം എന്നിങ്ങനെ നാലായി തിരിച്ചു. ഒരു വർണം ലോപിക്കൽ, പുതിയത് വരൽ, പകരം വരൽ, ഇരട്ടിക്കൽ എന്നിവയാണ് യഥാക്രമം.", "source": "Wikipedia", "url": "https://ml.wikipedia.org/wiki/%E0%B4%B8%E0%B4%A8%E0%B5%8D%E0%B4%A7%E0%B4%BF_(%E0%B4%B5%E0%B5%8D%E0%B4%AF%E0%B4%BE%E0%B4%95%E0%B4%B0%E0%B4%A3%E0%B4%82)"},
  {"topic": "മലയാള ഭാഷ", "title": "ആഗമസന്ധി: തിരു + ഓണം = തിരുവോണം", "body": "രണ്ട് വർണങ്ങൾ ചേരുമ്പോൾ ഇടയിൽ പുതിയൊരു വർണം വന്നുചേരുന്നതാണ് ആഗമസന്ധി. ഉദാ: തിരു + ഓണം = തിരുവോണം (വ് ആഗമം), തിരു + അനന്തപുരം = തിരുവനന്തപുരം, പന + ഓല = പനയോല (യ് ആഗമം).", "source": "Wikipedia", "url": "https://ml.wikipedia.org/wiki/%E0%B4%B8%E0%B4%A8%E0%B5%8D%E0%B4%A7%E0%B4%BF_(%E0%B4%B5%E0%B5%8D%E0%B4%AF%E0%B4%BE%E0%B4%95%E0%B4%B0%E0%B4%A3%E0%B4%82)"},
  {"topic": "മലയാള ഭാഷ", "title": "ആദേശസന്ധി: കൺ + നീർ = കണ്ണീർ", "body": "ഒരു വർണത്തിനു പകരം മറ്റൊരു വർണം വരുന്നതാണ് ആദേശസന്ധി. ഉദാ: നെൽ + മണി = നെന്മണി, കൺ + നീർ = കണ്ണീർ, അവൻ + ഓടി = അവനോടി. പി.എസ്.സി. പരീക്ഷകളിൽ വെണ്ണീർ, വെണ്ണിലാവ് എന്നിവയും ആദേശത്തിന് ഉദാഹരണം.", "source": "Wikipedia", "url": "https://ml.wikipedia.org/wiki/%E0%B4%B8%E0%B4%A8%E0%B5%8D%E0%B4%A7%E0%B4%BF_(%E0%B4%B5%E0%B5%8D%E0%B4%AF%E0%B4%BE%E0%B4%95%E0%B4%B0%E0%B4%A3%E0%B4%82)"},
  {"topic": "മലയാള ഭാഷ", "title": "ദ്വിത്വസന്ധി: താമര + കുളം", "body": "ചേരുന്ന വ്യഞ്ജനങ്ങളിൽ ഒന്ന് ഇരട്ടിക്കുന്നതാണ് ദ്വിത്വസന്ധി. ഉദാ: പച്ച + കല്ല് = പച്ചക്കല്ല്, നിൻ + എ = നിന്നെ, താമര + കുളം = താമരക്കുളം, ഇറങ്ങി + പോയി = ഇറങ്ങിപ്പോയി.", "source": "Wikipedia", "url": "https://ml.wikipedia.org/wiki/%E0%B4%B8%E0%B4%A8%E0%B5%8D%E0%B4%A7%E0%B4%BF_(%E0%B4%B5%E0%B5%8D%E0%B4%AF%E0%B4%BE%E0%B4%95%E0%B4%B0%E0%B4%A3%E0%B4%82)"},
  {"topic": "മലയാള ഭാഷ", "title": "ദ്വന്ദ്വനും ബഹുവ്രീഹിയും", "body": "രണ്ടു പദങ്ങൾക്കും തുല്യപ്രാധാന്യമുള്ളത് ദ്വന്ദ്വസമാസം (കൈകാലുകൾ, മാതാപിതാക്കൾ). ഇരുപദങ്ങളും അല്ലാതെ അന്യപദത്തിന് പ്രാധാന്യം വരുന്നത് ബഹുവ്രീഹി (ചെന്താമരക്കണ്ണൻ, പങ്കജാക്ഷി).", "source": "Wikipedia", "url": "https://ml.wikipedia.org/wiki/%E0%B4%B8%E0%B4%AE%E0%B4%BE%E0%B4%B8%E0%B4%82"}],
 [{"topic": "ജീവശാസ്ത്രവും ആരോഗ്യവും", "title": "ഫീമർ: ഏറ്റവും വലുതും നീളമേറിയതുമായ അസ്ഥി", "body": "മനുഷ്യശരീരത്തിലെ ഏറ്റവും വലുതും നീളം കൂടിയതും കട്ടിയേറിയതുമായ അസ്ഥിയാണ് തുടയെല്ലായ ഫീമർ. ഇടുപ്പിനെയും കാൽമുട്ടിനെയും ബന്ധിപ്പിക്കുന്ന ഈ അസ്ഥി ശരീരഭാരം താങ്ങുന്നതിൽ പ്രധാന പങ്ക് വഹിക്കുന്നു.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Femur"},
  {"topic": "ജീവശാസ്ത്രവും ആരോഗ്യവും", "title": "സ്റ്റേപ്പിസ്: ഏറ്റവും ചെറിയ അസ്ഥി", "body": "മനുഷ്യശരീരത്തിലെ ഏറ്റവും ചെറുതും ഭാരം കുറഞ്ഞതുമായ അസ്ഥിയാണ് മധ്യകർണത്തിലെ സ്റ്റേപ്പിസ്. മാലിയസ്, ഇൻകസ്, സ്റ്റേപ്പിസ് എന്നീ മൂന്ന് ശ്രവണാസ്ഥികളിൽ മൂന്നാമത്തേതാണിത്.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Stapes"},
  {"topic": "ജീവശാസ്ത്രവും ആരോഗ്യവും", "title": "മുതിർന്നവരിൽ 206 അസ്ഥികൾ", "body": "ജനനസമയത്ത് ഏകദേശം 270 അസ്ഥികളുണ്ടെങ്കിലും ചിലത് കൂടിച്ചേരുന്നതിനാൽ മുതിർന്നവരിൽ ഏകദേശം 206 അസ്ഥികളാണുള്ളത്. ഇതിൽ അക്ഷാസ്ഥികൂടത്തിൽ 80-ഉം അനുബന്ധ അസ്ഥികൂടത്തിൽ 126-ഉം അസ്ഥികളുണ്ട്.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Human_skeleton"},
  {"topic": "ജീവശാസ്ത്രവും ആരോഗ്യവും", "title": "കരൾ: ഏറ്റവും വലിയ ആന്തരാവയവവും ഗ്രന്ഥിയും", "body": "ശരീരത്തിലെ ഏറ്റവും വലിയ ആന്തരാവയവവും ഏറ്റവും വലിയ ഗ്രന്ഥിയുമാണ് കരൾ. വിഷവസ്തുക്കളെ നിർവീര്യമാക്കുന്നതും കൊഴുപ്പിന്റെ ദഹനത്തിന് സഹായിക്കുന്ന പിത്തരസം (ബൈൽ) ഉൽപാദിപ്പിക്കുന്നതും കരളാണ്; പിത്തരസം പിത്താശയത്തിൽ സംഭരിക്കുന്നു.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Liver"},
  {"topic": "ജീവശാസ്ത്രവും ആരോഗ്യവും", "title": "തൈറോയ്ഡ്: ഏറ്റവും വലിയ അന്തഃസ്രാവി ഗ്രന്ഥി", "body": "കഴുത്തിന്റെ മുൻഭാഗത്ത് ശ്വാസനാളത്തിന് മുന്നിലായി സ്ഥിതിചെയ്യുന്ന തൈറോയ്ഡാണ് ഏറ്റവും വലിയ അന്തഃസ്രാവി ഗ്രന്ഥി. തൈറോക്സിൻ (T4), ട്രൈഅയഡോതൈറോണിൻ (T3), രക്തത്തിലെ കാൽസ്യം കുറയ്ക്കുന്ന കാൽസിടോണിൻ എന്നിവ ഇത് ഉൽപാദിപ്പിക്കുന്നു.", "source": "Aakash", "url": "https://www.aakash.ac.in/important-concepts/biology/thyroid-gland"},
  {"topic": "ജീവശാസ്ത്രവും ആരോഗ്യവും", "title": "അയഡിന്റെ കുറവ്: ഗോയിറ്റർ", "body": "അയഡിന്റെ അപര്യാപ്തത തൈറോയ്ഡ് ഗ്രന്ഥി വീങ്ങുന്ന ഗോയിറ്ററിന് കാരണമാകുന്നു. ഗർഭകാലത്തെ അയഡിൻ കുറവ് കുട്ടികളിൽ ക്രെറ്റിനിസത്തിന് (ബുദ്ധിമാന്ദ്യം, വളർച്ചാമുരടിപ്പ്) ഇടയാക്കാം. കറിയുപ്പിൽ അയഡിൻ ചേർക്കലാണ് പ്രധാന പ്രതിരോധമാർഗം.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Iodine_deficiency"},
  {"topic": "ജീവശാസ്ത്രവും ആരോഗ്യവും", "title": "പിറ്റ്യൂറ്ററി: 'മാസ്റ്റർ ഗ്രന്ഥി'", "body": "തൈറോയ്ഡ്, അഡ്രിനൽ തുടങ്ങിയ മറ്റ് ഗ്രന്ഥികളെ നിയന്ത്രിക്കുന്നതിനാൽ പിറ്റ്യൂറ്ററിയെ 'മാസ്റ്റർ ഗ്രന്ഥി' എന്ന് വിളിക്കുന്നു. മസ്തിഷ്കത്തിന്റെ അടിഭാഗത്തുള്ള ഇതിന്റെ മുൻഭാഗമാണ് ശരീരവളർച്ച നിയന്ത്രിക്കുന്ന വളർച്ചാഹോർമോൺ (സൊമാറ്റോട്രോപ്പിൻ) ഉൽപാദിപ്പിക്കുന്നത്.", "source": "Hormones Australia", "url": "https://www.hormones-australia.org.au/the-endocrine-system/pituitary/"},
  {"topic": "ജീവശാസ്ത്രവും ആരോഗ്യവും", "title": "ഇൻസുലിൻ: പാൻക്രിയാസിലെ ബീറ്റാ കോശങ്ങൾ", "body": "രക്തത്തിലെ പഞ്ചസാര നിയന്ത്രിക്കുന്ന ഇൻസുലിൻ ഉൽപാദിപ്പിക്കുന്നത് പാൻക്രിയാസിലെ ഐലറ്റ്സ് ഓഫ് ലാംഗർഹാൻസിലെ ബീറ്റാ കോശങ്ങളാണ്. 1921-ൽ ടൊറന്റോ സർവകലാശാലയിൽ ഫ്രെഡറിക് ബാന്റിങ്ങും ചാൾസ് ബെസ്റ്റും ചേർന്ന് ഇൻസുലിൻ വേർതിരിച്ചെടുത്തു.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Insulin"},
  {"topic": "ജീവശാസ്ത്രവും ആരോഗ്യവും", "title": "അഡ്രിനാലിൻ: 'പൊരുതുക അല്ലെങ്കിൽ ഓടുക' ഹോർമോൺ", "body": "അടിയന്തര സാഹചര്യങ്ങളെ നേരിടാൻ ശരീരത്തെ സജ്ജമാക്കുന്ന ഹോർമോണാണ് അഡ്രിനാലിൻ (എപ്പിനെഫ്രിൻ). അഡ്രിനൽ ഗ്രന്ഥിയുടെ മെഡുല്ലയാണ് ഇത് പ്രധാനമായും ഉൽപാദിപ്പിക്കുന്നത്; ഹൃദയമിടിപ്പും രക്തത്തിലെ പഞ്ചസാരയും കൂട്ടുകയും കൃഷ്ണമണി വികസിപ്പിക്കുകയും ചെയ്യുന്നു.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Adrenaline"},
  {"topic": "ജീവശാസ്ത്രവും ആരോഗ്യവും", "title": "ABO രക്തഗ്രൂപ്പ്: കാൾ ലാൻഡ്സ്റ്റെയ്നർ", "body": "ABO രക്തഗ്രൂപ്പുകൾ 1901-ൽ കണ്ടെത്തിയത് ഓസ്ട്രിയൻ ശാസ്ത്രജ്ഞൻ കാൾ ലാൻഡ്സ്റ്റെയ്നറാണ്. നാലാമത്തെ ഗ്രൂപ്പായ AB അടുത്ത വർഷം (1902) അദ്ദേഹത്തിന്റെ ശിഷ്യരായ ഡികാസ്റ്റെല്ലോയും സ്റ്റർലിയും കണ്ടെത്തി.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/ABO_blood_group_system"}],
 [{"topic": "ഇന്ത്യൻ ഭരണഘടന", "title": "ഭരണഘടനാ നിർമാണസഭയുടെ ആദ്യ യോഗം: 1946", "body": "ഭരണഘടനാ നിർമാണസഭയുടെ ആദ്യ യോഗം 1946 ഡിസംബർ 9-ന് ന്യൂഡൽഹിയിൽ ചേർന്നു; 207 അംഗങ്ങൾ പങ്കെടുത്തു. ഡോ. സച്ചിദാനന്ദ സിൻഹയായിരുന്നു സഭയുടെ ആദ്യ (താൽക്കാലിക) അധ്യക്ഷൻ; നെഹ്റു അല്ല.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Constituent_Assembly_of_India"},
  {"topic": "ഇന്ത്യൻ ഭരണഘടന", "title": "നിർമാണസഭാ അധ്യക്ഷൻ: രാജേന്ദ്രപ്രസാദ്", "body": "1946 ഡിസംബർ 11-ന് ഡോ. രാജേന്ദ്രപ്രസാദ് ഭരണഘടനാ നിർമാണസഭയുടെ സ്ഥിരം അധ്യക്ഷനായി; എച്ച്.സി. മുഖർജി ഉപാധ്യക്ഷനായി. 1950 ജനുവരി 26-ന് റിപ്പബ്ലിക്കിന്റെ ആദ്യ രാഷ്ട്രപതിയായതും രാജേന്ദ്രപ്രസാദാണ്.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Constituent_Assembly_of_India"},
  {"topic": "ഇന്ത്യൻ ഭരണഘടന", "title": "ഡ്രാഫ്റ്റിങ് കമ്മിറ്റി: അധ്യക്ഷൻ അംബേദ്കർ", "body": "1947 ഓഗസ്റ്റ് 29-ന് ഡോ. ബി.ആർ. അംബേദ്കർ അധ്യക്ഷനായി ഡ്രാഫ്റ്റിങ് കമ്മിറ്റി രൂപീകരിച്ചു. കെ.എം. മുൻഷി, അല്ലാടി കൃഷ്ണസ്വാമി അയ്യർ, എൻ. ഗോപാലസ്വാമി അയ്യങ്കാർ, മുഹമ്മദ് സാദുള്ള, എൻ. മാധവറാവു, ടി.ടി. കൃഷ്ണമാചാരി എന്നിവരായിരുന്നു മറ്റംഗങ്ങൾ.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Constituent_Assembly_of_India"},
  {"topic": "ഇന്ത്യൻ ഭരണഘടന", "title": "നിർമാണസഭ: ക്യാബിനറ്റ് മിഷൻ പദ്ധതി", "body": "1946-ലെ ക്യാബിനറ്റ് മിഷൻ പദ്ധതി പ്രകാരമാണ് ഭരണഘടനാ നിർമാണസഭ രൂപീകരിച്ചത്. ആകെ 389 അംഗങ്ങൾ: പ്രവിശ്യകളിൽനിന്ന് 292, നാട്ടുരാജ്യങ്ങളിൽനിന്ന് 93, ചീഫ് കമ്മീഷണർ പ്രവിശ്യകളിൽനിന്ന് 4. വിഭജനശേഷം അംഗസംഖ്യ 299 ആയി കുറഞ്ഞു.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Constituent_Assembly_of_India"},
  {"topic": "ഇന്ത്യൻ ഭരണഘടന", "title": "ഭരണഘടനാ ഉപദേഷ്ടാവ്: ബി.എൻ. റാവു", "body": "1946 ജൂലൈ 11-ന് ബി.എൻ. റാവു ഭരണഘടനാ നിർമാണസഭയുടെ ഭരണഘടനാ ഉപദേഷ്ടാവായി നിയമിതനായി. ഭരണഘടനയുടെ ആദ്യ കരട് തയ്യാറാക്കിയത് അദ്ദേഹമാണ്; ഡ്രാഫ്റ്റിങ് കമ്മിറ്റിയുടെ ഉപദേഷ്ടാവ് എന്ന ചോദ്യത്തിനും ഉത്തരം ബി.എൻ. റാവുവാണ്.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Constituent_Assembly_of_India"},
  {"topic": "ഇന്ത്യൻ ഭരണഘടന", "title": "നിർദ്ദേശക തത്വങ്ങൾ: അയർലൻഡിൽനിന്ന്", "body": "നിർദ്ദേശക തത്വങ്ങൾ (DPSP) എന്ന ആശയം അയർലൻഡിന്റെ ഭരണഘടനയിൽനിന്നാണ് ഇന്ത്യ സ്വീകരിച്ചത്. രാജ്യസഭയിലേക്ക് അംഗങ്ങളെ നാമനിർദ്ദേശം ചെയ്യുന്ന രീതിയും രാഷ്ട്രപതിയെ തിരഞ്ഞെടുക്കുന്ന രീതിയും അയർലൻഡിൽനിന്ന് കടമെടുത്തവയാണ്.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Constitution_of_India"},
  {"topic": "ഇന്ത്യൻ ഭരണഘടന", "title": "മൗലികാവകാശങ്ങളും ആമുഖവും: അമേരിക്കയിൽനിന്ന്", "body": "മൗലികാവകാശങ്ങൾ, ജുഡീഷ്യൽ റിവ്യൂ (നീതിന്യായ പുനരവലോകനം), ലിഖിത ഭരണഘടന, ആമുഖം എന്നിവ അമേരിക്കൻ ഐക്യനാടുകളുടെ ഭരണഘടനയിൽനിന്ന് സ്വീകരിച്ചവയാണ്. ‘ആമുഖം’ എന്ന ആശയത്തിന് കടപ്പാട് അമേരിക്കയോടാണ്.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Constitution_of_India"},
  {"topic": "ഇന്ത്യൻ ഭരണഘടന", "title": "രണ്ടാം പട്ടിക: ശമ്പളവും ആനുകൂല്യങ്ങളും", "body": "ഭരണഘടനയുടെ രണ്ടാം പട്ടികയിൽ രാഷ്ട്രപതി, ഗവർണർമാർ, സുപ്രീം കോടതി-ഹൈക്കോടതി ജഡ്ജിമാർ, കംട്രോളർ ആൻഡ് ഓഡിറ്റർ ജനറൽ തുടങ്ങിയവരുടെ ശമ്പളം സംബന്ധിച്ച വ്യവസ്ഥകളാണ്. മൂന്നാം പട്ടികയിൽ സത്യപ്രതിജ്ഞയുടെ മാതൃകകളാണ്.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Constitution_of_India"},
  {"topic": "ഇന്ത്യൻ ഭരണഘടന", "title": "ഏഴാം പട്ടിക: മൂന്ന് അധികാര ലിസ്റ്റുകൾ", "body": "കേന്ദ്ര-സംസ്ഥാന അധികാരവിഭജനം വ്യക്തമാക്കുന്നത് ഏഴാം പട്ടികയാണ്: യൂണിയൻ ലിസ്റ്റ്, സംസ്ഥാന ലിസ്റ്റ്, സമവർത്തി (കൺകറന്റ്) ലിസ്റ്റ്. സമവർത്തി ലിസ്റ്റ് എന്ന ആശയം ഓസ്ട്രേലിയൻ ഭരണഘടനയിൽനിന്ന് സ്വീകരിച്ചതാണ്.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Constitution_of_India"},
  {"topic": "ഇന്ത്യൻ ഭരണഘടന", "title": "കൂറുമാറ്റ നിരോധനം: 52-ാം ഭേദഗതി, 1985", "body": "1985-ലെ 52-ാം ഭേദഗതി പത്താം പട്ടിക ചേർത്ത് കൂറുമാറ്റ നിരോധന നിയമം കൊണ്ടുവന്നു. അയോഗ്യത സംബന്ധിച്ച് തീരുമാനമെടുക്കുന്നത് സ്പീക്കർ/ചെയർമാൻ; 2003-ലെ 91-ാം ഭേദഗതി ‘പിളർപ്പ്’ എന്ന ഇളവ് ഒഴിവാക്കി, ലയനത്തിന് മൂന്നിൽ രണ്ട് അംഗങ്ങൾ വേണം.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Tenth_Schedule_to_the_Constitution_of_India"}],
 [{"topic": "ആനുകാലികം", "title": "2026 സാഹിത്യ നൊബേൽ: ആൻ കാഴ്സൺ", "body": "2026-ലെ സാഹിത്യ നൊബേൽ കനേഡിയൻ കവിയും ഉപന്യാസകാരിയും ക്ലാസിക്കൽ പണ്ഡിതയുമായ ആൻ കാഴ്സണ്. 2026 ഒക്ടോബർ 8-ന് സ്വീഡിഷ് അക്കാദമി പ്രഖ്യാപിച്ചു. 'ഓട്ടോബയോഗ്രഫി ഓഫ് റെഡ്' (1998) ശ്രദ്ധേയ കൃതി.", "source": "The Korea Times", "url": "https://www.koreatimes.co.kr/world/20261008/canadian-poet-anne-carson-wins-nobel-prize-in-literature"},
  {"topic": "ആനുകാലികം", "title": "2026 സമാധാന നൊബേൽ: നവി പിള്ള", "body": "2026-ലെ സമാധാന നൊബേൽ ദക്ഷിണാഫ്രിക്കൻ ന്യായാധിപയും മുൻ യു.എൻ. മനുഷ്യാവകാശ ഹൈക്കമ്മീഷണറുമായ നവി (നവനീതം) പിള്ളയ്ക്ക്. ഇന്ത്യൻ തമിഴ് വംശജയായ അവർക്കുള്ള പുരസ്കാരം 2026 ഒക്ടോബർ 9-ന് ഓസ്ലോയിൽ പ്രഖ്യാപിച്ചു.", "source": "Al Jazeera", "url": "https://www.aljazeera.com/news/2026/10/9/2026-nobel-peace-prize-awarded-to-navi-pillay"},
  {"topic": "ആനുകാലികം", "title": "2025 സമാധാന നൊബേൽ: മരിയ കൊറീന മച്ചാദോ", "body": "2025-ലെ (ഒക്ടോബർ) സമാധാന നൊബേൽ വെനസ്വേലക്കാരിയായ മരിയ കൊറീന മച്ചാദോയ്ക്ക് ലഭിച്ചു. വെനസ്വേലൻ ജനതയുടെ ജനാധിപത്യ അവകാശങ്ങൾക്കായുള്ള അക്ഷീണ പ്രവർത്തനമാണ് പുരസ്കാരത്തിന് ആധാരം.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/2025_Nobel_Prizes"},
  {"topic": "ആനുകാലികം", "title": "2025 സാഹിത്യ നൊബേൽ: ക്രസ്നഹോർകായ്", "body": "2025-ലെ (ഒക്ടോബർ) സാഹിത്യ നൊബേൽ ഹംഗേറിയൻ എഴുത്തുകാരൻ ലാസ്ലോ ക്രസ്നഹോർകായിക്ക്. പ്രളയസമാന ഭീതിക്കിടയിലും കലയുടെ ശക്തി ഉറപ്പിക്കുന്ന ദർശനാത്മകമായ രചനകൾക്കാണ് പുരസ്കാരം.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/2025_Nobel_Prizes"},
  {"topic": "ആനുകാലികം", "title": "2024 സാഹിത്യ നൊബേൽ: ഹാൻ കാങ്", "body": "2024-ലെ (ഒക്ടോബർ) സാഹിത്യ നൊബേൽ ദക്ഷിണ കൊറിയൻ എഴുത്തുകാരി ഹാൻ കാങ്ങിന്. ചരിത്രപരമായ ആഘാതങ്ങളെ നേരിടുകയും മനുഷ്യജീവിതത്തിന്റെ ദുർബലത തുറന്നുകാട്ടുകയും ചെയ്യുന്ന 'തീവ്രമായ കാവ്യാത്മക ഗദ്യ'ത്തിനാണ് പുരസ്കാരം.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/2024_Nobel_Prizes"},
  {"topic": "ആനുകാലികം", "title": "2024 സമാധാന നൊബേൽ: നിഹോൺ ഹിദാൻക്യോ", "body": "2024-ലെ (ഒക്ടോബർ) സമാധാന നൊബേൽ ജപ്പാനിലെ ഹിരോഷിമ–നാഗസാക്കി അണുബോംബ് അതിജീവിതരുടെ സംഘടനയായ നിഹോൺ ഹിദാൻക്യോയ്ക്ക്. ആണവായുധ മുക്ത ലോകത്തിനായുള്ള ശ്രമങ്ങളും സാക്ഷിമൊഴികളുമാണ് പുരസ്കാരത്തിന് ആധാരം.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/2024_Nobel_Prizes"},
  {"topic": "ആനുകാലികം", "title": "2024 ഭൗതിക നൊബേൽ: ഹോപ്ഫീൽഡ്, ഹിന്റൺ", "body": "2024-ലെ (ഒക്ടോബർ) ഭൗതികശാസ്ത്ര നൊബേൽ ജോൺ ഹോപ്ഫീൽഡ് (യു.എസ്.), ജെഫ്രി ഹിന്റൺ എന്നിവർക്ക്. കൃത്രിമ ന്യൂറൽ നെറ്റ്‌വർക്കുകൾ ഉപയോഗിച്ചുള്ള മെഷീൻ ലേണിങ്ങിന് അടിത്തറയിട്ട കണ്ടെത്തലുകൾക്കാണ് പുരസ്കാരം.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/2024_Nobel_Prizes"},
  {"topic": "ആനുകാലികം", "title": "2026 ഫിഫ ലോകകപ്പ്: സ്പെയിൻ ജേതാക്കൾ", "body": "2026 ജൂലൈ 19-ന് ന്യൂജേഴ്സിയിലെ ഈസ്റ്റ് റഥർഫോർഡിൽ നടന്ന ഫൈനലിൽ അർജന്റീനയെ എക്സ്ട്രാ ടൈമിൽ 1–0ന് തോൽപ്പിച്ച് സ്പെയിൻ രണ്ടാം ലോകകിരീടം നേടി (ആദ്യം 2010). ഗോൾ: ഫെറാൻ ടോറസ്; ഗോൾഡൻ ബോൾ: റോഡ്രി.", "source": "FIFA", "url": "https://inside.fifa.com/en/news/spain-crowned-world-cup-2026-champions-new-york-new-jersey"},
  {"topic": "ആനുകാലികം", "title": "2026 ടി20 ലോകകപ്പ്: ഇന്ത്യക്ക് മൂന്നാം കിരീടം", "body": "2026 മാർച്ച് 8-ന് അഹമ്മദാബാദിലെ നരേന്ദ്ര മോദി സ്റ്റേഡിയത്തിൽ ന്യൂസിലൻഡിനെ 96 റൺസിന് തോൽപ്പിച്ച് സൂര്യകുമാർ യാദവ് നയിച്ച ഇന്ത്യ ജേതാക്കളായി. കിരീടം നിലനിർത്തുന്ന ആദ്യ ടീം; മലയാളി സഞ്ജു സാംസൺ ടൂർണമെന്റിലെ താരം.", "source": "Al Jazeera", "url": "https://www.aljazeera.com/sports/2026/3/8/t20-world-cup-final-india-defeat-new-zealand-by-96-runs-for-third-title"},
  {"topic": "ആനുകാലികം", "title": "2024 ടി20 ലോകകപ്പ്: ഇന്ത്യ ജേതാക്കൾ", "body": "2024 ജൂൺ 29-ന് ബാർബഡോസിലെ കെൻസിങ്ടൺ ഓവലിൽ ദക്ഷിണാഫ്രിക്കയെ 7 റൺസിന് തോൽപ്പിച്ച് രോഹിത് ശർമ നയിച്ച ഇന്ത്യ ടി20 ലോകകപ്പ് നേടി. ഫൈനലിലെ താരം വിരാട് കോഹ്‌ലി (59 പന്തിൽ 76 റൺസ്).", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/2024_ICC_Men%27s_T20_World_Cup_final"}],
 [{"topic": "General English", "title": "Question tags: positive ↔ negative", "body": "A positive statement takes a negative tag and a negative statement a positive tag: 'She's a doctor, isn't she?' / 'He isn't here, is he?' With no auxiliary, use do/does/did: 'Children play football, don't they?' (വാലറ്റ ചോദ്യം)", "source": "British Council", "url": "https://learnenglish.britishcouncil.org/grammar/b1-b2-grammar/question-tags"},
  {"topic": "General English", "title": "Tags after nobody, never, nothing", "body": "Never, nobody, nothing and none make a sentence negative, so the tag is positive: 'Nobody has called, have they?', 'Nobody wants to be poor, do they?', 'He said nothing, did he?' Nobody/everyone take 'they' in the tag.", "source": "British Council", "url": "https://learnenglish.britishcouncil.org/grammar/b1-b2-grammar/question-tags"},
  {"topic": "General English", "title": "Tags with I am, Let's and imperatives", "body": "'I am …' usually takes 'aren't I?' (I am elder to you, aren't I?). 'Let's …' always takes 'shall we?' (Let's go for a walk, shall we?). An imperative takes 'will you?' or 'won't you?' (Open the door, will you?).", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Tag_question"},
  {"topic": "General English", "title": "Either…or / Neither…nor: nearer subject", "body": "With subjects joined by or/nor, the verb agrees with the subject nearer to it: 'Neither the girl nor her brothers have passed'; 'Either the students or their teacher has to come.' Two singulars take a singular verb: 'Neither Seena nor Reena swims well.'", "source": "Purdue OWL", "url": "https://owl.purdue.edu/owl/general_writing/grammar/subject_verb_agreement.html"},
  {"topic": "General English", "title": "Each, one of, as well as: singular verb", "body": "Each, neither, everyone and no one take a singular verb: 'Each of these workers is genial.' 'One of the men has reached the top.' 'As well as' doesn't change the subject: 'The leader, as well as his brothers, belongs to the tribe.'", "source": "Purdue OWL", "url": "https://owl.purdue.edu/owl/general_writing/grammar/subject_verb_agreement.html"},
  {"topic": "General English", "title": "Passive voice: continuous and perfect", "body": "Passive = be + past participle (V3). Continuous: is/was being + V3 ('She is teaching Maths' → 'Maths is being taught by her'). Perfect: has/have been + V3 ('They have appointed him' → 'He has been appointed'). Future: will be + V3. (കർമണി പ്രയോഗം)", "source": "British Council", "url": "https://learnenglish.britishcouncil.org/grammar/b1-b2-grammar/passives"},
  {"topic": "General English", "title": "Reported speech: tense backshift", "body": "After a past reporting verb, tenses move back: present → past; past simple/present perfect → past perfect. 'I bought a house' → He said that he had bought a house. Tomorrow → the next day, yesterday → the day before. A fact still true may stay in the present.", "source": "British Council", "url": "https://learnenglish.britishcouncil.org/grammar/b1-b2-grammar/reported-speech-1-statements"},
  {"topic": "General English", "title": "Reported questions and requests", "body": "Yes/no questions use if/whether: 'Have you read Othello?' → The teacher asked me whether I had read Othello. Wh-questions keep the wh-word with statement order: Priya asked him why he was working so hard. Requests: ask + object + to-infinitive.", "source": "British Council", "url": "https://learnenglish.britishcouncil.org/grammar/b1-b2-grammar/reported-speech-2-questions"},
  {"topic": "General English", "title": "Conditionals: If I were… / If I had…", "body": "Second conditional (imaginary present): If + past simple, would + verb – 'If I were rich, I would help everyone.' Third conditional (unreal past): If + had + V3, would have + V3 – 'If you had started early, you would have reached on time.'", "source": "British Council", "url": "https://learnenglish.britishcouncil.org/grammar/b1-b2-grammar/conditionals-third-mixed"},
  {"topic": "General English", "title": "A or an? Go by the sound", "body": "Choose 'a' before a consonant sound and 'an' before a vowel sound – the sound, not the spelling, decides: a university (yoo- sound), an hour, an honest man (silent h). PSC often asks 'He is ___ honest man' → an. (ഉച്ചാരണം നോക്കി)", "source": "British Council", "url": "https://learnenglish.britishcouncil.org/grammar/a1-a2-grammar/articles-a-an-the"}],
 [{"topic": "സാമ്പത്തികശാസ്ത്രം", "title": "ആസൂത്രണ കമ്മീഷൻ: 1950 മാർച്ച് 15", "body": "ഇന്ത്യൻ ആസൂത്രണ കമ്മീഷൻ 1950 മാർച്ച് 15-ന് നിലവിൽ വന്നു. പ്രധാനമന്ത്രിയായിരുന്നു എക്സ്-ഒഫീഷ്യോ ചെയർമാൻ; ആദ്യ ചെയർമാൻ ജവഹർലാൽ നെഹ്റു. ഭരണഘടനാ സ്ഥാപനമോ നിയമാധിഷ്ഠിത സ്ഥാപനമോ ആയിരുന്നില്ല. ആസ്ഥാനം യോജന ഭവൻ.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Planning_Commission_(India)"},
  {"topic": "സാമ്പത്തികശാസ്ത്രം", "title": "ആസൂത്രണ കമ്മീഷൻ ആദ്യ ഉപാധ്യക്ഷൻ: നന്ദ", "body": "ആസൂത്രണ കമ്മീഷന്റെ ഉപാധ്യക്ഷ പദവി ആദ്യമായി വഹിച്ചത് ഗുൽസാരിലാൽ നന്ദ (1953 ഫെബ്രുവരി 17 – 1963 സെപ്റ്റംബർ 21). പിൻഗാമി വി.ടി. കൃഷ്ണമാചാരി. നന്ദ പിന്നീട് രണ്ടുതവണ ഇടക്കാല പ്രധാനമന്ത്രിയുമായി.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Gulzarilal_Nanda"},
  {"topic": "സാമ്പത്തികശാസ്ത്രം", "title": "നീതി ആയോഗ്: 2015 ജനുവരി 1", "body": "ആസൂത്രണ കമ്മീഷന് പകരം 2015 ജനുവരി 1-ന് കേന്ദ്രമന്ത്രിസഭാ പ്രമേയത്തിലൂടെ നീതി ആയോഗ് നിലവിൽ വന്നു. പൂർണരൂപം: National Institution for Transforming India. പ്രധാനമന്ത്രിയാണ് എക്സ്-ഒഫീഷ്യോ ചെയർപേഴ്സൺ; ആസ്ഥാനം ന്യൂഡൽഹി.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/NITI_Aayog"},
  {"topic": "സാമ്പത്തികശാസ്ത്രം", "title": "ദേശീയ വികസന സമിതി (NDC): 1952", "body": "പഞ്ചവത്സര പദ്ധതികൾക്ക് പിന്തുണ ഉറപ്പാക്കാൻ 1952 ഓഗസ്റ്റ് 6-ന് ദേശീയ വികസന സമിതി (National Development Council) രൂപീകരിച്ചു. പ്രധാനമന്ത്രിയാണ് അധ്യക്ഷൻ; ദേശീയ പദ്ധതി പരിഗണിക്കുകയും പുരോഗതി അവലോകനം ചെയ്യുകയുമായിരുന്നു ചുമതല.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/National_Development_Council_(India)"},
  {"topic": "സാമ്പത്തികശാസ്ത്രം", "title": "ഒന്നാം പഞ്ചവത്സര പദ്ധതി: ഹാരോഡ്-ഡോമർ മാതൃക", "body": "ഒന്നാം പഞ്ചവത്സര പദ്ധതി (1951–56) ഹാരോഡ്-ഡോമർ മാതൃകയെ (ചില മാറ്റങ്ങളോടെ) അടിസ്ഥാനമാക്കിയായിരുന്നു. കൃഷിക്കും പ്രാഥമിക മേഖലയ്ക്കുമായിരുന്നു മുൻഗണന.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Five-Year_Plans_of_India"},
  {"topic": "സാമ്പത്തികശാസ്ത്രം", "title": "രണ്ടാം പദ്ധതി: മഹലനോബിസ് മാതൃക", "body": "രണ്ടാം പഞ്ചവത്സര പദ്ധതി (1956–61) പി.സി. മഹലനോബിസ് 1953-ൽ വികസിപ്പിച്ച മാതൃക പിന്തുടർന്നു. പൊതുമേഖലയ്ക്കും ദ്രുത വ്യവസായവൽക്കരണത്തിനും (ഘനവ്യവസായം) ആയിരുന്നു ഊന്നൽ.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Five-Year_Plans_of_India"},
  {"topic": "സാമ്പത്തികശാസ്ത്രം", "title": "12-ാം പദ്ധതി: അവസാന പഞ്ചവത്സര പദ്ധതി", "body": "2012–2017 കാലത്തെ 12-ാം പഞ്ചവത്സര പദ്ധതിയായിരുന്നു ഇന്ത്യയിലെ അവസാനത്തേത്; 2017-ൽ പഞ്ചവത്സര പദ്ധതികൾ നിർത്തലാക്കി. 9% വളർച്ചാലക്ഷ്യം ദേശീയ വികസന സമിതി 8% ആയി അംഗീകരിച്ചു.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Five-Year_Plans_of_India"},
  {"topic": "സാമ്പത്തികശാസ്ത്രം", "title": "ബാങ്ക് ദേശസാൽക്കരണം: 1969, 1980", "body": "1969 ജൂലൈ 19-ന് ഇന്ദിരാഗാന്ധി സർക്കാർ ഓർഡിനൻസിലൂടെ 14 പ്രധാന വാണിജ്യ ബാങ്കുകൾ ദേശസാൽക്കരിച്ചു. 1980-ൽ 6 ബാങ്കുകൾ കൂടി ദേശസാൽക്കരിച്ചതോടെ ബാങ്കിങ് ബിസിനസിന്റെ ഏകദേശം 91% സർക്കാർ നിയന്ത്രണത്തിലായി.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Nationalisation_of_banks_in_India"},
  {"topic": "സാമ്പത്തികശാസ്ത്രം", "title": "ഇംപീരിയൽ ബാങ്ക് SBI ആയത് 1955-ൽ", "body": "ബംഗാൾ, ബോംബെ, മദ്രാസ് എന്നീ മൂന്ന് പ്രസിഡൻസി ബാങ്കുകൾ ലയിച്ച് 1921 ജനുവരി 27-ന് ഇംപീരിയൽ ബാങ്ക് ഓഫ് ഇന്ത്യ രൂപംകൊണ്ടു. 1955 ജൂലൈ 1-ന് ഇത് സ്റ്റേറ്റ് ബാങ്ക് ഓഫ് ഇന്ത്യയായി; ആസ്ഥാനം മുംബൈ.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/State_Bank_of_India"},
  {"topic": "സാമ്പത്തികശാസ്ത്രം", "title": "RBI: ആദ്യ ഗവർണറും ആദ്യ ഇന്ത്യക്കാരനും", "body": "റിസർവ് ബാങ്കിന്റെ ആദ്യ ഗവർണർ ഓസ്ബോൺ സ്മിത്ത് (1935–37). ആദ്യ ഇന്ത്യക്കാരനായ ഗവർണർ സി.ഡി. ദേശ്മുഖ് (1943–49). പിന്നീട് പ്രധാനമന്ത്രിയായ മൻമോഹൻ സിങ്ങും (1982–85) RBI ഗവർണറായിരുന്നു.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/List_of_governors_of_the_Reserve_Bank_of_India"}],
 [{"topic": "കമ്പ്യൂട്ടർ അടിസ്ഥാനങ്ങൾ", "title": "കമ്പ്യൂട്ടറിന്റെ പിതാവ്: ചാൾസ് ബാബേജ്", "body": "കമ്പ്യൂട്ടറിന്റെ പിതാവായി കണക്കാക്കുന്നത് ചാൾസ് ബാബേജിനെ. 1822-ൽ ഡിഫറൻസ് എഞ്ചിൻ നിർമാണം തുടങ്ങി; പിന്നീട് പഞ്ച്ഡ് കാർഡുകൾകൊണ്ട് പ്രോഗ്രാം ചെയ്യാവുന്ന പൊതു-ആവശ്യ യന്ത്രമായ അനലിറ്റിക്കൽ എഞ്ചിൻ രൂപകൽപ്പന ചെയ്തു.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Charles_Babbage"},
  {"topic": "കമ്പ്യൂട്ടർ അടിസ്ഥാനങ്ങൾ", "title": "CPU: ALU-വും കൺട്രോൾ യൂണിറ്റും", "body": "കമ്പ്യൂട്ടറിന്റെ തലച്ചോറായ CPU-വിന്റെ പ്രധാന ഭാഗങ്ങൾ: കണക്കുകൂട്ടലുകളും താരതമ്യങ്ങളും നടത്തുന്ന ALU (Arithmetic Logic Unit), പ്രവർത്തനങ്ങൾ ഏകോപിപ്പിക്കുന്ന കൺട്രോൾ യൂണിറ്റ് (CU), ഡാറ്റ താൽക്കാലികമായി സൂക്ഷിക്കുന്ന രജിസ്റ്ററുകൾ.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Central_processing_unit"},
  {"topic": "കമ്പ്യൂട്ടർ അടിസ്ഥാനങ്ങൾ", "title": "ബിറ്റ്, നിബിൾ, ബൈറ്റ്", "body": "ബൈനറി അക്കമായ 0 അല്ലെങ്കിൽ 1 ആണ് ബിറ്റ്. 4 ബിറ്റ് = 1 നിബിൾ, 8 ബിറ്റ് = 1 ബൈറ്റ്. മെമ്മറിയുടെ ബൈനറി കണക്കിൽ 1 KB = 1024 ബൈറ്റ്, 1 GB = 1024 MB (2³⁰ ബൈറ്റ്). 'ബൈറ്റ്' എന്ന പദം 1956-ൽ വെർണർ ബുക്ഹോൾസ് രൂപപ്പെടുത്തി.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Byte"},
  {"topic": "കമ്പ്യൂട്ടർ അടിസ്ഥാനങ്ങൾ", "title": "ROM: വൈദ്യുതി പോയാലും മായില്ല", "body": "ROM (Read Only Memory) അസ്ഥിരമല്ലാത്ത (non-volatile) മെമ്മറിയാണ്; ഫേംവെയർ/BIOS സൂക്ഷിക്കുന്നു. PROM ഒരിക്കൽ മാത്രം പ്രോഗ്രാം ചെയ്യാം; EPROM അൾട്രാവയലറ്റ് പ്രകാശംകൊണ്ടും EEPROM വൈദ്യുതികൊണ്ടും മായ്ക്കാം.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Read-only_memory"},
  {"topic": "കമ്പ്യൂട്ടർ അടിസ്ഥാനങ്ങൾ", "title": "കാഷ് മെമ്മറി: പ്രോസസറിന് ഏറ്റവും അടുത്ത്", "body": "പ്രോസസറിന് തൊട്ടടുത്തുള്ള, പ്രധാന മെമ്മറിയെക്കാൾ (RAM) വേഗമേറിയ ചെറിയ മെമ്മറിയാണ് കാഷ്. പതിവായി ഉപയോഗിക്കുന്ന ഡാറ്റയുടെ പകർപ്പ് സൂക്ഷിക്കുന്നു. L1, L2, L3 എന്നീ തട്ടുകൾ; സാധാരണ SRAM കൊണ്ട് നിർമിക്കുന്നു.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/CPU_cache"},
  {"topic": "കമ്പ്യൂട്ടർ അടിസ്ഥാനങ്ങൾ", "title": "ഓപ്പറേറ്റിങ് സിസ്റ്റം: സിസ്റ്റം സോഫ്റ്റ്‌വെയർ", "body": "മറ്റ് സോഫ്റ്റ്‌വെയറുകൾക്ക് പ്രവർത്തിക്കാനുള്ള അടിത്തറ നൽകുന്നവയാണ് സിസ്റ്റം സോഫ്റ്റ്‌വെയർ: ഓപ്പറേറ്റിങ് സിസ്റ്റം, ഡിവൈസ് ഡ്രൈവറുകൾ, യൂട്ടിലിറ്റികൾ, ഭാഷാ ട്രാൻസ്ലേറ്ററുകൾ. വേഡ് പ്രോസസർ, ബ്രൗസർ എന്നിവ ആപ്ലിക്കേഷൻ സോഫ്റ്റ്‌വെയറാണ്.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/System_software"},
  {"topic": "കമ്പ്യൂട്ടർ അടിസ്ഥാനങ്ങൾ", "title": "BOSS: C-DAC-ന്റെ ഇന്ത്യൻ ലിനക്സ്", "body": "BOSS (Bharat Operating System Solutions) C-DAC വികസിപ്പിച്ച, ഡെബിയൻ അടിസ്ഥാനമാക്കിയ ഇന്ത്യൻ GNU/Linux വിതരണം. 2007-ൽ ആദ്യ പതിപ്പ്; ഇന്ത്യയിൽ സ്വതന്ത്ര-ഓപ്പൺ സോഴ്സ് സോഫ്റ്റ്‌വെയർ പ്രോത്സാഹിപ്പിക്കുകയാണ് ലക്ഷ്യം.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Bharat_Operating_System_Solutions"},
  {"topic": "കമ്പ്യൂട്ടർ അടിസ്ഥാനങ്ങൾ", "title": "കമ്പൈലറും ഇന്റർപ്രെട്ടറും", "body": "ഹൈ-ലെവൽ ഭാഷയിലെ സോഴ്സ് കോഡ് മുഴുവൻ മെഷീൻ കോഡിലേക്ക് മാറ്റി എക്സിക്യൂട്ടബിൾ പ്രോഗ്രാം ഉണ്ടാക്കുന്നത് കമ്പൈലർ. മുൻകൂട്ടി മെഷീൻ കോഡാക്കാതെ നേരിട്ട് പ്രോഗ്രാം പ്രവർത്തിപ്പിക്കുന്നത് ഇന്റർപ്രെട്ടർ; കമ്പൈൽ ചെയ്ത കോഡ് പൊതുവേ വേഗം കൂടിയതാണ്.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Compiler"},
  {"topic": "കമ്പ്യൂട്ടർ അടിസ്ഥാനങ്ങൾ", "title": "WWW: ടിം ബെർണേഴ്സ് ലീ, CERN", "body": "വേൾഡ് വൈഡ് വെബ് ആവിഷ്കരിച്ചത് ടിം ബെർണേഴ്സ് ലീ; 1989 മാർച്ചിൽ CERN-ൽ നിർദേശം സമർപ്പിച്ചു. HTML, URL, HTTP എന്നിവയാണ് അടിസ്ഥാന ഘടകങ്ങൾ. 1991-ൽ പൊതുജനങ്ങൾക്ക് ലഭ്യമായി; 1993-ൽ CERN ഇത് റോയൽറ്റി രഹിതമാക്കി.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/World_Wide_Web"},
  {"topic": "കമ്പ്യൂട്ടർ അടിസ്ഥാനങ്ങൾ", "title": "HTTP: വെബിന്റെ പ്രോട്ടോക്കോൾ", "body": "HTTP (Hypertext Transfer Protocol) വേൾഡ് വൈഡ് വെബിലെ ഡാറ്റാ വിനിമയത്തിന്റെ അടിസ്ഥാന പ്രോട്ടോക്കോൾ; എൻക്രിപ്റ്റ് ചെയ്ത സുരക്ഷിത രൂപം HTTPS. സാധാരണ പോർട്ട് 80, HTTPS-ന് 443. ടിം ബെർണേഴ്സ് ലീയും സംഘവും CERN-ൽ 1989-ൽ വികസിപ്പിച്ചുതുടങ്ങി.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/HTTP"}],
 [{"topic": "കേരള ഭൂമിശാസ്ത്രം", "title": "ശാസ്താംകോട്ട: വലിയ ശുദ്ധജല തടാകം", "body": "കൊല്ലം ജില്ലയിലെ ശാസ്താംകോട്ട കായലാണ് കേരളത്തിലെ ഏറ്റവും വലിയ ശുദ്ധജല തടാകം. 2002-ൽ റാംസർ സൈറ്റായി പ്രഖ്യാപിച്ചു; തീരത്തെ പുരാതന ശാസ്താക്ഷേത്രത്തിൽനിന്നാണ് പേര്. കൊല്ലം മേഖലയുടെ പ്രധാന കുടിവെള്ള സ്രോതസ്സുമാണ്.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Sasthamcotta_Lake"},
  {"topic": "കേരള ഭൂമിശാസ്ത്രം", "title": "പാതിരാമണൽ: വേമ്പനാട്ടിലെ ദ്വീപ്", "body": "ആലപ്പുഴ ജില്ലയിലെ മുഹമ്മ പഞ്ചായത്തിൽ, വേമ്പനാട്ട് കായലിലുള്ള ചെറുദ്വീപാണ് പാതിരാമണൽ; കുമരകത്തിന് സമീപമാണിത്. ‘പാതിരാമണൽ’ എന്നാൽ ‘അർധരാത്രിയിലെ മണൽ’; നാടൻ-ദേശാടന പക്ഷികളുടെ പ്രധാന താവളമാണ്.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Pathiramanal"},
  {"topic": "കേരള ഭൂമിശാസ്ത്രം", "title": "കുറുവ ദ്വീപ്: കബനി നദിയിൽ", "body": "വയനാട് ജില്ലയിൽ കബനി നദിയിലുള്ള ജനവാസമില്ലാത്ത ദ്വീപസമൂഹമാണ് കുറുവ ദ്വീപ്. ഏകദേശം 3.8 ച.കി.മീ. വിസ്തൃതിയുള്ള ഈ സംരക്ഷിത നദീതട പ്രദേശം അപൂർവ പക്ഷികളുടെയും ശലഭങ്ങളുടെയും ആവാസകേന്ദ്രമാണ്.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Kuruva_Island"},
  {"topic": "കേരള ഭൂമിശാസ്ത്രം", "title": "ചിന്നാർ: മഴനിഴലിലെ വന്യജീവി സങ്കേതം", "body": "ഇടുക്കി ജില്ലയിലെ ചിന്നാർ വന്യജീവി സങ്കേതം (1984) പശ്ചിമഘട്ടത്തിന്റെ മഴനിഴൽ പ്രദേശത്താണ്; വാർഷിക മഴ ഏകദേശം 500 മി.മീ. മാത്രം. ചാമ്പൽ മലയണ്ണാനും നക്ഷത്ര ആമയും ഇവിടെയുണ്ട്; നക്ഷത്ര ആമകളുടെ പുനരധിവാസ കേന്ദ്രവും ഇവിടെയാണ്.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Chinnar_Wildlife_Sanctuary"},
  {"topic": "കേരള ഭൂമിശാസ്ത്രം", "title": "ശെന്തുരുണി: കൊല്ലം ജില്ലയിൽ", "body": "കൊല്ലം ജില്ലയിലാണ് ശെന്തുരുണി വന്യജീവി സങ്കേതം (1984). പ്രദേശത്തു മാത്രം കാണുന്ന ‘ചെങ്കുറിഞ്ഞി’ (Gluta travancorica) എന്ന മരത്തിൽനിന്നാണ് പേര്; തെന്മല അണക്കെട്ടിന്റെ ജലസംഭരണി സങ്കേതത്തോട് ചേർന്നുകിടക്കുന്നു.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Shendurney_Wildlife_Sanctuary"},
  {"topic": "കേരള ഭൂമിശാസ്ത്രം", "title": "ഇടുക്കി ആർച്ച് ഡാം: കുറവൻ-കുറത്തി മലകൾ", "body": "പെരിയാറിൽ കുറവൻ, കുറത്തി മലകൾക്കിടയിലെ ഇടുക്കമായ മലയിടുക്കിലാണ് ഇടുക്കി ആർച്ച് ഡാം (ഉയരം 168.91 മീ.). കാനഡയുടെ സഹായത്തോടെ നിർമിച്ച പദ്ധതി 1976-ൽ ഇന്ദിരാഗാന്ധി ഉദ്ഘാടനം ചെയ്തു; വൈദ്യുതനിലയം മൂലമറ്റത്ത് ഭൂഗർഭത്തിലാണ്.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Idukki_Dam"},
  {"topic": "കേരള ഭൂമിശാസ്ത്രം", "title": "കല്ലട: ഏറ്റവും വലിയ ജലസേചന പദ്ധതി", "body": "കൊല്ലം ജില്ലയിൽ കല്ലടയാറിലെ തെന്മല (പരപ്പാർ) അണക്കെട്ട് ഉൾപ്പെടുന്ന കല്ലട ജലസേചന പദ്ധതിയാണ് കേരളത്തിലെ ഏറ്റവും വലിയ ജലസേചന പദ്ധതി. അണക്കെട്ട് 1986-ൽ കമ്മീഷൻ ചെയ്തു; 1998-ൽ തുടങ്ങിയ തെന്മല ഇന്ത്യയിലെ ആദ്യ ആസൂത്രിത ഇക്കോടൂറിസം പദ്ധതിയാണ്.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Thenmala_Dam"},
  {"topic": "കേരള ഭൂമിശാസ്ത്രം", "title": "പാൽച്ചുരം: വയനാട്-കണ്ണൂർ", "body": "വയനാട് ജില്ലയെ കണ്ണൂർ ജില്ലയുമായി ബന്ധിപ്പിക്കുന്ന ചുരമാണ് പാൽച്ചുരം. മാനന്തവാടിയിൽനിന്ന് ഏകദേശം 22 കി.മീ. അകലെയുള്ള ഇവിടെനിന്ന് ഹെയർപിൻ വളവുകളുള്ള റോഡ് കണ്ണൂരിലെ കൊട്ടിയൂരിലേക്ക് ഇറങ്ങുന്നു. (കോഴിക്കോട്-വയനാട് ബന്ധം താമരശ്ശേരി ചുരം വഴിയാണ്.)", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Palchuram"},
  {"topic": "കേരള ഭൂമിശാസ്ത്രം", "title": "ആലപ്പുഴ: ഏറ്റവും ചെറിയ ജില്ല", "body": "വിസ്തൃതിയിൽ കേരളത്തിലെ ഏറ്റവും ചെറിയ ജില്ലയാണ് ആലപ്പുഴ (ഏകദേശം 1,414 ച.കി.മീ.). വനഭൂമിയില്ലാത്ത ഏക ജില്ല എന്നായിരുന്നു പഴയ ചോദ്യം; 2013-ൽ വീയപുരത്ത് 14.5 ഏക്കർ സംരക്ഷിത വനമായി പ്രഖ്യാപിച്ചു. ‘കിഴക്കിന്റെ വെനീസ്’ എന്ന് കഴ്സൺ വിശേഷിപ്പിച്ചു.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Alappuzha_district"},
  {"topic": "കേരള ഭൂമിശാസ്ത്രം", "title": "കണ്ണൂർ: ഉയർന്ന സ്ത്രീ-പുരുഷ അനുപാതം", "body": "2011 സെൻസസ് പ്രകാരം കേരളത്തിൽ ഏറ്റവും ഉയർന്ന സ്ത്രീ-പുരുഷ അനുപാതം കണ്ണൂർ ജില്ലയിലാണ്; ഏറ്റവും കുറവ് ഇടുക്കിയിൽ (1,006). സംസ്ഥാനത്തിന്റെ ശരാശരി 1,000 പുരുഷന്മാർക്ക് 1,084 സ്ത്രീകൾ.", "source": "Maps of India (Census 2011)", "url": "https://www.mapsofindia.com/census2011/kerala-sex-ratio.html"}],
 [{"topic": "ഇന്ത്യൻ-ലോക ഭൂമിശാസ്ത്രം", "title": "K2 (ഗോഡ്വിൻ ഓസ്റ്റിൻ): 8,611 മീറ്റർ", "body": "കാരക്കോറം നിരയിലെ K2 അഥവാ ഗോഡ്വിൻ ഓസ്റ്റിൻ (8,611 മീ.) ലോകത്തിലെ രണ്ടാമത്തെ ഉയരം കൂടിയ കൊടുമുടിയാണ്; ഇന്ത്യ അവകാശപ്പെടുന്ന പ്രദേശത്തെ ഏറ്റവും ഉയർന്ന കൊടുമുടിയായി പരീക്ഷകളിൽ ചോദിക്കുന്നു. ‘സാവേജ് മൗണ്ടൻ’ എന്ന വിളിപ്പേരുണ്ട്.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/K2"},
  {"topic": "ഇന്ത്യൻ-ലോക ഭൂമിശാസ്ത്രം", "title": "ഭക്രാ അണക്കെട്ട്: സത്‌ലജ് നദി", "body": "ഹിമാചൽ പ്രദേശിലെ ബിലാസ്പൂരിൽ സത്‌ലജ് നദിയിലാണ് ഭക്രാ അണക്കെട്ട് (226 മീ., 1963). ജലസംഭരണിയുടെ പേര് ഗോബിന്ദ് സാഗർ. നെഹ്റു ഇതിനെ ‘പുനരുജ്ജീവിക്കുന്ന ഇന്ത്യയുടെ പുതിയ ക്ഷേത്രം’ എന്നു വിശേഷിപ്പിച്ചു.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Bhakra_Dam"},
  {"topic": "ഇന്ത്യൻ-ലോക ഭൂമിശാസ്ത്രം", "title": "ഹിരാക്കുഡ്: മഹാനദിയിലെ അണക്കെട്ട്", "body": "ഒഡീഷയിലെ സംബൽപൂരിന് സമീപം മഹാനദിയിലാണ് ഹിരാക്കുഡ് അണക്കെട്ട്. ലോകത്തിലെ ഏറ്റവും നീളം കൂടിയ മൺ അണക്കെട്ടുകളിൽ ഒന്നായ ഇതിന്റെ പ്രധാന ഭാഗം 4.8 കി.മീ.; അനുബന്ധ ബണ്ടുകൾ ഉൾപ്പെടെ 25.8 കി.മീ. 1957-ൽ ഉദ്ഘാടനം ചെയ്തു.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Hirakud_Dam"},
  {"topic": "ഇന്ത്യൻ-ലോക ഭൂമിശാസ്ത്രം", "title": "സർദാർ സരോവർ: നർമദയിൽ", "body": "ഗുജറാത്തിലെ നർമദ ജില്ലയിൽ കെവാഡിയയ്ക്ക് സമീപം നർമദ നദിയിലാണ് സർദാർ സരോവർ അണക്കെട്ട്; 2017 സെപ്റ്റംബർ 17-ന് ഉദ്ഘാടനം ചെയ്തു. ഗുജറാത്ത്, മധ്യപ്രദേശ്, മഹാരാഷ്ട്ര, രാജസ്ഥാൻ എന്നിവയ്ക്ക് ഗുണം; സ്റ്റാച്യു ഓഫ് യൂണിറ്റി തൊട്ടടുത്താണ്.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Sardar_Sarovar_Dam"},
  {"topic": "ഇന്ത്യൻ-ലോക ഭൂമിശാസ്ത്രം", "title": "ബ്രഹ്മപുത്ര: പല പേരുകളുള്ള നദി", "body": "ബ്രഹ്മപുത്ര ടിബറ്റിൽ യാർലുങ് സാങ്പോ, അരുണാചലിൽ സിയാങ്/ദിഹാങ്, ബംഗ്ലാദേശിൽ ജമുന എന്നിങ്ങനെ അറിയപ്പെടുന്നു. ‘ഇന്ത്യയുടെ ചുവന്ന നദി’ എന്നു വിളിക്കപ്പെടുന്നു; ‘ബ്രഹ്മാവിന്റെ പുത്രൻ’ എന്നർഥമുള്ള പേര് പുരുഷനാമമാണ്.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Brahmaputra_River"},
  {"topic": "ഇന്ത്യൻ-ലോക ഭൂമിശാസ്ത്രം", "title": "ഗംഗയുടെ ഉത്ഭവം: ഗോമുഖ്", "body": "ഗംഗയുടെ പ്രധാന ശാഖയായ ഭാഗീരഥി ഉത്തരാഖണ്ഡിലെ ഗംഗോത്രി ഹിമാനിയുടെ അടിവാരത്തുള്ള ഗോമുഖിൽ ഉത്ഭവിക്കുന്നു. ദേവപ്രയാഗിൽ അളകനന്ദയുമായി ചേരുന്നതോടെ ഗംഗ എന്ന പേര് ലഭിക്കുന്നു; ബംഗ്ലാദേശിൽ പത്മ എന്നറിയപ്പെടുന്നു.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Ganges"},
  {"topic": "ഇന്ത്യൻ-ലോക ഭൂമിശാസ്ത്രം", "title": "മാജുലി: ആദ്യ ദ്വീപ് ജില്ല", "body": "ആസാമിൽ ബ്രഹ്മപുത്രയിലുള്ള മാജുലിയെ ഏറ്റവും വലിയ നദീദ്വീപായി ഗിന്നസ് വേൾഡ് റെക്കോർഡ്സ് അംഗീകരിച്ചിട്ടുണ്ട്. 2016-ൽ ഇന്ത്യയിലെ ആദ്യ ദ്വീപ് ജില്ലയായി; ശങ്കരദേവന്റെ വൈഷ്ണവ ‘സത്ര’കൾക്ക് പ്രസിദ്ധം.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Majuli"},
  {"topic": "ഇന്ത്യൻ-ലോക ഭൂമിശാസ്ത്രം", "title": "ബാരൻ ദ്വീപ്: സജീവ അഗ്നിപർവതം", "body": "ആൻഡമാൻ കടലിലെ ബാരൻ ദ്വീപിലാണ് ഇന്ത്യൻ ഉപഭൂഖണ്ഡത്തിലെ സ്ഥിരീകരിക്കപ്പെട്ട ഏക സജീവ അഗ്നിപർവതം. പോർട്ട് ബ്ലെയറിൽനിന്ന് ഏകദേശം 138 കി.മീ. വടക്കുകിഴക്കുള്ള ഈ ദ്വീപിൽ ജനവാസമില്ല.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Barren_Island_(Andaman_Islands)"},
  {"topic": "ഇന്ത്യൻ-ലോക ഭൂമിശാസ്ത്രം", "title": "നർമദ: പടിഞ്ഞാറോട്ടൊഴുകുന്ന വലിയ നദി", "body": "മധ്യപ്രദേശിലെ അമർകണ്ടകിൽ ഉത്ഭവിക്കുന്ന നർമദ (ഏകദേശം 1,312 കി.മീ.) ഇന്ത്യയിലെ ഏറ്റവും നീളം കൂടിയ പടിഞ്ഞാറോട്ടൊഴുകുന്ന നദിയാണ്. വിന്ധ്യ-സത്പുര നിരകൾക്കിടയിലെ ഭ്രംശതാഴ്വരയിലൂടെ ഒഴുകി ഖംഭാത് ഉൾക്കടലിൽ (അറബിക്കടൽ) പതിക്കുന്നതിനാൽ ഡെൽറ്റയല്ല, അഴിമുഖമാണ്.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Narmada_River"},
  {"topic": "ഇന്ത്യൻ-ലോക ഭൂമിശാസ്ത്രം", "title": "നാഥുലാ ചുരം: സിക്കിം-ടിബറ്റ്", "body": "സിക്കിമിനെ ടിബറ്റുമായി (ചൈന) ബന്ധിപ്പിക്കുന്ന ഹിമാലയൻ ചുരമാണ് നാഥുലാ (ഏകദേശം 4,310 മീ.). 1962-ലെ യുദ്ധത്തിനുശേഷം അടച്ച ചുരം 2006 ജൂലൈ 6-ന് വ്യാപാരത്തിനായി വീണ്ടും തുറന്നു; കൈലാസ്-മാനസരോവർ തീർഥാടനത്തിനും ഉപയോഗിക്കുന്നു.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Nathu_La"}],
 [{"topic": "ഇന്ത്യൻ ചരിത്രം", "title": "ലാഹോർ സമ്മേളനം 1929: പൂർണ്ണസ്വരാജ്", "body": "1929 ഡിസംബറിലെ ലാഹോർ കോൺഗ്രസ് സമ്മേളനം ജവഹർലാൽ നെഹ്റുവിന്റെ അധ്യക്ഷതയിൽ പൂർണ്ണസ്വരാജ് ലക്ഷ്യമായി പ്രഖ്യാപിച്ചു. 1929 ഡിസംബർ 31-ന് രാവി തീരത്ത് നെഹ്റു ത്രിവർണ്ണപതാക ഉയർത്തി; 1930 ജനുവരി 26 സ്വാതന്ത്ര്യദിനമായി ആചരിച്ചു.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Purna_Swaraj"},
  {"topic": "ഇന്ത്യൻ ചരിത്രം", "title": "ബെൽഗാം സമ്മേളനം 1924: അധ്യക്ഷൻ ഗാന്ധിജി", "body": "1924 ഡിസംബറിൽ ബെൽഗാമിൽ നടന്ന ഇന്ത്യൻ നാഷണൽ കോൺഗ്രസ് സമ്മേളനത്തിൽ മഹാത്മാഗാന്ധിയായിരുന്നു അധ്യക്ഷൻ. 1920-ലെ നാഗ്പൂർ സമ്മേളനത്തിന്റെ അധ്യക്ഷൻ സി. വിജയരാഘവാചാര്യർ ആയിരുന്നു.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/List_of_presidents_of_the_Indian_National_Congress"},
  {"topic": "ഇന്ത്യൻ ചരിത്രം", "title": "ദാദാഭായ് നവറോജി: മൂന്നുതവണ കോൺഗ്രസ് അധ്യക്ഷൻ", "body": "ദാദാഭായ് നവറോജി 1886, 1893, 1906 വർഷങ്ങളിൽ കോൺഗ്രസ് അധ്യക്ഷനായി. ‘ഇന്ത്യയുടെ വന്ദ്യവയോധികൻ’ (Grand Old Man of India) എന്നറിയപ്പെടുന്നു; ചോർച്ചാ സിദ്ധാന്തം അവതരിപ്പിച്ച ‘Poverty and Un-British Rule in India’ (1901) രചിച്ചു.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Dadabhai_Naoroji"},
  {"topic": "ഇന്ത്യൻ ചരിത്രം", "title": "ശാശ്വത ഭൂനികുതി വ്യവസ്ഥ: കോൺവാലിസ്, 1793", "body": "ഗവർണർ ജനറൽ കോൺവാലിസ് പ്രഭു 1793-ൽ ബംഗാളിലും ബീഹാറിലും ശാശ്വത ഭൂനികുതി വ്യവസ്ഥ (Permanent Settlement) നടപ്പാക്കി. ഭൂനികുതി സ്ഥിരമായി നിശ്ചയിച്ച് ജമീന്ദാർമാരെ ഭൂവുടമകളായി അംഗീകരിച്ചു.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Permanent_Settlement"},
  {"topic": "ഇന്ത്യൻ ചരിത്രം", "title": "സൈനിക സഹായ വ്യവസ്ഥ: വെല്ലസ്ലി പ്രഭു", "body": "ഗവർണർ ജനറൽ റിച്ചാർഡ് വെല്ലസ്ലി (1798–1805) സൈനിക സഹായ വ്യവസ്ഥയ്ക്ക് (Subsidiary Alliance) വ്യവസ്ഥാപിത രൂപം നൽകി. 1798-ൽ ഇത് ആദ്യമായി അംഗീകരിച്ചത് ഹൈദരാബാദ് നൈസാമാണ്.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Subsidiary_alliance"},
  {"topic": "ഇന്ത്യൻ ചരിത്രം", "title": "ദത്താവകാശ നിരോധനം: ഡൽഹൗസി പ്രഭു", "body": "ഡൽഹൗസി പ്രഭു (1848–1856) ദത്താവകാശ നിരോധന നയം (Doctrine of Lapse) ശക്തമായി നടപ്പാക്കി. സത്താറ (1848), ഝാൻസി, നാഗ്പൂർ തുടങ്ങിയ നാട്ടുരാജ്യങ്ങൾ ഇതുവഴി ബ്രിട്ടീഷ് ഭരണത്തിൽ ചേർത്തു; 1856-ൽ അവധും കൂട്ടിച്ചേർത്തു.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Doctrine_of_lapse"},
  {"topic": "ഇന്ത്യൻ ചരിത്രം", "title": "റെഗുലേറ്റിംഗ് ആക്ട് 1773", "body": "1773-ലെ റെഗുലേറ്റിംഗ് ആക്ട് വഴി വാറൻ ഹേസ്റ്റിംഗ്സ് ബംഗാളിലെ ആദ്യ ഗവർണർ ജനറലായി. ഈ നിയമപ്രകാരം 1774-ൽ കൽക്കത്തയിൽ സുപ്രീം കോടതി സ്ഥാപിച്ചു; ആദ്യ ചീഫ് ജസ്റ്റിസ് സർ ഇലൈജ ഇംപി.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Regulating_Act_of_1773"},
  {"topic": "ഇന്ത്യൻ ചരിത്രം", "title": "1858-ലെ നിയമം: കിരീടഭരണം, കാനിംഗ്", "body": "1857-ലെ കലാപത്തിനുശേഷം 1858-ൽ ഈസ്റ്റിന്ത്യാ കമ്പനിയുടെ ഭരണം ബ്രിട്ടീഷ് കിരീടത്തിന് കൈമാറി. 1856 മുതൽ ഗവർണർ ജനറലായിരുന്ന കാനിംഗ് പ്രഭു അതോടെ ഇന്ത്യയിലെ ആദ്യ വൈസ്രോയിയായി.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Charles_Canning,_1st_Earl_Canning"},
  {"topic": "ഇന്ത്യൻ ചരിത്രം", "title": "ചമ്പാരൻ 1917: ഗാന്ധിജിയുടെ ആദ്യ സത്യാഗ്രഹം", "body": "ഇന്ത്യയിൽ ഗാന്ധിജിയുടെ ആദ്യ സത്യാഗ്രഹം 1917-ൽ ബീഹാറിലെ ചമ്പാരനിലായിരുന്നു. നീലം (ഇൻഡിഗോ) കൃഷി ചെയ്യാൻ നിർബന്ധിതരായ കർഷകർക്കുവേണ്ടിയായിരുന്നു സമരം; ഗാന്ധിജിയെ ക്ഷണിച്ചത് രാജ്കുമാർ ശുക്ല.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Champaran_Satyagraha"},
  {"topic": "ഇന്ത്യൻ ചരിത്രം", "title": "ഗാന്ധി-ഇർവിൻ സന്ധി: 1931 മാർച്ച് 5", "body": "1931 മാർച്ച് 5-ന് ഗാന്ധിജിയും വൈസ്രോയി ഇർവിൻ പ്രഭുവും സന്ധി ഒപ്പുവച്ചു. ഇതോടെ സിവിൽ നിയമലംഘന പ്രസ്ഥാനം നിർത്തിവച്ചു; തുടർന്ന് 1931-ലെ രണ്ടാം വട്ടമേശ സമ്മേളനം ലണ്ടനിൽ നടന്നു.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Gandhi%E2%80%93Irwin_Pact"}],
 [{"topic": "കേരള ചരിത്രം", "title": "കുലശേഖരന്മാരുടെ തലസ്ഥാനം: മഹോദയപുരം", "body": "ചേര പെരുമാക്കൾ (കുലശേഖരന്മാർ) ഏകദേശം 844 മുതൽ 1124 വരെ കേരളം ഭരിച്ചു. തലസ്ഥാനം മഹോദയപുരം (മകോതൈ), ഇന്നത്തെ കൊടുങ്ങല്ലൂർ. ആദ്യ രാജാവ് സ്ഥാണു രവി കുലശേഖരൻ; അവസാനത്തേത് രാമ കുലശേഖരൻ.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Chera_Perumals_of_Makotai"},
  {"topic": "കേരള ചരിത്രം", "title": "തരിസാപ്പള്ളി ശാസനം: 849", "body": "849-ൽ കൊല്ലത്തെ നാടുവാഴി അയ്യനടികൾ തിരുവടികൾ തരിസാപ്പള്ളിക്കുവേണ്ടി മരുവാൻ സപീർ ഈശോയ്ക്ക് നൽകിയ ചെപ്പേടാണ് തരിസാപ്പള്ളി ശാസനം. ചേര രാജാവ് സ്ഥാണു രവിയുടെ അഞ്ചാം ഭരണവർഷത്തിലാണ് ഇത്.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Quilon_Syrian_copper_plates"},
  {"topic": "കേരള ചരിത്രം", "title": "വാസ്കോ ഡ ഗാമ: കാപ്പാട്, 1498", "body": "1498 മെയ് 20-ന് പോർച്ചുഗീസ് നാവികൻ വാസ്കോ ഡ ഗാമ കോഴിക്കോടിനടുത്ത് കാപ്പാട് എത്തി സാമൂതിരിയെ സന്ദർശിച്ചു. 1524 ഡിസംബർ 24-ന് കൊച്ചിയിൽ വച്ച് അദ്ദേഹം അന്തരിച്ചു.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Vasco_da_Gama"},
  {"topic": "കേരള ചരിത്രം", "title": "സെന്റ് ആഞ്ചലോ കോട്ട, കണ്ണൂർ: 1505", "body": "കണ്ണൂരിലെ സെന്റ് ആഞ്ചലോ കോട്ട 1505-ൽ പോർച്ചുഗീസ് വൈസ്രോയി ഫ്രാൻസിസ്കോ ഡി അൽമേഡയുടെ കാലത്ത് നിർമ്മിച്ചു. 1663-ൽ ഡച്ചുകാർ പിടിച്ചെടുത്ത കോട്ട 1772-ൽ അറയ്ക്കൽ രാജാവിന് വിറ്റു; 1790-ൽ ബ്രിട്ടീഷുകാർ കൈവശമാക്കി.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/St._Angelo_Fort"},
  {"topic": "കേരള ചരിത്രം", "title": "ആറ്റിങ്ങൽ കലാപം 1721", "body": "1721-ൽ അഞ്ചുതെങ്ങിലെ ബ്രിട്ടീഷുകാർക്കെതിരെ നടന്ന ആറ്റിങ്ങൽ കലാപം ബ്രിട്ടീഷ് അധികാരത്തിനെതിരെ ഇന്ത്യയിൽ നടന്ന ആദ്യ സംഘടിത കലാപമായി കണക്കാക്കപ്പെടുന്നു. ആറ്റിങ്ങൽ റാണിക്കുള്ള സമ്മാനം സംബന്ധിച്ച തർക്കമായിരുന്നു പെട്ടെന്നുള്ള കാരണം.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Attingal_Outbreak"},
  {"topic": "കേരള ചരിത്രം", "title": "കുളച്ചൽ യുദ്ധം 1741: ഡച്ചുകാരുടെ പരാജയം", "body": "1741 ഓഗസ്റ്റിൽ കുളച്ചൽ യുദ്ധത്തിൽ മാർത്താണ്ഡവർമ്മ ഡച്ച് ഈസ്റ്റിന്ത്യാ കമ്പനിയെ തോൽപ്പിച്ചു. പിടിയിലായ ഡച്ച് സേനാനായകൻ ഡിലനോയ് പിന്നീട് തിരുവിതാംകൂർ സൈന്യത്തിന്റെ ‘വലിയ കപ്പിത്താൻ’ ആയി; ഉദയഗിരി കോട്ട അദ്ദേഹത്തിന് നൽകി.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Battle_of_Colachel"},
  {"topic": "കേരള ചരിത്രം", "title": "തൃപ്പടിദാനം 1750: മാർത്താണ്ഡവർമ്മ", "body": "1750 ജനുവരിയിൽ മാർത്താണ്ഡവർമ്മ തിരുവിതാംകൂർ രാജ്യം ശ്രീപത്മനാഭന് സമർപ്പിച്ചു; ഇതാണ് തൃപ്പടിദാനം. തുടർന്ന് ‘ശ്രീപത്മനാഭദാസൻ’ ആയി, ദേവന്റെ പ്രതിനിധിയെന്ന നിലയിൽ ഭരിച്ചു. ഭരണകാലം 1729–1758.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Marthanda_Varma"},
  {"topic": "കേരള ചരിത്രം", "title": "ധർമ്മരാജ: കാർത്തിക തിരുനാൾ രാമവർമ്മ", "body": "മാർത്താണ്ഡവർമ്മയുടെ പിൻഗാമി കാർത്തിക തിരുനാൾ രാമവർമ്മ (ഭരണം 1758–1798) ധർമ്മശാസ്ത്രം കർശനമായി പാലിച്ചതിനാലും മൈസൂർ ആക്രമണകാലത്ത് മലബാറിൽനിന്നുള്ള അഭയാർത്ഥികളെ സംരക്ഷിച്ചതിനാലും ‘ധർമ്മരാജ’ എന്നറിയപ്പെട്ടു. ദിവാൻ രാജാ കേശവദാസ്.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Dharma_Raja"},
  {"topic": "കേരള ചരിത്രം", "title": "പഴശ്ശിരാജ: ‘കേരളസിംഹം’, 1805", "body": "കോട്ടയം (മലബാർ) രാജവംശത്തിലെ കേരളവർമ്മ പഴശ്ശിരാജ ബ്രിട്ടീഷുകാരോട് പോരാടി 1805 നവംബർ 30-ന് വയനാട്ടിലെ മാവിലത്തോടിൽ വീരമൃത്യു വരിച്ചു. ‘കേരളസിംഹം’ എന്നറിയപ്പെടുന്നു; കെ.എം. പണിക്കർ ‘കേരളസിംഹം’ (1941) എന്ന നോവൽ രചിച്ചു.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Pazhassi_Raja"},
  {"topic": "കേരള ചരിത്രം", "title": "കുണ്ടറ വിളംബരം 1809: വേലുത്തമ്പി ദളവ", "body": "തിരുവിതാംകൂർ ദളവ വേലുത്തമ്പി 1809 ജനുവരി 11-ന് ബ്രിട്ടീഷുകാർക്കെതിരെ കുണ്ടറ വിളംബരം നടത്തി. തലക്കുളത്ത് ജനിച്ച അദ്ദേഹം 1809-ൽ ശത്രുക്കൾ വളഞ്ഞപ്പോൾ മണ്ണടി ക്ഷേത്രത്തിൽ ആത്മഹത്യ ചെയ്തു.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Velu_Thampi_Dalawa"}],
 [{"topic": "കേരള ഭരണസംവിധാനം", "title": "കേരളപ്പിറവി: 1956 നവംബർ 1", "body": "1956-ലെ സംസ്ഥാന പുനഃസംഘടനാ നിയമപ്രകാരം 1956 നവംബർ 1-ന് കേരളം രൂപീകൃതമായി. തിരു-കൊച്ചി സംസ്ഥാനവും മദ്രാസ് സംസ്ഥാനത്തിലെ മലബാർ ജില്ലയും ചേർത്താണ് രൂപീകരണം. ഫസൽ അലി അധ്യക്ഷനായ സംസ്ഥാന പുനഃസംഘടനാ കമ്മീഷന്റെ ശുപാർശ പ്രകാരമായിരുന്നു ഇത്.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/States_Reorganisation_Act,_1956"},
  {"topic": "കേരള ഭരണസംവിധാനം", "title": "കാസർഗോഡ് താലൂക്ക് കേരളത്തിലേക്ക്", "body": "1956-ലെ പുനഃസംഘടനയിൽ ദക്ഷിണ കാനറ ജില്ലയിലെ കാസർഗോഡ് താലൂക്ക് കേരളത്തോട് ചേർത്തു. അതേസമയം തിരു-കൊച്ചിയുടെ തെക്കേ ഭാഗമായ കന്യാകുമാരി ജില്ലയും ചെങ്കോട്ട താലൂക്കും മദ്രാസ് സംസ്ഥാനത്തിന് കൈമാറി.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/States_Reorganisation_Act,_1956"},
  {"topic": "കേരള ഭരണസംവിധാനം", "title": "ഇ.എം.എസ്.: കേരളത്തിന്റെ ആദ്യ മുഖ്യമന്ത്രി", "body": "1957 ഏപ്രിൽ 5-ന് ഇ.എം.എസ്. നമ്പൂതിരിപ്പാട് (സി.പി.ഐ.) കേരളത്തിന്റെ ആദ്യ മുഖ്യമന്ത്രിയായി സത്യപ്രതിജ്ഞ ചെയ്തു. തിരഞ്ഞെടുപ്പിലൂടെ അധികാരത്തിലെത്തിയ ആദ്യ കമ്മ്യൂണിസ്റ്റ് സർക്കാർ ഇതാണ്. 'ഒന്നേകാൽ കോടി മലയാളികൾ' അദ്ദേഹത്തിന്റെ കൃതിയാണ്.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/List_of_chief_ministers_of_Kerala"},
  {"topic": "കേരള ഭരണസംവിധാനം", "title": "ആദ്യ മന്ത്രിസഭയിൽ 11 പേർ", "body": "1957-ലെ ഇ.എം.എസ്. മന്ത്രിസഭയിൽ മുഖ്യമന്ത്രി ഉൾപ്പെടെ 11 അംഗങ്ങൾ. പ്രമുഖർ: സി. അച്യുതമേനോൻ (ധനം), ജോസഫ് മുണ്ടശ്ശേരി (വിദ്യാഭ്യാസം, സഹകരണം), വി.ആർ. കൃഷ്ണയ്യർ (നിയമം), ഏക വനിതാ അംഗം കെ.ആർ. ഗൗരി (റവന്യൂ).", "source": "കേരള നിയമസഭ", "url": "https://www.niyamasabha.org/codes/ginfo_6_1.htm"},
  {"topic": "കേരള ഭരണസംവിധാനം", "title": "കേരള വിദ്യാഭ്യാസ ബിൽ: ജോസഫ് മുണ്ടശ്ശേരി", "body": "1957-ലെ കേരള വിദ്യാഭ്യാസ ബിൽ അവതരിപ്പിച്ചത് വിദ്യാഭ്യാസ മന്ത്രി പ്രൊഫ. ജോസഫ് മുണ്ടശ്ശേരിയാണ്. സുപ്രീം കോടതി പരിശോധനയ്ക്ക് ശേഷം രാഷ്ട്രപതിയുടെ അനുമതി ലഭിച്ച് ഇത് കേരള വിദ്യാഭ്യാസ നിയമം 1958 (1959-ലെ 6-ാം നിയമം) ആയി.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Kerala_Education_Act,_1958"},
  {"topic": "കേരള ഭരണസംവിധാനം", "title": "ആർ. ശങ്കർ: ആദ്യ ഉപമുഖ്യമന്ത്രി", "body": "പട്ടം താണുപിള്ള മന്ത്രിസഭയിൽ (1960–62) ആർ. ശങ്കർ കേരളത്തിന്റെ ആദ്യ ഉപമുഖ്യമന്ത്രിയായി. 1962 സെപ്റ്റംബർ 26-ന് പട്ടത്തിന്റെ പിൻഗാമിയായി അദ്ദേഹം കേരളത്തിന്റെ മൂന്നാമത്തെ മുഖ്യമന്ത്രിയായി.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/R._Sankar"},
  {"topic": "കേരള ഭരണസംവിധാനം", "title": "ആർ. ശങ്കർ: അവിശ്വാസത്തിൽ വീണ ആദ്യ സർക്കാർ", "body": "നിയമസഭ അവിശ്വാസ പ്രമേയം പാസാക്കിയതിനെ തുടർന്ന് 1964 സെപ്റ്റംബർ 10-ന് ആർ. ശങ്കർ മന്ത്രിസഭ രാജിവെച്ചു. അവിശ്വാസ പ്രമേയത്തിലൂടെ പുറത്തായ ആദ്യ കേരള മുഖ്യമന്ത്രിയായി അദ്ദേഹം അറിയപ്പെടുന്നു.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/R._Sankar"},
  {"topic": "കേരള ഭരണസംവിധാനം", "title": "ജ്യോതി വെങ്കിടാചെല്ലം: ആദ്യ വനിതാ ഗവർണർ", "body": "കേരളത്തിലെ ആദ്യ വനിതാ ഗവർണർ ജ്യോതി വെങ്കിടാചെല്ലമാണ് (1977 ഒക്ടോബർ 14 – 1982 ഒക്ടോബർ 27). രാംദുലാരി സിൻഹ, ഷീല ദീക്ഷിത് എന്നിവരും പിന്നീട് കേരള ഗവർണർമാരായ വനിതകളാണ്.", "source": "കേരള നിയമസഭ", "url": "https://www.niyamasabha.org/codes/ginfo_4.htm"},
  {"topic": "കേരള ഭരണസംവിധാനം", "title": "ജനകീയാസൂത്രണം: 1996 ഓഗസ്റ്റ് 17", "body": "ജനകീയാസൂത്രണ പ്രസ്ഥാനം 1996 ഓഗസ്റ്റ് 17-ന് (ചിങ്ങം 1) ഇ.എം.എസ്. നമ്പൂതിരിപ്പാട് ഉദ്ഘാടനം ചെയ്തു. ഒമ്പതാം പഞ്ചവത്സര പദ്ധതിയുടെ ഭാഗമായിരുന്നതിനാൽ 'ഒമ്പതാം പദ്ധതിക്കായുള്ള ജനകീയ കാമ്പെയ്ൻ' എന്നും അറിയപ്പെടുന്നു.", "source": "The South First", "url": "https://thesouthfirst.com/kerala/peoples-plan-at-30-kerala-youth-to-take-forward-revolution-in-local-governance/"},
  {"topic": "കേരള ഭരണസംവിധാനം", "title": "കേരള പഞ്ചായത്ത് രാജ് നിയമം: 1994", "body": "1994-ൽ കേരള പഞ്ചായത്ത് രാജ് നിയമവും കേരള മുനിസിപ്പാലിറ്റി നിയമവും നടപ്പാക്കി. ഗ്രാമങ്ങളിൽ ത്രിതല സംവിധാനവും നഗരങ്ങളിൽ ഏകതല സംവിധാനവുമാണ്.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Local_government_in_Kerala"}],
 [{"topic": "ഭൗതികശാസ്ത്രം", "title": "പാസ്കൽ: മർദ്ദത്തിന്റെ SI യൂണിറ്റ്", "body": "മർദ്ദത്തിന്റെ SI യൂണിറ്റാണ് പാസ്കൽ (Pa). 1 പാസ്കൽ = 1 ന്യൂട്ടൻ/ചതുരശ്ര മീറ്റർ (N/m²). ഫ്രഞ്ച് ശാസ്ത്രജ്ഞൻ ബ്ലെയ്സ് പാസ്കലിന്റെ പേരിലുള്ള ഈ യൂണിറ്റ് 1971-ലാണ് ഔദ്യോഗികമായി അംഗീകരിച്ചത്.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Pascal_(unit)"},
  {"topic": "ഭൗതികശാസ്ത്രം", "title": "പാസ്കൽ നിയമം: ഹൈഡ്രോളിക് പ്രസ്", "body": "അടച്ച പാത്രത്തിലെ ദ്രാവകത്തിൽ ഒരിടത്ത് പ്രയോഗിക്കുന്ന മർദ്ദം കുറവില്ലാതെ എല്ലാ ഭാഗത്തേക്കും തുല്യമായി വ്യാപിക്കുന്നു എന്നതാണ് പാസ്കൽ നിയമം. ഹൈഡ്രോളിക് പ്രസിന്റെ പ്രവർത്തനതത്വം ഇതാണ്.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Pascal%27s_law"},
  {"topic": "ഭൗതികശാസ്ത്രം", "title": "ബാരോമീറ്റർ കണ്ടുപിടിച്ചത് ടോറിസെല്ലി", "body": "അന്തരീക്ഷമർദ്ദം അളക്കുന്ന ഉപകരണമാണ് ബാരോമീറ്റർ. 1643-ൽ ഇവാഞ്ചലിസ്റ്റ ടോറിസെല്ലിയാണ് മെർക്കുറി ബാരോമീറ്റർ കണ്ടുപിടിച്ചത്. അന്തരീക്ഷമർദ്ദം ഏകദേശം 30 ഇഞ്ച് ഉയരമുള്ള മെർക്കുറി സ്തംഭത്തെ താങ്ങിനിർത്തുമെന്ന് അദ്ദേഹം തെളിയിച്ചു.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Barometer"},
  {"topic": "ഭൗതികശാസ്ത്രം", "title": "ഹൈഗ്രോമീറ്റർ: ആർദ്രത അളക്കാൻ", "body": "അന്തരീക്ഷത്തിലെ ആർദ്രത, അതായത് വായുവിലുള്ള നീരാവിയുടെ അളവ്, അളക്കുന്ന ഉപകരണമാണ് ഹൈഗ്രോമീറ്റർ. അന്തരീക്ഷമർദ്ദം അളക്കുന്നത് ബാരോമീറ്റർ കൊണ്ടാണ്; ഇവ തമ്മിൽ പരീക്ഷയിൽ മാറിപ്പോകാറുണ്ട്.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Hygrometer"},
  {"topic": "ഭൗതികശാസ്ത്രം", "title": "ന്യൂട്ടന്റെ മൂന്നാം ചലനനിയമം", "body": "ഓരോ പ്രവർത്തനത്തിനും തുല്യവും വിപരീതവുമായ ഒരു പ്രതിപ്രവർത്തനം ഉണ്ടായിരിക്കും എന്നതാണ് ന്യൂട്ടന്റെ മൂന്നാം ചലനനിയമം. റോക്കറ്റ് മുകളിലേക്ക് ഉയരുന്നത് ഈ നിയമത്തിന് ഉദാഹരണമാണ്.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Newton%27s_laws_of_motion"},
  {"topic": "ഭൗതികശാസ്ത്രം", "title": "ബോയിൽ നിയമം: മർദ്ദവും വ്യാപ്തവും", "body": "സ്ഥിര ഊഷ്മാവിൽ ഒരു നിശ്ചിത അളവ് വാതകത്തിന്റെ മർദ്ദവും വ്യാപ്തവും വിപരീതാനുപാതത്തിലാണ്. 1662-ൽ റോബർട്ട് ബോയിൽ പ്രസിദ്ധീകരിച്ചു. വെള്ളത്തിനടിയിലേക്ക് താഴ്ത്തുന്ന ബലൂൺ ചുരുങ്ങുന്നത് ഉദാഹരണം.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Boyle%27s_law"},
  {"topic": "ഭൗതികശാസ്ത്രം", "title": "പ്രകാശവേഗം ആദ്യം കണക്കാക്കിയത് റോമർ", "body": "ശൂന്യതയിൽ പ്രകാശത്തിന്റെ വേഗം സെക്കൻഡിൽ 299,792,458 മീറ്റർ (ഏകദേശം 3 × 10⁸ m/s) ആണ്; ശൂന്യതയിലാണ് പ്രകാശത്തിന് ഏറ്റവും വേഗം. 1676-ൽ വ്യാഴത്തിന്റെ ഉപഗ്രഹമായ അയോയെ നിരീക്ഷിച്ച് ഓലെ റോമറാണ് ഇത് ആദ്യമായി കണക്കാക്കിയത്.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Speed_of_light"},
  {"topic": "ഭൗതികശാസ്ത്രം", "title": "വായുവിൽ ശബ്ദവേഗം ഏകദേശം 343 m/s", "body": "20°C-ൽ വായുവിൽ ശബ്ദത്തിന്റെ വേഗം ഏകദേശം 343 m/s ആണ്. ജലത്തിൽ ഏകദേശം 1481 m/s, ഇരുമ്പിൽ 5120 m/s. അതായത് ശബ്ദവേഗം കൂടുന്ന ക്രമം: വായു < ജലം < ഇരുമ്പ് (ഖരവസ്തു).", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Speed_of_sound"},
  {"topic": "ഭൗതികശാസ്ത്രം", "title": "വജ്രത്തിളക്കം: പൂർണ ആന്തര പ്രതിഫലനം", "body": "സാന്ദ്രത കൂടിയ മാധ്യമത്തിൽനിന്ന് കുറഞ്ഞതിലേക്ക് ക്രിട്ടിക്കൽ കോണിനേക്കാൾ വലിയ കോണിൽ പ്രകാശം പതിക്കുമ്പോൾ പൂർണ ആന്തര പ്രതിഫലനം സംഭവിക്കുന്നു. വജ്രത്തിന്റെ തിളക്കത്തിനും ഒപ്റ്റിക്കൽ ഫൈബറിന്റെ പ്രവർത്തനത്തിനും കാരണം ഇതാണ്.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Total_internal_reflection"},
  {"topic": "ഭൗതികശാസ്ത്രം", "title": "മഴവില്ല്: പ്രകീർണനം", "body": "ജലകണങ്ങളിൽ സൂര്യപ്രകാശത്തിന് അപവർത്തനം, ആന്തര പ്രതിഫലനം, പ്രകീർണനം എന്നിവ സംഭവിച്ചാണ് മഴവില്ല് ഉണ്ടാകുന്നത്. സൂര്യൻ നിരീക്ഷകന്റെ പിന്നിലായിരിക്കും; പ്രാഥമിക മഴവില്ലിൽ ചുവപ്പ് പുറത്തും വയലറ്റ് ഉള്ളിലും.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Rainbow"}],
 [{"topic": "രസതന്ത്രം", "title": "ഇലക്ട്രോൺ കണ്ടെത്തിയത് ജെ.ജെ. തോംസൺ", "body": "1897-ൽ കാഥോഡ് കിരണ പരീക്ഷണങ്ങളിലൂടെ ജെ.ജെ. തോംസണാണ് ഇലക്ട്രോൺ കണ്ടെത്തിയത്. നെഗറ്റീവ് ചാർജുള്ള ഈ കണത്തിന്റെ ചാർജ് കൃത്യമായി അളന്നത് റോബർട്ട് മില്ലിക്കന്റെ എണ്ണത്തുള്ളി പരീക്ഷണമാണ് (1909).", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Electron"},
  {"topic": "രസതന്ത്രം", "title": "ന്യൂട്രോൺ കണ്ടെത്തിയത് ചാഡ്‌വിക്", "body": "ആറ്റത്തിന്റെ ന്യൂക്ലിയസിലുള്ള ചാർജില്ലാത്ത കണമായ ന്യൂട്രോൺ 1932-ൽ ജെയിംസ് ചാഡ്‌വിക് കണ്ടെത്തി. ഇതിന് അദ്ദേഹത്തിന് 1935-ലെ ഭൗതികശാസ്ത്ര നൊബേൽ ലഭിച്ചു. ന്യൂട്രോണിന്റെ പിണ്ഡം ഏകദേശം പ്രോട്ടോണിന് തുല്യം.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Neutron"},
  {"topic": "രസതന്ത്രം", "title": "പ്രോട്ടോൺ: മൂലകത്തിന്റെ തിരിച്ചറിയൽ", "body": "ഏണസ്റ്റ് റൂഥർഫോർഡാണ് പ്രോട്ടോൺ കണ്ടെത്തി പേര് നൽകിയത് (1917–1920). ന്യൂക്ലിയസിലെ പ്രോട്ടോണുകളുടെ എണ്ണമാണ് അറ്റോമിക നമ്പർ (Z); അതാണ് ഒരു മൂലകത്തെ നിർണയിക്കുന്നത്. അതിനാൽ 'മൂലകത്തിന്റെ ഐഡന്റിറ്റി കാർഡ്' എന്നറിയപ്പെടുന്നു.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Proton"},
  {"topic": "രസതന്ത്രം", "title": "മെൻഡലീഫിന്റെ ആവർത്തനപ്പട്ടിക: 1869", "body": "ദിമിത്രി മെൻഡലീഫ് 1869-ൽ അറ്റോമിക ഭാരത്തിന്റെ അടിസ്ഥാനത്തിൽ ആവർത്തനപ്പട്ടിക അവതരിപ്പിച്ചു. കണ്ടെത്താത്ത മൂലകങ്ങൾക്കായി ഒഴിവിട്ട് ഗാലിയം, ജർമേനിയം തുടങ്ങിയവയുടെ ഗുണങ്ങൾ പ്രവചിച്ചു. മെൻഡലീവിയം (101) അദ്ദേഹത്തിന്റെ പേരിലാണ്.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Dmitri_Mendeleev"},
  {"topic": "രസതന്ത്രം", "title": "മോസ്‌ലി: അറ്റോമിക നമ്പറിന്റെ അടിസ്ഥാനം", "body": "1913-ൽ എക്സ്-റേ സ്പെക്ട്രം പഠിച്ച് ഹെൻറി മോസ്‌ലി മൂലകങ്ങളുടെ ക്രമം അറ്റോമിക നമ്പറിന്റെ അടിസ്ഥാനത്തിലാണെന്ന് തെളിയിച്ചു. ആധുനിക ആവർത്തനപ്പട്ടിക ഇതിനെ ആധാരമാക്കുന്നു; അതിൽ 18 ഗ്രൂപ്പുകളും 7 പീരിയഡുകളുമുണ്ട്.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Henry_Moseley"},
  {"topic": "രസതന്ത്രം", "title": "ഹൈഡ്രജൻ: ഏറ്റവും ഭാരം കുറഞ്ഞ മൂലകം", "body": "പ്രപഞ്ചത്തിലെ ഏറ്റവും ഭാരം കുറഞ്ഞതും ഏറ്റവും കൂടുതലുള്ളതുമായ മൂലകമാണ് ഹൈഡ്രജൻ; സാധാരണ ദ്രവ്യത്തിന്റെ ഏകദേശം 75%. 1766-ൽ ഹെൻറി കാവൻഡിഷ് ഇത് വേറിട്ട പദാർത്ഥമായി തിരിച്ചറിഞ്ഞു; ലാവോസിയെ പേര് നൽകി.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Hydrogen"},
  {"topic": "രസതന്ത്രം", "title": "ഭൂവൽക്കത്തിൽ കൂടുതൽ ഓക്സിജൻ", "body": "ഭൂവൽക്കത്തിൽ ഏറ്റവും കൂടുതലുള്ള മൂലകം ഓക്സിജൻ (ഏകദേശം 46%), രണ്ടാമത് സിലിക്കൺ (28%). ഏറ്റവും കൂടുതലുള്ള ലോഹം അലുമിനിയം (ഏകദേശം 8%); തൊട്ടുപിന്നിൽ ഇരുമ്പ്.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Abundance_of_elements_in_Earth%27s_crust"},
  {"topic": "രസതന്ത്രം", "title": "വായുവിൽ 78% നൈട്രജൻ", "body": "ഈർപ്പമില്ലാത്ത വായുവിൽ ഏകദേശം 78.08% നൈട്രജൻ, 20.95% ഓക്സിജൻ, 0.93% ആർഗൺ എന്നിങ്ങനെയാണ് അടങ്ങിയിരിക്കുന്നത്. അന്തരീക്ഷത്തിൽ ഏറ്റവും കൂടുതലുള്ള വാതകം നൈട്രജനും, ഏറ്റവും കൂടുതലുള്ള കുലീനവാതകം ആർഗണുമാണ്.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Atmosphere_of_Earth"},
  {"topic": "രസതന്ത്രം", "title": "ദ്രാവക മൂലകങ്ങൾ: മെർക്കുറിയും ബ്രോമിനും", "body": "സാധാരണ ഊഷ്മാവിൽ ദ്രാവകാവസ്ഥയിലുള്ള മൂലകങ്ങൾ രണ്ടെണ്ണം: ലോഹമായ മെർക്കുറിയും (രസം) അലോഹമായ ബ്രോമിനും. ബ്രോമിൻ ചുവപ്പുകലർന്ന തവിട്ടുനിറമുള്ള, എളുപ്പം ബാഷ്പമാകുന്ന ദ്രാവകമാണ്.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Bromine"},
  {"topic": "രസതന്ത്രം", "title": "ചിരിപ്പിക്കുന്ന വാതകം: നൈട്രസ് ഓക്സൈഡ്", "body": "നൈട്രസ് ഓക്സൈഡ് (N₂O) ആണ് 'ചിരിപ്പിക്കുന്ന വാതകം'. 1772-ൽ ജോസഫ് പ്രീസ്റ്റ്‌ലി ആദ്യമായി നിർമ്മിച്ചു; ഹംഫ്രി ഡേവിയാണ് 'ലാഫിങ് ഗ്യാസ്' എന്ന പേര് നൽകിയത്. ഇപ്പോഴും ദന്തചികിത്സയിൽ അനസ്തേഷ്യയ്ക്ക് ഉപയോഗിക്കുന്നു.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Nitrous_oxide"}],
 [{"topic": "കല, സാഹിത്യം, കായികം", "title": "ആദ്യ വള്ളത്തോൾ പുരസ്കാരം: പാലാ", "body": "വള്ളത്തോൾ സാഹിത്യ സമിതി 1991-ൽ ഏർപ്പെടുത്തിയ വള്ളത്തോൾ പുരസ്കാരം ആദ്യമായി ലഭിച്ചത് കവി പാലാ നാരായണൻ നായർക്കാണ് (1991). മഹാകവി വള്ളത്തോൾ നാരായണമേനോന്റെ സ്മരണയ്ക്കായുള്ള സാഹിത്യ പുരസ്കാരമാണിത്.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Vallathol_Award"},
  {"topic": "കല, സാഹിത്യം, കായികം", "title": "സരസ്വതി സമ്മാൻ: ആദ്യ മലയാളി ബാലാമണിയമ്മ", "body": "കെ.കെ. ബിർള ഫൗണ്ടേഷൻ 1991-ൽ ഏർപ്പെടുത്തിയ സരസ്വതി സമ്മാൻ നേടിയ ആദ്യ മലയാളി ബാലാമണിയമ്മയാണ് (1995, 'നിവേദ്യം'). അയ്യപ്പപ്പണിക്കർ (2005), സുഗതകുമാരി (2012, 'മണലെഴുത്ത്') എന്നിവരും നേടി.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Saraswati_Samman"},
  {"topic": "കല, സാഹിത്യം, കായികം", "title": "ഉറൂബ്: പി.സി. കുട്ടികൃഷ്ണൻ", "body": "'ഉറൂബ്' എന്ന തൂലികാനാമത്തിൽ എഴുതിയത് പി.സി. കുട്ടികൃഷ്ണൻ. പേർഷ്യനിൽ 'നിത്യയൗവനം' എന്നാണ് അർത്ഥം. 'സുന്ദരികളും സുന്ദരന്മാരും' (1960-ൽ കേന്ദ്ര സാഹിത്യ അക്കാദമി അവാർഡ്), 'ഉമ്മാച്ചു' എന്നിവ പ്രധാന നോവലുകൾ.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Uroob"},
  {"topic": "കല, സാഹിത്യം, കായികം", "title": "കോവിലൻ: വി.വി. അയ്യപ്പൻ", "body": "'കോവിലൻ' എന്ന തൂലികാനാമത്തിൽ എഴുതിയത് വി.വി. അയ്യപ്പൻ (1923–2010). നാവികസേനയിലും കരസേനയിലും സേവനം ചെയ്തു. 'തട്ടകം' നോവലിന് കേന്ദ്ര സാഹിത്യ അക്കാദമി (1998), വയലാർ (1999) അവാർഡുകൾ ലഭിച്ചു.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Kovilan"},
  {"topic": "കല, സാഹിത്യം, കായികം", "title": "വിലാസിനി: എം.കെ. മേനോൻ", "body": "'വിലാസിനി' എന്ന തൂലികാനാമം എം.കെ. മേനോന്റേതാണ്. 3,958 പേജുള്ള, നാലു വാല്യങ്ങളുള്ള 'അവകാശികൾ' ഇന്ത്യൻ ഭാഷകളിലെ ഏറ്റവും ദൈർഘ്യമേറിയ നോവലായി അറിയപ്പെടുന്നു; ഇതിന് കേന്ദ്ര സാഹിത്യ അക്കാദമി, വയലാർ അവാർഡുകൾ ലഭിച്ചു.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Vilasini"},
  {"topic": "കല, സാഹിത്യം, കായികം", "title": "തിക്കോടിയൻ: പി. കുഞ്ഞനന്തൻ നായർ", "body": "'തിക്കോടിയൻ' എന്ന തൂലികാനാമത്തിൽ അറിയപ്പെടുന്നത് നാടകകൃത്ത് പി. കുഞ്ഞനന്തൻ നായർ. അദ്ദേഹത്തിന്റെ ആത്മകഥ 'അരങ്ങു കാണാത്ത നടൻ' (1991) കേന്ദ്ര സാഹിത്യ അക്കാദമി, വയലാർ അവാർഡുകൾ നേടി.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Thikkodiyan"},
  {"topic": "കല, സാഹിത്യം, കായികം", "title": "കേരള ഇബ്സൻ: എൻ. കൃഷ്ണപിള്ള", "body": "മാനസിക-സാമൂഹിക സംഘർഷങ്ങൾ ചിത്രീകരിക്കുന്ന യഥാതഥ നാടകങ്ങൾ എഴുതിയ എൻ. കൃഷ്ണപിള്ള 'കേരള ഇബ്സൻ' എന്നറിയപ്പെടുന്നു. 'ഭഗ്നഭവനം' (1942), 'കന്യക' (1944) എന്നിവ പ്രധാന നാടകങ്ങൾ.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/N._Krishna_Pillai"},
  {"topic": "കല, സാഹിത്യം, കായികം", "title": "പാവങ്ങൾ: നാലപ്പാട്ട് നാരായണമേനോൻ", "body": "വിക്ടർ ഹ്യൂഗോയുടെ 'ലെ മിസറബിൾ' 'പാവങ്ങൾ' എന്ന പേരിൽ മലയാളത്തിലാക്കിയത് നാലപ്പാട്ട് നാരായണമേനോൻ. മലയാള സാഹിത്യചരിത്രത്തിലെ നാഴികക്കല്ലായ ഈ വിവർത്തനം പുതിയ ഗദ്യശൈലി നൽകി. 'കണ്ണുനീർത്തുള്ളി' അദ്ദേഹത്തിന്റെ വിലാപകാവ്യം.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Nalapat_Narayana_Menon"},
  {"topic": "കല, സാഹിത്യം, കായികം", "title": "ആടുജീവിതം: നജീബിന്റെ കഥ", "body": "ബെന്യാമിന്റെ 'ആടുജീവിതം' (2008) സൗദി മരുഭൂമിയിൽ ആടുകളെ മേയ്ക്കാൻ നിർബന്ധിതനായ നജീബിന്റെ യഥാർത്ഥ അനുഭവം അടിസ്ഥാനമാക്കിയ നോവലാണ്. 2009-ൽ കേരള സാഹിത്യ അക്കാദമി അവാർഡ് നേടി; 2024-ൽ ബ്ലെസി സിനിമയാക്കി.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Aadujeevitham"},
  {"topic": "കല, സാഹിത്യം, കായികം", "title": "ഖസാക്കിന്റെ ഇതിഹാസം: ഒ.വി. വിജയൻ", "body": "ഒ.വി. വിജയന്റെ ആദ്യ നോവലായ 'ഖസാക്കിന്റെ ഇതിഹാസം' 1968-ൽ മാതൃഭൂമി ആഴ്ചപ്പതിപ്പിൽ പ്രസിദ്ധീകരിച്ചു. നായകൻ രവി; അപ്പുക്കിളി, അള്ളാപ്പിച്ച മൊല്ലാക്ക എന്നിവർ കഥാപാത്രങ്ങൾ. പാലക്കാട്ടെ തസ്രാക്ക് ഗ്രാമമാണ് പ്രചോദനം.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Khasakkinte_Itihasam"}],
 [{"topic": "മലയാള ഭാഷ", "title": "തത്പുരുഷൻ, കർമ്മധാരയൻ, ദ്വിഗു", "body": "ഉത്തരപദത്തിന് പ്രാധാന്യമുള്ളത് തത്പുരുഷൻ (പാക്കുവെട്ടി). വിശേഷണ-വിശേഷ്യ ബന്ധമുള്ളത് കർമ്മധാരയൻ (പൂരിതാഭ). പൂർവപദം സംഖ്യയായ സമാസം ദ്വിഗു (മുക്കണ്ണൻ, ദശാനനൻ). അവ്യയീഭാവന് ഉദാ: അനുദിനം.", "source": "Wikipedia", "url": "https://ml.wikipedia.org/wiki/%E0%B4%B8%E0%B4%AE%E0%B4%BE%E0%B4%B8%E0%B4%82"},
  {"topic": "മലയാള ഭാഷ", "title": "മലയാളത്തിൽ ഏഴ് വിഭക്തികൾ", "body": "മലയാളത്തിൽ ഏഴ് വിഭക്തികൾ: നിർദ്ദേശിക (പ്രത്യയമില്ല), പ്രതിഗ്രാഹിക (എ), സംയോജിക (ഓട്), ഉദ്ദേശിക (ക്ക്/ന്), പ്രയോജിക (ആൽ), സംബന്ധിക (ന്റെ/ഉടെ), ആധാരിക (ഇൽ/കൽ). നിർദ്ദേശികയ്ക്ക് പ്രത്യയമില്ല.", "source": "Wikipedia", "url": "https://ml.wikipedia.org/wiki/%E0%B4%B5%E0%B4%BF%E0%B4%AD%E0%B4%95%E0%B5%8D%E0%B4%A4%E0%B4%BF"},
  {"topic": "മലയാള ഭാഷ", "title": "ലീലാതിലകം: മണിപ്രവാള വ്യാകരണം", "body": "മണിപ്രവാളത്തിന്റെ വ്യാകരണവും കാവ്യശാസ്ത്രവും പ്രതിപാദിക്കുന്ന 14-ാം നൂറ്റാണ്ടിലെ ഗ്രന്ഥമാണ് 'ലീലാതിലകം'. സംസ്കൃതത്തിൽ എഴുതിയ ഇതിന്റെ കർത്താവ് അജ്ഞാതനാണ്; 'ശില്പങ്ങൾ' എന്ന എട്ട് ഭാഗങ്ങളുണ്ട്.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Lilatilakam"},
  {"topic": "മലയാള ഭാഷ", "title": "സംക്ഷേപവേദാർത്ഥം: ആദ്യ അച്ചടി പുസ്തകം", "body": "മലയാളത്തിൽ ആദ്യമായി അച്ചടിച്ച പുസ്തകം 'സംക്ഷേപവേദാർത്ഥം' ആണ്. ക്ലെമന്റ് പിയാനിയസ് (ക്ലമന്റ് പാതിരി) രചിച്ച ഈ ഗ്രന്ഥം 1772-ൽ റോമിൽ ചലിക്കുന്ന അച്ചുകൾ ഉപയോഗിച്ച് അച്ചടിച്ചു.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Samkshepavedartham"},
  {"topic": "മലയാള ഭാഷ", "title": "സി.എം.എസ്. പ്രസ്: കോട്ടയം, 1821", "body": "ബെഞ്ചമിൻ ബെയ്‌ലി 1821-ൽ കോട്ടയത്ത് സ്ഥാപിച്ച സി.എം.എസ്. പ്രസ് കേരളത്തിലെ ആദ്യ മലയാളം അച്ചടിശാലയാണ്. 1846-ൽ ഇവിടെനിന്ന് ഒരു മലയാളം-ഇംഗ്ലീഷ് നിഘണ്ടുവും പ്രസിദ്ധീകരിച്ചു.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/C.M.S._Press"},
  {"topic": "മലയാള ഭാഷ", "title": "ജ്ഞാനനിക്ഷേപം: ആദ്യ അച്ചടിപ്പത്രം, 1848", "body": "1848-ൽ കോട്ടയം സി.എം.എസ്. പ്രസ്സിൽ അച്ചടിച്ചു പ്രസിദ്ധീകരിച്ച 'ജ്ഞാനനിക്ഷേപം' കേരളത്തിലെ ആദ്യ അച്ചടിപ്പത്രമാണ്. രാജ്യസമാചാരം (1847) ലിത്തോഗ്രാഫ് പ്രസിദ്ധീകരണമായിരുന്നു.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/C.M.S._Press"},
  {"topic": "മലയാള ഭാഷ", "title": "രാമചരിതം: പ്രാചീന മലയാള കൃതി", "body": "ചീരാമകവി രചിച്ച 'രാമചരിതം' (12–13 നൂറ്റാണ്ട്) ലഭ്യമായതിൽ ഏറ്റവും പഴയ മലയാള സാഹിത്യകൃതിയായി കരുതപ്പെടുന്നു. പാട്ട് പ്രസ്ഥാനത്തിലെ ഈ കൃതി രാമായണം യുദ്ധകാണ്ഡം ആധാരമാക്കി 164 പടലങ്ങളിലായി രചിച്ചു.", "source": "Wikipedia", "url": "https://ml.wikipedia.org/wiki/%E0%B4%B0%E0%B4%BE%E0%B4%AE%E0%B4%9A%E0%B4%B0%E0%B4%BF%E0%B4%A4%E0%B4%82"},
  {"topic": "മലയാള ഭാഷ", "title": "മലയാള ലിപി: വട്ടെഴുത്തും ഗ്രന്ഥലിപിയും", "body": "മലയാളം എഴുതാൻ ആദ്യകാലത്ത് ഉപയോഗിച്ചത് വട്ടെഴുത്താണ്. ഇന്നത്തെ മലയാള ലിപി ഗ്രന്ഥലിപിയിൽനിന്ന് 14-ാം നൂറ്റാണ്ടോടെ രൂപപ്പെട്ടു. വട്ടെഴുത്തിൽനിന്നുണ്ടായ കോലെഴുത്ത് വടക്കൻ കേരളത്തിൽ പ്രചാരത്തിലായിരുന്നു.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Vatteluttu"},
  {"topic": "മലയാള ഭാഷ", "title": "ലോപസന്ധി: കൊടുത്തു + ഇല്ല", "body": "ചേരുന്ന വർണങ്ങളിൽ ഒന്ന് ലോപിക്കുന്ന (ഇല്ലാതാകുന്ന) സന്ധിയാണ് ലോപസന്ധി. ഉദാ: കൊടുത്തു + ഇല്ല = കൊടുത്തില്ല, തണുപ്പു + ഉണ്ട് = തണുപ്പുണ്ട്. ഇവിടെ പൂർവപദാന്തത്തിലെ 'ഉ' ലോപിക്കുന്നു.", "source": "Wikipedia", "url": "https://ml.wikipedia.org/wiki/%E0%B4%B8%E0%B4%A8%E0%B5%8D%E0%B4%A7%E0%B4%BF_(%E0%B4%B5%E0%B5%8D%E0%B4%AF%E0%B4%BE%E0%B4%95%E0%B4%B0%E0%B4%A3%E0%B4%82)"},
  {"topic": "മലയാള ഭാഷ", "title": "മലയാളം സർവകലാശാല: തിരൂർ, 2012", "body": "തുഞ്ചത്തെഴുത്തച്ഛൻ മലയാളം സർവകലാശാല 2012 നവംബർ 1-ന് മലപ്പുറം ജില്ലയിലെ തിരൂരിൽ മുഖ്യമന്ത്രി ഉമ്മൻ ചാണ്ടി ഉദ്ഘാടനം ചെയ്തു. ആദ്യ വൈസ് ചാൻസലർ മുൻ ചീഫ് സെക്രട്ടറി കെ. ജയകുമാർ.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Thunchath_Ezhuthachan_Malayalam_University"}],
 [{"topic": "ജീവശാസ്ത്രവും ആരോഗ്യവും", "title": "O -ve ദാതാവ്; AB+ve സ്വീകർത്താവ്", "body": "O Rh-നെഗറ്റീവ് രക്തമുള്ളവരെ 'സാർവത്രിക ദാതാക്കൾ' എന്നും AB Rh-പോസിറ്റീവ് രക്തമുള്ളവരെ 'സാർവത്രിക സ്വീകർത്താക്കൾ' എന്നും വിളിക്കുന്നു. AB ഗ്രൂപ്പുകാർക്ക് എല്ലാ ഗ്രൂപ്പുകളിൽനിന്നും രക്തം സ്വീകരിക്കാം.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Blood_type"},
  {"topic": "ജീവശാസ്ത്രവും ആരോഗ്യവും", "title": "മുതിർന്നവരിൽ ഏകദേശം 5 ലിറ്റർ രക്തം", "body": "പ്രായപൂർത്തിയായ ഒരാളുടെ ശരീരത്തിൽ ഏകദേശം 5 ലിറ്റർ രക്തമുണ്ട്. രക്തത്തിന്റെ pH 7.35–7.45 എന്ന നേരിയ ക്ഷാരസ്വഭാവമുള്ള പരിധിയിലാണ്; രക്തത്തിന്റെ ഏകദേശം 55% ദ്രാവകഭാഗമായ പ്ലാസ്മയാണ്.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Blood"},
  {"topic": "ജീവശാസ്ത്രവും ആരോഗ്യവും", "title": "രക്തചംക്രമണം: വില്യം ഹാർവി", "body": "ശരീരത്തിലെ രക്തചംക്രമണം പൂർണ്ണമായും വിശദമായും ആദ്യം വിവരിച്ചത് ഇംഗ്ലീഷ് ഭിഷഗ്വരനായ വില്യം ഹാർവിയാണ്. 1628-ൽ ഫ്രാങ്ക്ഫർട്ടിൽ പ്രസിദ്ധീകരിച്ച 'ഡി മോട്ടു കോർഡിസ്' എന്ന ഗ്രന്ഥത്തിലാണ് അദ്ദേഹം ഇത് അവതരിപ്പിച്ചത്.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/William_Harvey"},
  {"topic": "ജീവശാസ്ത്രവും ആരോഗ്യവും", "title": "മെഡുല്ല ഒബ്ലോംഗേറ്റ: ഹൃദയമിടിപ്പും ശ്വസനവും", "body": "മസ്തിഷ്കകാണ്ഡത്തിന്റെ താഴത്തെ ഭാഗമായ മെഡുല്ല ഒബ്ലോംഗേറ്റയാണ് ഹൃദയമിടിപ്പ്, ശ്വസനം, രക്തസമ്മർദ്ദം തുടങ്ങിയ അനൈച്ഛിക പ്രവർത്തനങ്ങൾ നിയന്ത്രിക്കുന്നത്. ഛർദ്ദി, ചുമ, തുമ്മൽ, വിഴുങ്ങൽ എന്നീ റിഫ്ലക്സുകളും ഇതിന്റെ നിയന്ത്രണത്തിലാണ്.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Medulla_oblongata"},
  {"topic": "ജീവശാസ്ത്രവും ആരോഗ്യവും", "title": "സെറിബ്രം: മസ്തിഷ്കത്തിലെ ഏറ്റവും വലിയ ഭാഗം", "body": "മസ്തിഷ്കത്തിന്റെ ഏറ്റവും വലിയ ഭാഗമായ സെറിബ്രമാണ് ചിന്ത, ബുദ്ധി, ഓർമ്മ, ഭാഷ എന്നിവയുടെ കേന്ദ്രം. സംസാരശേഷിയുമായി ബന്ധപ്പെട്ട ബ്രോക്കാസ് ഏരിയ സെറിബ്രത്തിന്റെ ഫ്രണ്ടൽ ലോബിലാണ്; ഇതിന് തകരാർ സംഭവിച്ചാൽ സംസാരവൈകല്യം (അഫേസിയ) ഉണ്ടാകാം.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Cerebrum"},
  {"topic": "ജീവശാസ്ത്രവും ആരോഗ്യവും", "title": "ജീവകം C: അസ്കോർബിക് ആസിഡ്", "body": "അസ്കോർബിക് ആസിഡ് എന്നറിയപ്പെടുന്ന ജീവകം C ജലത്തിൽ ലയിക്കുന്നതാണ്; ഇതിന്റെ കുറവ് സ്കർവി എന്ന രോഗത്തിന് കാരണമാകുന്നു. നാരങ്ങ പോലുള്ള സിട്രസ് പഴങ്ങൾ പ്രധാന സ്രോതസ്സ്; ഇതിനെക്കുറിച്ചുള്ള പഠനത്തിന് ആൽബർട്ട് സെന്റ്-ജിയോർജിക്ക് 1937-ൽ നൊബേൽ ലഭിച്ചു.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Vitamin_C"},
  {"topic": "ജീവശാസ്ത്രവും ആരോഗ്യവും", "title": "ജീവകം A കുറവ്: നിശാന്ധത, സീറോഫ്താൽമിയ", "body": "ജീവകം A-യുടെ കുറവ് കണ്ണിൽ റോഡോപ്സിൻ ഉൽപാദനം കുറച്ച് നിശാന്ധതയ്ക്ക് കാരണമാകുന്നു; ഇത് മൂർച്ഛിച്ച് കണ്ണ് വരളുന്ന അവസ്ഥയാണ് സീറോഫ്താൽമിയ. ജന്തുജന്യ ഭക്ഷണത്തിലുള്ള റെറ്റിനോൾ ജീവകം A-യുടെ ഒരു സജീവരൂപമാണ്.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Vitamin_A_deficiency"},
  {"topic": "ജീവശാസ്ത്രവും ആരോഗ്യവും", "title": "ജീവകം D കുറവ്: കണ (റിക്കറ്റ്സ്)", "body": "കുട്ടികളിൽ അസ്ഥികൾ ബലഹീനമാകുന്ന കണ (റിക്കറ്റ്സ്) രോഗത്തിന്റെ പ്രധാന കാരണം ജീവകം D-യുടെ കുറവാണ്; മുതിർന്നവരിൽ ഇതിന് സമാനമായ അവസ്ഥ ഓസ്റ്റിയോമലേഷ്യ. സൂര്യപ്രകാശമേൽക്കുമ്പോൾ ചർമ്മം ജീവകം D നിർമ്മിക്കുന്നു; D3 കോൾകാൽസിഫെറോൾ ആണ്.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Rickets"},
  {"topic": "ജീവശാസ്ത്രവും ആരോഗ്യവും", "title": "ജീവകം B1 (തയമിൻ) കുറവ്: ബെറിബെറി", "body": "തയമിൻ (ജീവകം B1) കുറവുമൂലമുള്ള രോഗമാണ് ബെറിബെറി. തവിട് നീക്കിയ വെള്ള അരി (പോളിഷ്ഡ് റൈസ്) മുഖ്യാഹാരമാക്കുന്നത് പ്രധാന കാരണമാണ്. ഹൃദയത്തെ ബാധിക്കുന്ന 'വെറ്റ്', നാഡികളെ ബാധിക്കുന്ന 'ഡ്രൈ' എന്നിങ്ങനെ രണ്ട് തരമുണ്ട്.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Beriberi"},
  {"topic": "ജീവശാസ്ത്രവും ആരോഗ്യവും", "title": "ജീവകം B3 (നിയാസിൻ) കുറവ്: പെല്ലാഗ്ര", "body": "നിയാസിൻ (ജീവകം B3) കുറവുമൂലമുണ്ടാകുന്ന രോഗമാണ് പെല്ലാഗ്ര. വയറിളക്കം (Diarrhoea), ചർമ്മവീക്കം (Dermatitis), മറവിരോഗം (Dementia), മരണം (Death) എന്നീ 'നാല് D'കളാണ് ഇതിന്റെ ലക്ഷണങ്ങളായി പറയുന്നത്.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Pellagra"}],
 [{"topic": "ഇന്ത്യൻ ഭരണഘടന", "title": "91-ാം ഭേദഗതി: മന്ത്രിസഭ പരമാവധി 15%", "body": "2004-ൽ പ്രാബല്യത്തിൽ വന്ന 91-ാം ഭേദഗതി പ്രധാനമന്ത്രി ഉൾപ്പെടെയുള്ള മന്ത്രിസഭയുടെ അംഗസംഖ്യ ലോക്‌സഭയുടെ (സംസ്ഥാനങ്ങളിൽ നിയമസഭയുടെ) ആകെ അംഗങ്ങളുടെ 15% ആയി പരിമിതപ്പെടുത്തി. കൂറുമാറ്റ നിരോധന വ്യവസ്ഥകളും ഇത് കർശനമാക്കി.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/List_of_amendments_of_the_Constitution_of_India"},
  {"topic": "ഇന്ത്യൻ ഭരണഘടന", "title": "73-ാം ഭേദഗതി: പഞ്ചായത്തീരാജ്", "body": "73-ാം ഭേദഗതി (1992) 1993 ഏപ്രിൽ 24-ന് പ്രാബല്യത്തിൽ വന്നു. ഭാഗം IX (അനുച്ഛേദം 243–243O) പഞ്ചായത്തുകൾക്ക് ഭരണഘടനാ പദവി നൽകി; 29 വിഷയങ്ങളുള്ള പതിനൊന്നാം പട്ടിക ചേർത്തു. അഞ്ചു വർഷം കൂടുമ്പോൾ തിരഞ്ഞെടുപ്പ് നിർബന്ധമാക്കി.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Seventy-third_Amendment_of_the_Constitution_of_India"},
  {"topic": "ഇന്ത്യൻ ഭരണഘടന", "title": "74-ാം ഭേദഗതി: നഗരപാലികകൾ", "body": "74-ാം ഭേദഗതി (1992) 1993 ജൂൺ 1-ന് പ്രാബല്യത്തിൽ വന്നു. ഭാഗം IXA നഗരസഭകൾക്ക് ഭരണഘടനാ പദവി നൽകി; ഇത് ചേർത്ത പന്ത്രണ്ടാം പട്ടികയിൽ നഗരസഭകൾക്കുള്ള 18 ചുമതലകളാണ് (അനുച്ഛേദം 243W).", "source": "GKToday", "url": "https://www.gktoday.in/article-243-w"},
  {"topic": "ഇന്ത്യൻ ഭരണഘടന", "title": "പൗരത്വം: ഭാഗം II, അനുച്ഛേദം 5–11", "body": "ഭരണഘടനയുടെ ഭാഗം II-ലെ അനുച്ഛേദങ്ങൾ 5 മുതൽ 11 വരെയാണ് പൗരത്വത്തെക്കുറിച്ച് പറയുന്നത്. പൗരത്വം നിയമം വഴി നിയന്ത്രിക്കാൻ പാർലമെന്റിന് അധികാരം നൽകുന്നത് അനുച്ഛേദം 11 ആണ്; ഇതനുസരിച്ച് പൗരത്വ നിയമം 1955-ൽ പാസാക്കി.", "source": "constitutionofindia.net", "url": "https://www.constitutionofindia.net/parts/part-ii/"},
  {"topic": "ഇന്ത്യൻ ഭരണഘടന", "title": "അനുച്ഛേദം 19: ആറ് സ്വാതന്ത്ര്യങ്ങൾ", "body": "അനുച്ഛേദം 19 പൗരന്മാർക്ക് ആറ് സ്വാതന്ത്ര്യങ്ങൾ ഉറപ്പുനൽകുന്നു: അഭിപ്രായ-ആവിഷ്കാര സ്വാതന്ത്ര്യം, ആയുധമില്ലാതെ സമാധാനപരമായി സമ്മേളിക്കൽ, സംഘടന രൂപീകരിക്കൽ, ഇന്ത്യയിലുടനീളം സഞ്ചാരം, താമസം, ഏത് തൊഴിലും ചെയ്യാനുള്ള സ്വാതന്ത്ര്യം.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Fundamental_rights_in_India"},
  {"topic": "ഇന്ത്യൻ ഭരണഘടന", "title": "അനുച്ഛേദം 24: ബാലവേല നിരോധനം", "body": "14 വയസ്സിൽ താഴെയുള്ള കുട്ടികളെ ഫാക്ടറികളിലും ഖനികളിലും മറ്റ് അപകടകരമായ ജോലികളിലും നിയോഗിക്കുന്നത് അനുച്ഛേദം 24 നിരോധിക്കുന്നു. അനുച്ഛേദം 23–24 ആണ് ‘ചൂഷണത്തിനെതിരായ അവകാശം’.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Fundamental_rights_in_India"},
  {"topic": "ഇന്ത്യൻ ഭരണഘടന", "title": "മതസ്വാതന്ത്ര്യം: അനുച്ഛേദം 25–28", "body": "അനുച്ഛേദങ്ങൾ 25 മുതൽ 28 വരെ മതസ്വാതന്ത്ര്യത്തിനുള്ള അവകാശമാണ്: മനസ്സാക്ഷി സ്വാതന്ത്ര്യവും മതം ആചരിക്കാനുള്ള സ്വാതന്ത്ര്യവും. അനുച്ഛേദം 29–30 ന്യൂനപക്ഷങ്ങളുടെ സാംസ്കാരിക-വിദ്യാഭ്യാസ അവകാശങ്ങളാണ്.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Fundamental_rights_in_India"},
  {"topic": "ഇന്ത്യൻ ഭരണഘടന", "title": "സ്വത്തവകാശം നീക്കിയത് 44-ാം ഭേദഗതി", "body": "1978-ലെ 44-ാം ഭേദഗതി സ്വത്തവകാശത്തെ മൗലികാവകാശങ്ങളുടെ പട്ടികയിൽനിന്ന് നീക്കം ചെയ്തു; അത് അനുച്ഛേദം 300A പ്രകാരമുള്ള നിയമപരമായ അവകാശമായി. അതിനാൽ ഇന്ന് സ്വത്തവകാശം മൗലികാവകാശമല്ല; ലംഘിക്കപ്പെട്ടാൽ അനുച്ഛേദം 32 പ്രകാരം നേരിട്ട് സുപ്രീം കോടതിയെ സമീപിക്കാനാവില്ല.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Fundamental_rights_in_India"},
  {"topic": "ഇന്ത്യൻ ഭരണഘടന", "title": "ഭരണഘടനയിലെ 5 റിട്ടുകൾ", "body": "ഭരണഘടന അഞ്ച് റിട്ടുകൾ നൽകുന്നു: ഹേബിയസ് കോർപസ്, മാൻഡമസ്, പ്രൊഹിബിഷൻ, സെർഷ്യോററി, ക്വോ വാറന്റോ. മൗലികാവകാശ സംരക്ഷണത്തിന് സുപ്രീം കോടതി അനുച്ഛേദം 32 പ്രകാരവും ഹൈക്കോടതികൾ അനുച്ഛേദം 226 പ്രകാരവും റിട്ട് പുറപ്പെടുവിക്കുന്നു.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Writ"},
  {"topic": "ഇന്ത്യൻ ഭരണഘടന", "title": "ഹേബിയസ് കോർപസ്: ‘ശരീരം ഹാജരാക്കുക’", "body": "അന്യായമായി തടവിലാക്കിയ ആളെ കോടതിയിൽ ഹാജരാക്കാൻ ഉത്തരവിടുന്ന റിട്ടാണ് ഹേബിയസ് കോർപസ്; തടങ്കൽ നിയമവിരുദ്ധമെങ്കിൽ മോചിപ്പിക്കും. അർഹതയില്ലാതെ പൊതുപദവി കൈവശം വയ്ക്കുന്നയാൾക്കെതിരെ ‘ഏത് അധികാരത്തിൽ’ എന്ന് ചോദിക്കുന്നത് ക്വോ വാറന്റോ.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Writ"}],
 [{"topic": "ആനുകാലികം", "title": "2025 ചാമ്പ്യൻസ് ട്രോഫി: ഇന്ത്യ", "body": "2025 മാർച്ച് 9-ന് ദുബായിൽ നടന്ന ഫൈനലിൽ ന്യൂസിലൻഡിനെ 4 വിക്കറ്റിന് തോൽപ്പിച്ച് ഇന്ത്യ ഐ.സി.സി. ചാമ്പ്യൻസ് ട്രോഫി നേടി; 2002, 2013-നുശേഷം ഇന്ത്യയുടെ മൂന്നാം കിരീടം. ക്യാപ്റ്റൻ രോഹിത് ശർമ (76) ഫൈനലിലെ താരം.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/2025_ICC_Champions_Trophy_final"},
  {"topic": "ആനുകാലികം", "title": "വനിതാ ഏകദിന ലോകകപ്പ് 2025: ഇന്ത്യ", "body": "2025 നവംബർ 2-ന് നവി മുംബൈയിലെ ഡി.വൈ. പാട്ടീൽ സ്റ്റേഡിയത്തിൽ ദക്ഷിണാഫ്രിക്കയെ 52 റൺസിന് തോൽപ്പിച്ച് ഇന്ത്യൻ വനിതകൾ ആദ്യമായി ഏകദിന ലോകകപ്പ് നേടി. ഫൈനലിലെ താരം ഷഫാലി വർമ; ടൂർണമെന്റിലെ താരം ദീപ്തി ശർമ.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/2025_Women%27s_Cricket_World_Cup_final"},
  {"topic": "ആനുകാലികം", "title": "ഡി. ഗുകേഷ്: ലോക ചെസ് ചാമ്പ്യൻ (2024)", "body": "2024 ഡിസംബർ 12-ന് സിംഗപ്പൂരിൽ ചൈനയുടെ ഡിങ് ലിറനെ 7½–6½ന് തോൽപ്പിച്ച് ഡി. ഗുകേഷ് ലോക ചെസ് ചാമ്പ്യനായി. 18-ാം വയസ്സിൽ, തർക്കമറ്റ ലോക ചാമ്പ്യനാകുന്ന ഏറ്റവും പ്രായം കുറഞ്ഞയാൾ; കാസ്പറോവിന്റെ റെക്കോർഡ് മറികടന്നു.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Gukesh_Dommaraju"},
  {"topic": "ആനുകാലികം", "title": "പാരിസ് ഒളിമ്പിക്സ് 2024: ഇന്ത്യക്ക് 6 മെഡൽ", "body": "2024 ജൂലൈ–ഓഗസ്റ്റിൽ നടന്ന പാരിസ് ഒളിമ്പിക്സിൽ ഇന്ത്യ 1 വെള്ളിയും 5 വെങ്കലവും നേടി (71-ാം സ്ഥാനം). വെള്ളി: നീരജ് ചോപ്ര (ജാവലിൻ). വെങ്കലം: മനു ഭാക്കർ (2), സരബ്ജോത് സിങ്, സ്വപ്നിൽ കുസാലെ, പുരുഷ ഹോക്കി ടീം, അമൻ സെഹ്‌രാവത്ത്.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/India_at_the_2024_Summer_Olympics"},
  {"topic": "ആനുകാലികം", "title": "മനു ഭാക്കർ: ഒരു ഒളിമ്പിക്സിൽ 2 മെഡൽ", "body": "2024 ജൂലൈയിൽ പാരിസ് ഒളിമ്പിക്സിൽ 10 മീ. എയർ പിസ്റ്റൾ വ്യക്തിഗത വെങ്കലവും സരബ്ജോത് സിങ്ങിനൊപ്പം മിക്സഡ് ടീം വെങ്കലവും നേടി. സ്വാതന്ത്ര്യാനന്തരം ഒരു ഒളിമ്പിക്സിൽ രണ്ട് മെഡൽ നേടുന്ന ആദ്യ ഇന്ത്യൻ താരം.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/India_at_the_2024_Summer_Olympics"},
  {"topic": "ആനുകാലികം", "title": "ശ്രീജേഷിന്റെ 16-ാം നമ്പർ ജഴ്സി പിൻവലിച്ചു", "body": "2024 ഓഗസ്റ്റിൽ പാരിസ് ഒളിമ്പിക്സിൽ ഹോക്കി വെങ്കലം നേടിയശേഷം മലയാളി ഗോൾകീപ്പർ പി.ആർ. ശ്രീജേഷ് അന്താരാഷ്ട്ര ഹോക്കിയിൽനിന്ന് വിരമിച്ചു. ഹോക്കി ഇന്ത്യ അദ്ദേഹത്തിന്റെ 16-ാം നമ്പർ ജഴ്സി പിൻവലിച്ചു; 2025-ൽ പത്മഭൂഷൺ ലഭിച്ചു.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/P._R._Sreejesh"},
  {"topic": "ആനുകാലികം", "title": "ദിവ്യ ദേശ്മുഖ്: വനിതാ ചെസ് ലോകകപ്പ്", "body": "2025 ജൂലൈയിൽ ജോർജിയയിലെ ബാത്തുമിയിൽ നടന്ന ഫിഡെ വനിതാ ചെസ് ലോകകപ്പിന്റെ ഫൈനലിൽ ഇന്ത്യയുടെ തന്നെ കൊനേരു ഹംപിയെ തോൽപ്പിച്ച് ദിവ്യ ദേശ്മുഖ് ജേതാവായി. ഇതോടെ 2026 വനിതാ കാൻഡിഡേറ്റ്സ് ടൂർണമെന്റിന് യോഗ്യത നേടി.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Women%27s_Chess_World_Cup_2025"},
  {"topic": "ആനുകാലികം", "title": "2026 ഏഷ്യൻ ഗെയിംസ്: ഇന്ത്യക്ക് 85 മെഡൽ", "body": "2026 ഒക്ടോബറിൽ സമാപിച്ച ജപ്പാനിലെ ഐച്ചി–നഗോയ ഏഷ്യൻ ഗെയിംസിൽ ഇന്ത്യ 21 സ്വർണം, 27 വെള്ളി, 37 വെങ്കലം ഉൾപ്പെടെ 85 മെഡലുമായി നാലാമതെത്തി; ചൈന ഒന്നാമത്. ഇന്ത്യയുടെ റെക്കോർഡ് 2023-ൽ നടന്ന ഹാങ്ചൗ ഗെയിംസിലെ 107 മെഡൽ.", "source": "The Week", "url": "https://www.theweek.in/news/sports/2026/10/03/asian-games-2026-india-finishes-fourth-with-85-medals-after-late-gold-rush.html"},
  {"topic": "ആനുകാലികം", "title": "ഗ്ലാസ്ഗോ കോമൺവെൽത്ത് ഗെയിംസ് 2026", "body": "2026 ജൂലൈ–ഓഗസ്റ്റിൽ സ്കോട്ട്ലൻഡിലെ ഗ്ലാസ്ഗോയിൽ നടന്ന കോമൺവെൽത്ത് ഗെയിംസിൽ ഇന്ത്യ 13 സ്വർണം, 17 വെള്ളി, 9 വെങ്കലം ഉൾപ്പെടെ 39 മെഡലുകളുമായി മെഡൽപ്പട്ടികയിൽ നാലാം സ്ഥാനം നേടി.", "source": "Gulf News", "url": "https://gulfnews.com/sport/pm-modi-hails-indias-success-at-commonwealth-games-1.500628847"},
  {"topic": "ആനുകാലികം", "title": "കേരളം ആദ്യമായി രഞ്ജി ട്രോഫി ഫൈനലിൽ", "body": "2024–25 സീസണിൽ കേരളം ആദ്യമായി രഞ്ജി ട്രോഫി ഫൈനലിലെത്തി. 2025 ഫെബ്രുവരി–മാർച്ചിൽ നാഗ്പൂരിൽ നടന്ന ഫൈനൽ സമനിലയിലായെങ്കിലും ഒന്നാം ഇന്നിങ്സ് ലീഡിന്റെ ബലത്തിൽ വിദർഭ ജേതാക്കളായി; കേരളം റണ്ണേഴ്സ് അപ്പ്.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Kerala_cricket_team"}],
 [{"topic": "General English", "title": "Collective nouns: pride, herd, shoal", "body": "A pride of lions; a herd of deer, cattle or elephants; a shoal (or school) of fish; a swarm of bees or flies. (സമൂഹനാമം) PSC repeatedly asks 'a ___ of lions' → pride and 'a ___ of fish' → shoal.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/List_of_English_terms_of_venery,_by_animal"},
  {"topic": "General English", "title": "Collective nouns: flock, troop, pack", "body": "A flock of sheep; a troop of monkeys; a pack of wolves; a gaggle of geese; a convocation of eagles. PSC has asked 'A group of eagles is called' → a convocation of eagles. (സമൂഹനാമം)", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/List_of_English_terms_of_venery,_by_animal"},
  {"topic": "General English", "title": "Monogamy, polygyny, polyandry", "body": "Monogamy – having only one partner/spouse at a time (ഏകപത്നീവ്രതം); polygamy – more than one spouse; polygyny – one man with several wives; polyandry – one woman with several husbands at the same time (ബഹുഭർതൃത്വം).", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Monogamy"},
  {"topic": "General English", "title": "One word: theist, atheist, misogynist", "body": "Theist – one who believes in God (ഈശ്വരവിശ്വാസി); atheist – its antonym, one who denies God's existence; misogynist – one who hates women (Greek misos 'hate' + gynē 'woman'). Opposite of misogynist: philogynist.", "source": "Wiktionary", "url": "https://en.wiktionary.org/wiki/misogynist"},
  {"topic": "General English", "title": "Omniscient, omnipotent, omnipresent", "body": "From Latin omnis, 'all': omniscient – having total knowledge, all-knowing (സർവജ്ഞൻ); omnipotent – having unlimited power (സർവശക്തൻ); omnipresent – present everywhere at the same time (സർവവ്യാപി).", "source": "Wiktionary", "url": "https://en.wiktionary.org/wiki/omniscient"},
  {"topic": "General English", "title": "Pandemonium, vagabond, arsonist", "body": "Pandemonium – wild, noisy disorder (coined by Milton in Paradise Lost); vagabond – one who wanders with no fixed home; arsonist – one who deliberately sets fire to property; aborigines – the original inhabitants of a place.", "source": "Wiktionary", "url": "https://en.wiktionary.org/wiki/pandemonium"},
  {"topic": "General English", "title": "Latin: ab initio, status quo, bona fide", "body": "Ab initio – from the beginning; status quo – the existing state of affairs; bona fide – genuine, in good faith (opposite: mala fide); viva voce – orally, by word of mouth (also an oral examination).", "source": "Wiktionary", "url": "https://en.wiktionary.org/wiki/ab_initio"},
  {"topic": "General English", "title": "Idioms: blue moon, sixes and sevens", "body": "Once in a blue moon – very rarely; at sixes and sevens – in confusion or disorder; hit the nail on the head – say exactly the right thing; a red-letter day – a memorable, happy day. (ശൈലികൾ)", "source": "Wiktionary", "url": "https://en.wiktionary.org/wiki/at_sixes_and_sevens"},
  {"topic": "General English", "title": "Idioms: white elephant, swan song", "body": "A white elephant – a costly possession that is a burden; swan song – a final performance before retirement; a fish out of water – someone uneasy in unfamiliar surroundings; by fits and starts – irregularly, stopping and restarting.", "source": "Wiktionary", "url": "https://en.wiktionary.org/wiki/white_elephant"},
  {"topic": "General English", "title": "Licence/license, advice/advise, fewer", "body": "In British usage licence is the noun ('driving licence') and license the verb. Advice is the noun ('the teacher's advice'), advise the verb. Use fewer with countable nouns ('fewer pens'), less with uncountable ones ('less sugar').", "source": "Wiktionary", "url": "https://en.wiktionary.org/wiki/licence"}],
 [{"topic": "സാമ്പത്തികശാസ്ത്രം", "title": "RBI: ഹിൽട്ടൺ യങ് കമ്മീഷൻ ശുപാർശ", "body": "1926-ലെ ഹിൽട്ടൺ യങ് കമ്മീഷന്റെ (Royal Commission on Indian Currency and Finance) ശുപാർശപ്രകാരമാണ് റിസർവ് ബാങ്ക് സ്ഥാപിച്ചത്. കേന്ദ്ര ഓഫീസ് ആദ്യം കൊൽക്കത്തയിലായിരുന്നു; 1937-ൽ മുംബൈയിലേക്ക് മാറ്റി.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Reserve_Bank_of_India"},
  {"topic": "സാമ്പത്തികശാസ്ത്രം", "title": "ബാങ്കുകളുടെ ബാങ്ക്: റിസർവ് ബാങ്ക്", "body": "ഷെഡ്യൂൾഡ് ബാങ്കുകളുടെ അക്കൗണ്ടുകൾ സൂക്ഷിക്കുകയും ബാങ്കുകൾ തമ്മിലുള്ള ചെക്ക് ക്ലിയറിങ് സുഗമമാക്കുകയും ചെയ്യുന്നതിനാൽ RBI 'ബാങ്കുകളുടെ ബാങ്ക്' ആണ്. പ്രതിസന്ധിയിൽ ബാങ്കുകൾക്ക് അടിയന്തര വായ്പ നൽകുന്ന 'അവസാന ആശ്രയ വായ്പാദാതാവ്' (lender of last resort) കൂടിയാണ്.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Reserve_Bank_of_India"},
  {"topic": "സാമ്പത്തികശാസ്ത്രം", "title": "റിവേഴ്സ് റിപ്പോ നിരക്ക്", "body": "ബാങ്കുകൾ അധികമുള്ള പണം റിസർവ് ബാങ്കിൽ നിക്ഷേപിക്കുമ്പോൾ RBI നൽകുന്ന പലിശനിരക്കാണ് റിവേഴ്സ് റിപ്പോ; ഇതിലൂടെ വിപണിയിലെ അധിക പണലഭ്യത RBI പിൻവലിക്കുന്നു. 2022 ഏപ്രിൽ മുതൽ പലിശ ഇടനാഴിയുടെ താഴത്തെ പരിധിയായി ഇതിനു പകരം Standing Deposit Facility (SDF) വന്നു.", "source": "Bajaj Finserv AMC", "url": "https://www.bajajamc.com/knowledge-centre/what-is-reverse-repo-rate"},
  {"topic": "സാമ്പത്തികശാസ്ത്രം", "title": "നബാർഡ്: 1982 ജൂലൈ 12", "body": "കാർഷിക-ഗ്രാമീണ വികസനത്തിനുള്ള പരമോന്നത ബാങ്കായ NABARD 1981-ലെ നിയമപ്രകാരം 1982 ജൂലൈ 12-ന് നിലവിൽ വന്നു. ബി. ശിവരാമൻ അധ്യക്ഷനായ CRAFICARD സമിതിയുടെ ശുപാർശപ്രകാരം; ആസ്ഥാനം മുംബൈ.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/NABARD"},
  {"topic": "സാമ്പത്തികശാസ്ത്രം", "title": "പ്രാദേശിക ഗ്രാമീണ ബാങ്കുകൾ: 1975", "body": "നരസിംഹം കമ്മിറ്റി ശുപാർശപ്രകാരം 1975 ഒക്ടോബർ 2-ന് ആദ്യ റീജിയണൽ റൂറൽ ബാങ്കുകൾ (RRB) തുടങ്ങി. ആദ്യത്തേത് മൊറാദാബാദ് ആസ്ഥാനമായ പ്രഥമ ബാങ്ക്. ഓഹരി: കേന്ദ്രം 50%, സ്പോൺസർ ബാങ്ക് 35%, സംസ്ഥാനം 15%.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Regional_Rural_Bank"},
  {"topic": "സാമ്പത്തികശാസ്ത്രം", "title": "ഇൻഷുറൻസ് ദേശസാൽക്കരണം: 1956, 1972", "body": "1956 സെപ്റ്റംബർ 1-ന് LIC നിയമപ്രകാരം ലൈഫ് ഇൻഷുറൻസ് കോർപ്പറേഷൻ നിലവിൽ വന്നതോടെ ലൈഫ് ഇൻഷുറൻസ് ദേശസാൽക്കരിച്ചു. ജനറൽ ഇൻഷുറൻസ് ദേശസാൽക്കരിച്ചത് 1972-ലെ General Insurance Business (Nationalisation) Act പ്രകാരം.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Life_Insurance_Corporation"},
  {"topic": "സാമ്പത്തികശാസ്ത്രം", "title": "GST കൗൺസിൽ: അനുച്ഛേദം 279A", "body": "അനുച്ഛേദം 279A പ്രകാരമുള്ള GST കൗൺസിൽ കേന്ദ്രവും സംസ്ഥാനങ്ങളും ചേർന്ന സംയുക്ത വേദിയാണ്. കേന്ദ്ര ധനമന്ത്രിയാണ് അധ്യക്ഷൻ; റവന്യൂ ചുമതലയുള്ള കേന്ദ്ര സഹമന്ത്രിയും സംസ്ഥാനങ്ങളിലെ ധനമന്ത്രിമാരും അംഗങ്ങൾ.", "source": "GST Council", "url": "https://gstcouncil.gov.in/en/gst-council"},
  {"topic": "സാമ്പത്തികശാസ്ത്രം", "title": "രംഗരാജൻ കമ്മിറ്റി ദാരിദ്ര്യരേഖ (2014)", "body": "2014-ലെ സി. രംഗരാജൻ കമ്മിറ്റി ടെണ്ടുൽക്കർ രീതി പരിഷ്കരിച്ചു: ഗ്രാമങ്ങളിൽ പ്രതിദിനം ₹32 (₹972/മാസം), നഗരങ്ങളിൽ ₹47 (₹1,407/മാസം). ഈ കണക്കിൽ 2011–12-ൽ ദരിദ്രർ 29.5%.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Poverty_in_India"},
  {"topic": "സാമ്പത്തികശാസ്ത്രം", "title": "ഹരിതവിപ്ലവം: എം.എസ്. സ്വാമിനാഥൻ", "body": "ഇന്ത്യൻ ഹരിതവിപ്ലവത്തിന്റെ പിതാവ് എം.എസ്. സ്വാമിനാഥൻ; ആഗോള ഹരിതവിപ്ലവത്തിന് തുടക്കമിട്ടത് നോർമൻ ബോർലോഗ്. 1960-കളിൽ ആദ്യം പഞ്ചാബിൽ തുടങ്ങി; ഗോതമ്പിനും നെല്ലിനുമാണ് പ്രധാന നേട്ടം.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Green_Revolution_in_India"},
  {"topic": "സാമ്പത്തികശാസ്ത്രം", "title": "നിറവിപ്ലവങ്ങൾ: നീല, വെള്ളി, മഞ്ഞ", "body": "നീലവിപ്ലവം – മത്സ്യം; വെള്ളി (സിൽവർ) വിപ്ലവം – മുട്ട/കോഴി; മഞ്ഞവിപ്ലവം – എണ്ണക്കുരുക്കൾ; സുവർണ വിപ്ലവം – പഴങ്ങൾ, തേൻ, ഹോർട്ടികൾച്ചർ; ഉരുണ്ട (Round) വിപ്ലവം – ഉരുളക്കിഴങ്ങ്; ചാരവിപ്ലവം – രാസവളം.", "source": "Testbook", "url": "https://testbook.com/blog/agricultural-revolution-in-india"}],
 [{"topic": "കമ്പ്യൂട്ടർ അടിസ്ഥാനങ്ങൾ", "title": "URL: യൂണിഫോം റിസോഴ്സ് ലൊക്കേറ്റർ", "body": "വെബ് വിലാസമായ URL-ന്റെ പൂർണരൂപം Uniform Resource Locator. https://www.example.com/index.html-ൽ https സ്കീം (പ്രോട്ടോക്കോൾ), www.example.com ഡൊമെയ്ൻ, index.html ഫയൽ. 1994-ൽ RFC 1738-ൽ ടിം ബെർണേഴ്സ് ലീ നിർവചിച്ചു.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/URL"},
  {"topic": "കമ്പ്യൂട്ടർ അടിസ്ഥാനങ്ങൾ", "title": "വൈറസ്, വേം, ട്രോജൻ", "body": "വൈറസ് മറ്റു പ്രോഗ്രാമുകളിൽ സ്വന്തം കോഡ് ചേർത്ത് പെരുകുന്നു; അതിന് ആതിഥേയ പ്രോഗ്രാം വേണം. വേം ആതിഥേയ പ്രോഗ്രാമില്ലാതെ നെറ്റ്‌വർക്കിലൂടെ സ്വയം പടരുന്നു. ട്രോജൻ സാധാരണ സോഫ്റ്റ്‌വെയറായി വേഷംകെട്ടി കബളിപ്പിക്കുന്നു; സാധാരണ സ്വയം പടരില്ല.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Computer_virus"},
  {"topic": "കമ്പ്യൂട്ടർ അടിസ്ഥാനങ്ങൾ", "title": "ഫിഷിങ്: വ്യാജ സന്ദേശംവഴി വിവരമോഷണം", "body": "ബാങ്ക് പോലുള്ള വിശ്വസ്ത സ്ഥാപനത്തിന്റേതെന്ന് തോന്നുന്ന വ്യാജ ഇ-മെയിലോ വെബ്സൈറ്റോ ഉപയോഗിച്ച് പാസ്‌വേഡ് പോലുള്ള രഹസ്യവിവരങ്ങൾ കൈക്കലാക്കുന്ന തട്ടിപ്പാണ് ഫിഷിങ്. ഫോൺ വഴിയുള്ളത് വിഷിങ് (vishing), SMS വഴിയുള്ളത് സ്മിഷിങ് (smishing).", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Phishing"},
  {"topic": "കമ്പ്യൂട്ടർ അടിസ്ഥാനങ്ങൾ", "title": "ഐ.ടി. ആക്ട് 2000: 2000 ഒക്ടോബർ 17", "body": "ഇന്ത്യയുടെ വിവരസാങ്കേതികവിദ്യാ നിയമം (IT Act 2000) 2000 ഒക്ടോബർ 17-ന് പ്രാബല്യത്തിൽ വന്നു; UNCITRAL ഇ-കൊമേഴ്സ് മാതൃകാനിയമം അടിസ്ഥാനമാക്കി. സെക്ഷൻ 66 പ്രകാരം ഹാക്കിങ്ങിന് 3 വർഷം വരെ തടവ്. 2008-ൽ ഭേദഗതി ചെയ്തു.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Information_Technology_Act,_2000"},
  {"topic": "കമ്പ്യൂട്ടർ അടിസ്ഥാനങ്ങൾ", "title": "സൂപ്പർകമ്പ്യൂട്ടർ വേഗം: FLOPS", "body": "സൂപ്പർകമ്പ്യൂട്ടറുകളുടെ പ്രവർത്തനശേഷി അളക്കുന്നത് FLOPS-ൽ (Floating point operations per second) – ഒരു സെക്കൻഡിൽ നടത്തുന്ന ഫ്ലോട്ടിങ് പോയിന്റ് കണക്കുകൂട്ടലുകളുടെ എണ്ണം. TOP500 പട്ടിക LINPACK ബെഞ്ച്മാർക്ക് ഉപയോഗിക്കുന്നു.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/FLOPS"},
  {"topic": "കമ്പ്യൂട്ടർ അടിസ്ഥാനങ്ങൾ", "title": "ENIAC: ആദ്യ പൊതു-ആവശ്യ ഇലക്ട്രോണിക് യന്ത്രം", "body": "ENIAC (Electronic Numerical Integrator and Computer) ആദ്യ പ്രോഗ്രാം ചെയ്യാവുന്ന, പൊതു-ആവശ്യ ഇലക്ട്രോണിക് ഡിജിറ്റൽ കമ്പ്യൂട്ടർ. ജോൺ മോക്ലിയും ജെ. പ്രെസ്പർ എക്കർട്ടും നിർമിച്ചു; 1945-ൽ പൂർത്തിയായി, 1946-ൽ പ്രഖ്യാപിച്ചു. ഏകദേശം 18,000 വാക്വം ട്യൂബുകൾ.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/ENIAC"},
  {"topic": "കമ്പ്യൂട്ടർ അടിസ്ഥാനങ്ങൾ", "title": "UNIVAC I: ആദ്യ ബിസിനസ് കമ്പ്യൂട്ടർ (യു.എസ്.)", "body": "UNIVAC I (Universal Automatic Computer) അമേരിക്കയിൽ ബിസിനസ് ആവശ്യങ്ങൾക്കായി നിർമിച്ച ആദ്യ പൊതു-ആവശ്യ ഇലക്ട്രോണിക് കമ്പ്യൂട്ടർ. ആദ്യ യൂണിറ്റ് 1951-ൽ യു.എസ്. സെൻസസ് ബ്യൂറോ സ്വീകരിച്ചു; ENIAC നിർമിച്ച എക്കർട്ടും മോക്ലിയുമാണ് ശില്പികൾ.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/UNIVAC_I"},
  {"topic": "കമ്പ്യൂട്ടർ അടിസ്ഥാനങ്ങൾ", "title": "കമ്പ്യൂട്ടർ തലമുറകൾ", "body": "ഒന്നാം തലമുറ – വാക്വം ട്യൂബ്; രണ്ടാം തലമുറ – ട്രാൻസിസ്റ്റർ; മൂന്നാം തലമുറ – ഇന്റഗ്രേറ്റഡ് സർക്യൂട്ട് (IC); നാലാം തലമുറ – മൈക്രോപ്രോസസർ (VLSI); അഞ്ചാം തലമുറ – നിർമിതബുദ്ധി (AI) അടിസ്ഥാനമാക്കിയവ.", "source": "GeeksforGeeks", "url": "https://www.geeksforgeeks.org/computer-science-fundamentals/generations-of-computers-computer-fundamentals/"},
  {"topic": "കമ്പ്യൂട്ടർ അടിസ്ഥാനങ്ങൾ", "title": "TIFRAC: ഇന്ത്യയിൽ നിർമിച്ച ആദ്യ കമ്പ്യൂട്ടർ", "body": "മുംബൈയിലെ ടാറ്റ ഇൻസ്റ്റിറ്റ്യൂട്ട് ഓഫ് ഫണ്ടമെന്റൽ റിസർച്ച് വികസിപ്പിച്ച TIFRAC (TIFR Automatic Calculator) ഇന്ത്യയിൽ നിർമിച്ച ആദ്യ കമ്പ്യൂട്ടർ; 1960-ൽ കമ്മീഷൻ ചെയ്തു. ഈ പേര് നൽകിയത് ജവഹർലാൽ നെഹ്റു.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/TIFRAC"},
  {"topic": "കമ്പ്യൂട്ടർ അടിസ്ഥാനങ്ങൾ", "title": "PARAM 8000: ഇന്ത്യയുടെ ആദ്യ സൂപ്പർകമ്പ്യൂട്ടർ", "body": "പുണെയിലെ C-DAC വികസിപ്പിച്ച PARAM 8000 (1991) ഇന്ത്യയുടെ ആദ്യ തദ്ദേശീയ സൂപ്പർകമ്പ്യൂട്ടർ. 'പരം' എന്നാൽ സംസ്കൃതത്തിൽ 'പരമോന്നതം'; PARAllel Machine എന്നതിന്റെ ചുരുക്കവുമാണ്.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/PARAM"}],
 [{"topic": "കേരള ഭൂമിശാസ്ത്രം", "title": "വർക്കല ക്ലിഫ്: ദേശീയ ഭൗമസ്മാരകം", "body": "തിരുവനന്തപുരം ജില്ലയിലെ വർക്കല ക്ലിഫ് 2015-ൽ ജിയോളജിക്കൽ സർവേ ഓഫ് ഇന്ത്യ ദേശീയ ഭൗമശാസ്ത്ര സ്മാരകമായി പ്രഖ്യാപിച്ചു. ‘വർക്കല ഫോർമേഷൻ’ എന്ന അവസാദശിലാപാളികളിൽ ലിഗ്നൈറ്റിന്റെ നേർത്ത അടരുകളും കാണാം.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Varkala"},
  {"topic": "കേരള ഭൂമിശാസ്ത്രം", "title": "അഷ്ടമുടി: കായൽ ടൂറിസത്തിന്റെ കവാടം", "body": "കൊല്ലം ജില്ലയിലെ അഷ്ടമുടിക്കായൽ വലുപ്പത്തിൽ വേമ്പനാടിന് തൊട്ടുപിന്നിൽ രണ്ടാമതാണ്; എട്ടു ശാഖകളുള്ളതിനാലാണ് ‘അഷ്ടമുടി’ എന്ന പേര്. ‘കേരളത്തിലെ കായലുകളിലേക്കുള്ള കവാടം’ എന്നറിയപ്പെടുന്നു; 2002-ൽ റാംസർ സൈറ്റായി. മൺറോ തുരുത്ത് ഇതിലാണ്.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Ashtamudi_Lake"},
  {"topic": "കേരള ഭൂമിശാസ്ത്രം", "title": "ഇരവികുളം: കേരളത്തിലെ ആദ്യ ദേശീയോദ്യാനം", "body": "ഇടുക്കി ജില്ലയിലെ ഇരവികുളം 1978-ൽ കേരളത്തിലെ ആദ്യ ദേശീയോദ്യാനമായി (1975-ൽ വന്യജീവി സങ്കേതം). വംശനാശഭീഷണി നേരിടുന്ന വരയാടിന്റെ (നീലഗിരി താർ) സംരക്ഷണമാണ് ലക്ഷ്യം; ആനമുടി ഈ ഉദ്യാനത്തിനുള്ളിലാണ്, നീലക്കുറിഞ്ഞിയും ഇവിടെ പൂക്കുന്നു.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Eravikulam_National_Park"},
  {"topic": "കേരള ഭൂമിശാസ്ത്രം", "title": "പെരിയാർ: തേക്കടിയിലെ കടുവ സങ്കേതം", "body": "തേക്കടിയിലെ പെരിയാർ 1934-ൽ നെല്ലിക്കാംപട്ടി ഗെയിം സാങ്ച്വറിയായി തുടങ്ങി, 1950-ൽ വന്യജീവി സങ്കേതമായി, 1978-ൽ പ്രോജക്ട് ടൈഗറിന് കീഴിൽ കടുവ സങ്കേതമായി. 1895-ൽ മുല്ലപ്പെരിയാർ അണക്കെട്ട് നിർമിച്ചപ്പോൾ രൂപപ്പെട്ട പെരിയാർ തടാകം ഇതിനുള്ളിലാണ്.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Periyar_National_Park"},
  {"topic": "കേരള ഭൂമിശാസ്ത്രം", "title": "പള്ളിവാസൽ: കേരളത്തിലെ ആദ്യ ജലവൈദ്യുത പദ്ധതി", "body": "ഇടുക്കി ജില്ലയിൽ മൂന്നാറിനടുത്തുള്ള പള്ളിവാസൽ ആണ് കേരളത്തിലെ ആദ്യ ജലവൈദ്യുത പദ്ധതി. ആദ്യ യൂണിറ്റ് 1940 മാർച്ചിൽ ഉദ്ഘാടനം ചെയ്തു. പെരിയാറിന്റെ പോഷകനദിയായ മുതിരപ്പുഴയിലെ ജലമാണ് ഉപയോഗിക്കുന്നത്.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Pallivasal_Hydro_Electric_Project"},
  {"topic": "കേരള ഭൂമിശാസ്ത്രം", "title": "മുല്ലപ്പെരിയാർ അണക്കെട്ട്: 1895", "body": "ഇടുക്കി ജില്ലയിൽ പെരിയാറിലുള്ള മുല്ലപ്പെരിയാർ അണക്കെട്ട് 1895-ൽ കേണൽ ജോൺ പെന്നിക്വിക്കിന്റെ നേതൃത്വത്തിൽ പൂർത്തിയായി. 1886-ലെ 999 വർഷത്തെ പാട്ടക്കരാർ പ്രകാരം കേരളത്തിലാണെങ്കിലും തമിഴ്നാടാണ് അണക്കെട്ട് നിയന്ത്രിക്കുന്നത്.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Mullaperiyar_Dam"},
  {"topic": "കേരള ഭൂമിശാസ്ത്രം", "title": "അതിരപ്പിള്ളി: വലിയ വെള്ളച്ചാട്ടം", "body": "തൃശ്ശൂർ ജില്ലയിൽ ചാലക്കുടിപ്പുഴയിലുള്ള അതിരപ്പിള്ളിയാണ് കേരളത്തിലെ ഏറ്റവും വലിയ വെള്ളച്ചാട്ടം. ‘ദക്ഷിണേന്ത്യയുടെ നയാഗ്ര’ എന്നറിയപ്പെടുന്നു; വാഴച്ചാൽ വെള്ളച്ചാട്ടം തൊട്ടടുത്താണ്.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Athirappilly_Falls"},
  {"topic": "കേരള ഭൂമിശാസ്ത്രം", "title": "ഇടുക്കി വീണ്ടും ഏറ്റവും വലിയ ജില്ല", "body": "1972-ൽ രൂപീകരിച്ച ഇടുക്കി 1998-ൽ കുട്ടമ്പുഴ വില്ലേജ് എറണാകുളത്തേക്ക് മാറിയതോടെ പാലക്കാടിന് പിന്നിലായി. 2023 സെപ്റ്റംബറിൽ കുട്ടമ്പുഴയിലെ ഏകദേശം 12,718 ഹെക്ടർ ഇടമലക്കുടിയോട് ചേർത്തതോടെ ഇടുക്കി വീണ്ടും വിസ്തൃതിയിൽ ഒന്നാമതായി.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Idukki_district"},
  {"topic": "കേരള ഭൂമിശാസ്ത്രം", "title": "ചവറയിലെ കരിമണൽ ധാതുക്കൾ", "body": "കൊല്ലം ജില്ലയിലെ ചവറ തീരത്തെ കരിമണലിൽ ഇൽമനൈറ്റ്, റൂട്ടൈൽ, സിർക്കോൺ, മോണസൈറ്റ്, സില്ലിമനൈറ്റ് എന്നിവയുണ്ട്. 1922-ൽ ഇവിടെനിന്ന് ഇൽമനൈറ്റ് കയറ്റുമതി തുടങ്ങി; കേരള മിനറൽസ് ആൻഡ് മെറ്റൽസ് (KMML) ടൈറ്റാനിയം ഡയോക്സൈഡ് ഉൽപാദിപ്പിക്കുന്നു.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Kerala_Minerals_and_Metals"},
  {"topic": "കേരള ഭൂമിശാസ്ത്രം", "title": "ലാറ്ററൈറ്റ്: പേര് നൽകിയത് അങ്ങാടിപ്പുറത്ത്", "body": "1807-ൽ ഫ്രാൻസിസ് ബുക്കാനൻ ദക്ഷിണേന്ത്യയിൽ ലാറ്ററൈറ്റിനെ ആദ്യമായി വിവരിച്ച് പേരിട്ടു; ആ സ്ഥലം അടയാളപ്പെടുത്തുന്ന സ്മാരകം മലപ്പുറത്തെ അങ്ങാടിപ്പുറത്താണ്. ലാറ്റിനിൽ ‘later’ എന്നാൽ ഇഷ്ടിക; വെട്ടുകല്ലായി കെട്ടിടനിർമാണത്തിന് ഉപയോഗിക്കുന്നു.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Laterite"}],
 [{"topic": "ഇന്ത്യൻ-ലോക ഭൂമിശാസ്ത്രം", "title": "ലക്ഷദ്വീപ്: ഏറ്റവും ചെറിയ കേന്ദ്രഭരണപ്രദേശം", "body": "36 പവിഴദ്വീപുകളുള്ള ലക്ഷദ്വീപ് (ഏകദേശം 32.62 ച.കി.മീ.) ഇന്ത്യയിലെ ഏറ്റവും ചെറിയ കേന്ദ്രഭരണപ്രദേശമാണ്; തലസ്ഥാനം കവരത്തി. തെക്കേയറ്റത്തെ മിനിക്കോയ് ഒൻപത് ഡിഗ്രി ചാനലിന് തെക്കാണ്; മലയാളം അധിക ഔദ്യോഗിക ഭാഷയാണ്.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Lakshadweep"},
  {"topic": "ഇന്ത്യൻ-ലോക ഭൂമിശാസ്ത്രം", "title": "ലഡാക്ക്: തണുത്ത മരുഭൂമി", "body": "കുറഞ്ഞ മഴയും −20 മുതൽ −35 °C വരെ ശൈത്യവുമുള്ള ഉയർന്ന മരുഭൂമിയാണ് ലഡാക്ക്; ‘തണുത്ത മരുഭൂമി’ എന്നറിയപ്പെടുന്നു. 2019 ഒക്ടോബർ 31-ന് കേന്ദ്രഭരണപ്രദേശമായി; ഇന്ത്യയിലെ ഏറ്റവും വലിയ കേന്ദ്രഭരണപ്രദേശമാണ്.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Ladakh"},
  {"topic": "ഇന്ത്യൻ-ലോക ഭൂമിശാസ്ത്രം", "title": "ജോഗ് വെള്ളച്ചാട്ടം: ശരാവതി നദി", "body": "കർണാടകയിലെ ശിവമോഗ ജില്ലയിൽ ശരാവതി നദിയിലാണ് ജോഗ് വെള്ളച്ചാട്ടം (ഏകദേശം 253 മീ.). ഗെരുസൊപ്പ എന്നും അറിയപ്പെടുന്നു; രാജ, റാണി, റോറർ, റോക്കറ്റ് എന്നീ നാല് ധാരകളായാണ് പതിക്കുന്നത്.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Jog_Falls"},
  {"topic": "ഇന്ത്യൻ-ലോക ഭൂമിശാസ്ത്രം", "title": "അറ്റ്ലാന്റിക്: ‘S’ ആകൃതിയിലുള്ള സമുദ്രം", "body": "വലുപ്പത്തിൽ രണ്ടാമത്തെ സമുദ്രമായ അറ്റ്ലാന്റിക് യൂറോപ്പ്-ആഫ്രിക്കയ്ക്കും അമേരിക്കകൾക്കും ഇടയിൽ നീണ്ട ‘S’ ആകൃതിയിലുള്ള തടത്തിലാണ്. മധ്യ-അറ്റ്ലാന്റിക് പർവതനിര അതിനെ രണ്ടായി പകുക്കുന്നു; ആഴമേറിയ ഭാഗം പ്യൂർട്ടോ റിക്കോ ട്രെഞ്ച്.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Atlantic_Ocean"},
  {"topic": "ഇന്ത്യൻ-ലോക ഭൂമിശാസ്ത്രം", "title": "സിംസൺ മരുഭൂമിയും ‘ബിഗ് റെഡും’", "body": "മധ്യ ഓസ്ട്രേലിയയിലെ സിംസൺ മരുഭൂമിയിലെ ഏറ്റവും വലിയ മണൽക്കുന്നാണ് ‘ബിഗ് റെഡ്’ (നപ്പനെറിക്ക, ഏകദേശം 40 മീ.). ലോകത്തിലെ ഏറ്റവും നീളം കൂടിയ സമാന്തര മണൽക്കുന്നുകൾക്ക് പ്രസിദ്ധമാണ് ഈ മരുഭൂമി.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Simpson_Desert"},
  {"topic": "ഇന്ത്യൻ-ലോക ഭൂമിശാസ്ത്രം", "title": "ഗ്രാൻഡ് കാന്യൺ: കൊളറാഡോ നദി", "body": "യു.എസിലെ അരിസോണയിലുള്ള ഗ്രാൻഡ് കാന്യൺ കൊളറാഡോ നദി കൊത്തിയെടുത്ത മഹാമലയിടുക്കാണ്. ഏകദേശം 446 കി.മീ. നീളവും 29 കി.മീ. വരെ വീതിയും 1,857 മീറ്റർ വരെ ആഴവുമുണ്ട്.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Grand_Canyon"},
  {"topic": "ഇന്ത്യൻ-ലോക ഭൂമിശാസ്ത്രം", "title": "എൽ നിനോ: പസഫിക്കിലെ താപവ്യതിയാനം", "body": "മധ്യ-കിഴക്കൻ ഭൂമധ്യരേഖാ പസഫിക്കിൽ സമുദ്രോപരിതലം അസാധാരണമായി ചൂടാകുന്നതാണ് എൽ നിനോ; സ്പാനിഷിൽ ‘ആൺകുട്ടി’ (ഉണ്ണിയേശു). ഇത് സാധാരണയായി ഇന്ത്യൻ മൺസൂണിനെ ദുർബലമാക്കുന്നു; തണുത്ത വിപരീതഘട്ടം ലാ നിന.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/El_Ni%C3%B1o"},
  {"topic": "ഇന്ത്യൻ-ലോക ഭൂമിശാസ്ത്രം", "title": "സമുദ്രജല ലവണാംശം: 3.5%", "body": "തുറന്ന സമുദ്രജലത്തിന്റെ ശരാശരി ലവണാംശം ഏകദേശം 3.5% ആണ് (ഒരു കിലോഗ്രാമിൽ 35 ഗ്രാം ലവണം); കൂടുതലും സോഡിയം, ക്ലോറൈഡ് അയോണുകൾ. നദീമുഖങ്ങളിൽ കുറവും ചെങ്കടൽ പോലുള്ള അടഞ്ഞ കടലുകളിൽ കൂടുതലുമാണ്.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Seawater"},
  {"topic": "ഇന്ത്യൻ-ലോക ഭൂമിശാസ്ത്രം", "title": "പഞ്ചാബ്: സിന്ധുവിന്റെ അഞ്ചു പോഷകനദികൾ", "body": "ഝലം, ചിനാബ്, രാവി, ബിയാസ്, സത്‌ലജ് എന്നീ അഞ്ചു നദികൾ ചേർന്ന് ‘പഞ്ച്നദ്’ ആയി സിന്ധുവിൽ ചേരുന്നു; ‘അഞ്ചു നദികളുടെ നാട്’ എന്ന അർഥത്തിലാണ് പഞ്ചാബ് എന്ന പേര്. ടിബറ്റിൽ ഉത്ഭവിക്കുന്ന സിന്ധു കറാച്ചിക്കടുത്ത് അറബിക്കടലിൽ പതിക്കുന്നു.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Indus_River"},
  {"topic": "ഇന്ത്യൻ-ലോക ഭൂമിശാസ്ത്രം", "title": "ഗോദാവരി: ദക്ഷിണ ഗംഗ", "body": "1,465 കി.മീ. നീളമുള്ള ഗോദാവരി ഗംഗ കഴിഞ്ഞാൽ ഇന്ത്യയിലെ രണ്ടാമത്തെ നീളം കൂടിയ നദിയാണ്. മഹാരാഷ്ട്രയിലെ നാസിക്കിനടുത്ത് ത്രിംബകേശ്വറിൽ ഉത്ഭവിച്ച് ബംഗാൾ ഉൾക്കടലിൽ പതിക്കുന്നു; ‘ദക്ഷിണ ഗംഗ’ എന്നറിയപ്പെടുന്നു.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Godavari_River"}],
 [{"topic": "ഇന്ത്യൻ ചരിത്രം", "title": "ക്രിപ്സ് മിഷൻ 1942: ‘പോസ്റ്റ്-ഡേറ്റഡ് ചെക്ക്’", "body": "1942 മാർച്ചിൽ സ്റ്റാഫോർഡ് ക്രിപ്സ് ഇന്ത്യയിലെത്തി യുദ്ധാനന്തരം ഡൊമിനിയൻ പദവി വാഗ്ദാനം ചെയ്തു. ഇതിനെ ഗാന്ധിജി ‘തകർന്നുകൊണ്ടിരിക്കുന്ന ബാങ്കിൽ നിന്നുള്ള മുൻ‌തീയതിയിട്ട ചെക്ക്’ എന്നു വിശേഷിപ്പിച്ചു.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Cripps_Mission"},
  {"topic": "ഇന്ത്യൻ ചരിത്രം", "title": "സൈമൺ കമ്മീഷനും ലാലാ ലജ്പത് റായിയും", "body": "ഇന്ത്യക്കാരായ അംഗങ്ങളില്ലാത്ത സൈമൺ കമ്മീഷൻ 1928 ഫെബ്രുവരി 3-ന് ബോംബെയിലെത്തി; ‘സൈമൺ ഗോ ബാക്ക്’ മുദ്രാവാക്യത്തോടെ ബഹിഷ്കരിച്ചു. 1928 ഒക്ടോബർ 30-ന് ലാഹോറിലെ ലാത്തിച്ചാർജിൽ പരിക്കേറ്റ ലാലാ ലജ്പത് റായി നവംബർ 17-ന് അന്തരിച്ചു.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Simon_Commission"},
  {"topic": "ഇന്ത്യൻ ചരിത്രം", "title": "വട്ടമേശ സമ്മേളനങ്ങൾ: മൂന്നിലും അംബേദ്കർ", "body": "ലണ്ടനിൽ 1930, 1931, 1932 വർഷങ്ങളിലായി മൂന്ന് വട്ടമേശ സമ്മേളനങ്ങൾ നടന്നു. മൂന്നിലും ഡോ. ബി.ആർ. അംബേദ്കർ പങ്കെടുത്തു; ഗാന്ധിജി കോൺഗ്രസിന്റെ ഏക പ്രതിനിധിയായി രണ്ടാം സമ്മേളനത്തിൽ മാത്രം പങ്കെടുത്തു.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Round_Table_Conferences_(India)"},
  {"topic": "ഇന്ത്യൻ ചരിത്രം", "title": "ഇന്ത്യൻ അസോസിയേഷൻ 1876: സുരേന്ദ്രനാഥ് ബാനർജി", "body": "1876-ൽ സുരേന്ദ്രനാഥ് ബാനർജിയും ആനന്ദമോഹൻ ബോസും ചേർന്ന് ഇന്ത്യൻ അസോസിയേഷൻ രൂപീകരിച്ചു. കൽക്കത്ത കേന്ദ്രമായി പ്രവർത്തിച്ച ഈ സംഘടന കോൺഗ്രസിനു മുമ്പുള്ള പ്രധാന ദേശീയ സംഘടനകളിലൊന്നാണ്.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Indian_Association"},
  {"topic": "ഇന്ത്യൻ ചരിത്രം", "title": "ഒന്നാം പാനിപ്പത്ത് യുദ്ധം: 1526", "body": "1526 ഏപ്രിൽ 21-ന് ഒന്നാം പാനിപ്പത്ത് യുദ്ധത്തിൽ ബാബർ ഡൽഹി സുൽത്താൻ ഇബ്രാഹിം ലോദിയെ പരാജയപ്പെടുത്തി മുഗൾ ഭരണം സ്ഥാപിച്ചു. പീരങ്കികളും തോക്കുകളും ഉപയോഗിച്ച ഇന്ത്യയിലെ ആദ്യകാല യുദ്ധങ്ങളിലൊന്നാണിത്.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/First_Battle_of_Panipat"},
  {"topic": "ഇന്ത്യൻ ചരിത്രം", "title": "ദിൻ ഇലാഹി (1582): അക്ബർ", "body": "മുഗൾ ചക്രവർത്തി അക്ബർ 1582-ൽ ഫത്തേപ്പൂർ സിക്രിയിൽ ദിൻ ഇലാഹി ആരംഭിച്ചു. ‘ദൈവത്തിന്റെ ഏകത്വം’ എന്നർത്ഥമുള്ള തൗഹീദ്-ഇ-ഇലാഹി എന്നായിരുന്നു അക്കാലത്തെ പേര്.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Din-i_Ilahi"},
  {"topic": "ഇന്ത്യൻ ചരിത്രം", "title": "വിജയനഗര സാമ്രാജ്യം: 1336, ഹരിഹരൻ-ബുക്കൻ", "body": "1336-ൽ സംഗമ വംശത്തിലെ ഹരിഹരനും ബുക്കനും ചേർന്ന് വിജയനഗര സാമ്രാജ്യം സ്ഥാപിച്ചു; തലസ്ഥാനം ഇന്നത്തെ ഹംപിക്കടുത്ത്. ഏറ്റവും പ്രശസ്തനായ കൃഷ്ണദേവരായർ (1509–1529) തുളുവ വംശജനായിരുന്നു.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Vijayanagara_Empire"},
  {"topic": "ഇന്ത്യൻ ചരിത്രം", "title": "തളിക്കോട്ട യുദ്ധം 1565: വിജയനഗര തകർച്ച", "body": "1565 ജനുവരി 23-ലെ തളിക്കോട്ട യുദ്ധത്തിൽ ഡെക്കാൻ സുൽത്താനേറ്റുകളുടെ സഖ്യം വിജയനഗരത്തെ തോൽപ്പിച്ചു. വിജയനഗര സേനയെ നയിച്ച അലിയ രാമരായർ കൊല്ലപ്പെട്ടു; തലസ്ഥാനം കൊള്ളയടിക്കപ്പെട്ടു.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Battle_of_Talikota"},
  {"topic": "ഇന്ത്യൻ ചരിത്രം", "title": "അഷ്ടപ്രധാൻ: ശിവജിയുടെ മന്ത്രിസഭ", "body": "ശിവജി 1674-ൽ റായ്ഗഡിൽ കിരീടധാരണ സമയത്ത് എട്ടു മന്ത്രിമാരടങ്ങിയ അഷ്ടപ്രധാൻ രൂപീകരിച്ചു. പ്രധാനമന്ത്രിയെ പേഷ്വ (പന്ത്പ്രധാൻ) എന്നു വിളിച്ചു; ആദ്യ പേഷ്വ മോറോപന്ത് ത്രിംബക് പിംഗ്ലെ.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Ashta_Pradhan"},
  {"topic": "ഇന്ത്യൻ ചരിത്രം", "title": "സമുദ്രഗുപ്തൻ: ‘ഇന്ത്യൻ നെപ്പോളിയൻ’", "body": "ഗുപ്ത രാജാവ് സമുദ്രഗുപ്തനെ സൈനിക വിജയങ്ങൾ കാരണം ചരിത്രകാരൻ വിൻസെന്റ് സ്മിത്ത് ‘ഇന്ത്യൻ നെപ്പോളിയൻ’ എന്നു വിശേഷിപ്പിച്ചു. അദ്ദേഹത്തിന്റെ നേട്ടങ്ങൾ വിവരിക്കുന്ന അലഹബാദ് സ്തംഭലിഖിതം (പ്രയാഗ് പ്രശസ്തി) രചിച്ചത് ഹരിഷേണൻ.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Samudragupta"}],
 [{"topic": "കേരള ചരിത്രം", "title": "കുറിച്യ കലാപം 1812: വയനാട്", "body": "1812-ൽ വയനാട്ടിലെ കുറിച്യരും കുറുമരും ബ്രിട്ടീഷുകാരുടെ റവന്യൂ നയത്തിനെതിരെ കലാപം നടത്തി. നേരത്തേ പഴശ്ശിരാജയുടെ കൂടെ പോരാടിയവരായിരുന്നു ഇവർ; കലാപം ഏതാനും മാസങ്ങൾക്കുള്ളിൽ അടിച്ചമർത്തപ്പെട്ടു.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Early_resistance_to_British_rule_in_Malabar"},
  {"topic": "കേരള ചരിത്രം", "title": "സ്വാതി തിരുനാൾ: രാജാസ് ഫ്രീ സ്കൂൾ 1834", "body": "സ്വാതി തിരുനാൾ (ഭരണം 1813–1846) 1834-ൽ തിരുവനന്തപുരത്ത് ഇംഗ്ലീഷ് സ്കൂൾ ആരംഭിച്ചു; ഇതാണ് പിന്നീട് യൂണിവേഴ്സിറ്റി കോളേജായത്. 1836-ൽ തിരുവിതാംകൂറിലെ ആദ്യ സെൻസസും 1837-ൽ തിരുവനന്തപുരം വാനനിരീക്ഷണകേന്ദ്രവും ആരംഭിച്ചു.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Swathi_Thirunal_Rama_Varma"},
  {"topic": "കേരള ചരിത്രം", "title": "വൈകുണ്ഠസ്വാമികളെ തടവിലാക്കിയത് സ്വാതി തിരുനാൾ", "body": "ജാതിവിവേചനത്തെ എതിർത്ത വൈകുണ്ഠസ്വാമികളെ (അയ്യാ വൈകുണ്ഠർ) 1838-ൽ സ്വാതി തിരുനാൾ അറസ്റ്റ് ചെയ്ത് ശിങ്കാരത്തോപ്പ് ജയിലിൽ 110 ദിവസത്തോളം തടവിലാക്കി. അയ്യാവഴിയുടെ പ്രധാന ഗ്രന്ഥം ‘അഖിലത്തിരട്ട്’.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Ayya_Vaikundar"},
  {"topic": "കേരള ചരിത്രം", "title": "എസ്.എൻ.ഡി.പി. യോഗം: 1903", "body": "1903 മെയ് 15-ന് ശ്രീനാരായണ ധർമ്മ പരിപാലന യോഗം (SNDP) സ്ഥാപിതമായി. ശ്രീനാരായണ ഗുരു ആജീവനാന്ത അധ്യക്ഷനും കുമാരനാശാൻ ആദ്യ ജനറൽ സെക്രട്ടറിയുമായിരുന്നു; ഡോ. പല്പു സ്ഥാപനത്തിന് മുൻകൈയെടുത്തു.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Sree_Narayana_Dharma_Paripalana_Yogam"},
  {"topic": "കേരള ചരിത്രം", "title": "ശ്രീനാരായണ ഗുരു: ചെമ്പഴന്തി മുതൽ ശിവഗിരി വരെ", "body": "ശ്രീനാരായണ ഗുരു 1856-ൽ തിരുവനന്തപുരത്തെ ചെമ്പഴന്തിയിൽ ജനിച്ചു; 1928 സെപ്റ്റംബർ 20-ന് വർക്കല ശിവഗിരിയിൽ സമാധിയായി. ‘ഒരു ജാതി, ഒരു മതം, ഒരു ദൈവം മനുഷ്യന്’ എന്നതായിരുന്നു സന്ദേശം; പ്രധാന കൃതി ‘ആത്മോപദേശ ശതകം’.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Narayana_Guru"},
  {"topic": "കേരള ചരിത്രം", "title": "അയ്യങ്കാളി: ‘പുലയരാജാവ്’", "body": "1863-ൽ വെങ്ങാനൂരിൽ ജനിച്ച അയ്യങ്കാളി ‘പുലയരാജാവ്’ എന്നറിയപ്പെടുന്നു. ശ്രീമൂലം പ്രജാസഭയിൽ അംഗമായി; ഊരൂട്ടമ്പലത്തെ സ്കൂൾ പ്രവേശന പ്രശ്നത്തെ തുടർന്ന് കർഷകത്തൊഴിലാളികളുടെ പണിമുടക്ക് സംഘടിപ്പിച്ചു.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Ayyankali"},
  {"topic": "കേരള ചരിത്രം", "title": "പണ്ഡിറ്റ് കറുപ്പൻ: ജാതിക്കുമ്മി, കേരള ലിങ്കൺ", "body": "പണ്ഡിറ്റ് കറുപ്പന്റെ ‘ജാതിക്കുമ്മി’ (1904) ജാതിവ്യവസ്ഥയെയും അയിത്തത്തെയും വിമർശിച്ചു. പിന്നാക്കവിഭാഗങ്ങളുടെ ഉന്നമനത്തിനായുള്ള പ്രവർത്തനങ്ങൾ കാരണം ‘കേരള ലിങ്കൺ’ എന്നറിയപ്പെടുന്നു; 1913-ൽ ‘വിദ്വാൻ’ ബഹുമതി ലഭിച്ചു.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Pandit_Karuppan"},
  {"topic": "കേരള ചരിത്രം", "title": "വാഗ്ഭടാനന്ദൻ: ആത്മവിദ്യാസംഘം", "body": "കണ്ണൂരിലെ പാട്യത്ത് ജനിച്ച വയലേരി കുഞ്ഞിക്കണ്ണൻ ഗുരുക്കളാണ് വാഗ്ഭടാനന്ദൻ. അദ്ദേഹം ആത്മവിദ്യാസംഘം സ്ഥാപിച്ചു; 1925-ൽ ഊരാളുങ്കൽ ലേബർ കോൺട്രാക്ട് സഹകരണ സംഘം രൂപീകരിച്ചത് അദ്ദേഹത്തിന്റെ പ്രചോദനത്തിലാണ്.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Vagbhatananda"},
  {"topic": "കേരള ചരിത്രം", "title": "പൊയ്കയിൽ അപ്പച്ചൻ: പ്രത്യക്ഷ രക്ഷാ ദൈവസഭ", "body": "ഇരവിപേരൂരിൽ ജനിച്ച പൊയ്കയിൽ യോഹന്നാൻ (പൊയ്കയിൽ അപ്പച്ചൻ) സഭകളിലെ ജാതിവിവേചനത്തിൽ പ്രതിഷേധിച്ച് 1909-ൽ പ്രത്യക്ഷ രക്ഷാ ദൈവസഭ സ്ഥാപിച്ചു. 1921-ലും 1931-ലും ശ്രീമൂലം പ്രജാസഭയിലേക്ക് നാമനിർദേശം ചെയ്യപ്പെട്ടു.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Poykayil_Yohannan"},
  {"topic": "കേരള ചരിത്രം", "title": "എൻ.എസ്.എസ്. 1914: മന്നത്ത് പത്മനാഭൻ", "body": "മന്നത്ത് പത്മനാഭൻ 1914 ഒക്ടോബർ 31-ന് നായർ സർവീസ് സൊസൈറ്റി (NSS) സ്ഥാപിച്ചു. 1959-ലെ വിമോചന സമരത്തിന് നേതൃത്വം നൽകിയ മന്നത്തിന് ‘ഭാരതകേസരി’ ബഹുമതിയും 1966-ൽ പത്മഭൂഷണും ലഭിച്ചു.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Mannathu_Padmanabhan"}],
 [{"topic": "കേരള ഭരണസംവിധാനം", "title": "ത്രിതല പഞ്ചായത്ത്: 941 + 152 + 14", "body": "കേരളത്തിൽ 941 ഗ്രാമപഞ്ചായത്തുകൾ, 152 ബ്ലോക്ക് പഞ്ചായത്തുകൾ, 14 ജില്ലാ പഞ്ചായത്തുകൾ എന്നിങ്ങനെയാണ് ത്രിതല സംവിധാനം. താലൂക്ക് ത്രിതല പഞ്ചായത്തിന്റെ ഭാഗമല്ല; അത് റവന്യൂ ഭരണ യൂണിറ്റാണ്.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Local_government_in_Kerala"},
  {"topic": "കേരള ഭരണസംവിധാനം", "title": "കുടുംബശ്രീ: 1998 മേയ് 17", "body": "കുടുംബശ്രീ മിഷൻ 1998 മേയ് 17-ന് മലപ്പുറത്ത് പ്രധാനമന്ത്രി എ.ബി. വാജ്പേയി ഉദ്ഘാടനം ചെയ്തു. 1999 ഏപ്രിൽ 1 മുതൽ പ്രവർത്തനം തുടങ്ങി. ദാരിദ്ര്യ നിർമ്മാർജനവും സ്ത്രീശാക്തീകരണവുമാണ് ലക്ഷ്യം.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Kudumbashree"},
  {"topic": "കേരള ഭരണസംവിധാനം", "title": "സംസ്ഥാന മനുഷ്യാവകാശ കമ്മീഷൻ: 1998", "body": "കേരള സംസ്ഥാന മനുഷ്യാവകാശ കമ്മീഷൻ 1998 ഡിസംബർ 11-ന് 1993-ലെ മനുഷ്യാവകാശ സംരക്ഷണ നിയമപ്രകാരം രൂപീകരിച്ചു. ആദ്യ അധ്യക്ഷൻ ജസ്റ്റിസ് എം.എം. പരീത് പിള്ള. അധ്യക്ഷനെ കൂടാതെ 2 അംഗങ്ങളാണുള്ളത്.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Kerala_State_Human_Rights_Commission"},
  {"topic": "കേരള ഭരണസംവിധാനം", "title": "സംസ്ഥാന വിവരാവകാശ കമ്മീഷൻ: 2005", "body": "കേരള സംസ്ഥാന വിവരാവകാശ കമ്മീഷൻ 2005 ഡിസംബർ 19-ന് വിവരാവകാശ നിയമം 2005 പ്രകാരം നിലവിൽ വന്നു. ആസ്ഥാനം തിരുവനന്തപുരം. സംസ്ഥാന മുഖ്യ വിവരാവകാശ കമ്മീഷണറാണ് തലവൻ.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Kerala_State_Information_Commission"},
  {"topic": "കേരള ഭരണസംവിധാനം", "title": "കേരള വനിതാ കമ്മീഷൻ: 1996 മാർച്ച് 14", "body": "കേരള വനിതാ കമ്മീഷൻ 1990-ലെ കേരള വനിതാ കമ്മീഷൻ നിയമത്തിലെ 5-ാം വകുപ്പ് പ്രകാരം 1996 മാർച്ച് 14-ന് രൂപീകരിച്ചു. ആസ്ഥാനം തിരുവനന്തപുരം പട്ടം.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Kerala_Women%27s_Commission"},
  {"topic": "കേരള ഭരണസംവിധാനം", "title": "സുഗതകുമാരി: വനിതാ കമ്മീഷൻ അധ്യക്ഷ (1996)", "body": "കവയിത്രി സുഗതകുമാരി 1996-ൽ കേരള സംസ്ഥാന വനിതാ കമ്മീഷൻ അധ്യക്ഷയായി; കമ്മീഷൻ രൂപീകരിച്ച വർഷം തന്നെ. സ്ത്രീകൾക്കും കുട്ടികൾക്കുമെതിരായ അതിക്രമങ്ങൾക്കെതിരെ പതിറ്റാണ്ടുകൾ പോരാടിയ സാമൂഹിക പ്രവർത്തക കൂടിയാണ് അവർ.", "source": "The News Minute", "url": "https://www.thenewsminute.com/article/sugathakumari-fought-atrocities-against-women-and-children-decades-140178"},
  {"topic": "കേരള ഭരണസംവിധാനം", "title": "സംസ്ഥാന തിരഞ്ഞെടുപ്പ് കമ്മീഷൻ: 1993", "body": "കേരള സംസ്ഥാന തിരഞ്ഞെടുപ്പ് കമ്മീഷൻ 1993 ഡിസംബർ 3-ന് ഭരണഘടനയുടെ 243K അനുച്ഛേദപ്രകാരം നിലവിൽ വന്നു. പഞ്ചായത്ത്, മുനിസിപ്പാലിറ്റി, കോർപ്പറേഷൻ തിരഞ്ഞെടുപ്പുകൾ നടത്തുന്നു.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Kerala_State_Election_Commission"},
  {"topic": "കേരള ഭരണസംവിധാനം", "title": "ദുരന്ത നിവാരണ അതോറിറ്റി: 2007", "body": "2005-ലെ ദുരന്ത നിവാരണ നിയമപ്രകാരം കേരള സംസ്ഥാന ദുരന്ത നിവാരണ അതോറിറ്റി 2007 മേയ് 4-ന് രൂപീകരിച്ചു. മുഖ്യമന്ത്രി അധ്യക്ഷനും റവന്യൂ മന്ത്രി ഉപാധ്യക്ഷനുമാണ്.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Kerala_State_Disaster_Management_Authority"},
  {"topic": "കേരള ഭരണസംവിധാനം", "title": "അക്ഷയ: 2002 നവംബർ 18, മലപ്പുറം", "body": "അക്ഷയ പദ്ധതി 2002 നവംബർ 18-ന് മലപ്പുറം ജില്ലയിൽ ആരംഭിച്ചു. കേരള സംസ്ഥാന ഐ.ടി. മിഷനാണ് നടത്തിപ്പ്. ഇതിലൂടെ മലപ്പുറം ഇന്ത്യയിലെ ആദ്യ ഇ-സാക്ഷര ജില്ലയെന്ന് അറിയപ്പെടുന്നു.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Akshaya_project"},
  {"topic": "കേരള ഭരണസംവിധാനം", "title": "കരിമീൻ: സംസ്ഥാന മത്സ്യം (2010)", "body": "2010 ജൂലൈയിൽ കരിമീൻ (Green chromide) കേരളത്തിന്റെ സംസ്ഥാന മത്സ്യമായി പ്രഖ്യാപിച്ചു. 2010–11 'കരിമീൻ വർഷം' ആയി ആചരിച്ചു. കായൽ മത്സ്യമായ കരിമീനിന്റെ കൃഷി പ്രോത്സാഹിപ്പിക്കാനായിരുന്നു ഇത്.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/List_of_Kerala_state_symbols"}],
 [{"topic": "ഭൗതികശാസ്ത്രം", "title": "ഡെസിബൽ: ശബ്ദതീവ്രതയുടെ യൂണിറ്റ്", "body": "ശബ്ദത്തിന്റെ തീവ്രത (ഉച്ചത) അളക്കാൻ ഉപയോഗിക്കുന്ന യൂണിറ്റാണ് ഡെസിബൽ (dB). ഇത് 'ബെൽ' എന്ന യൂണിറ്റിന്റെ പത്തിലൊന്നാണ്; ബെൽ എന്ന പേര് അലക്സാണ്ടർ ഗ്രഹാം ബെല്ലിന്റെ ബഹുമാനാർത്ഥമാണ്.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Decibel"},
  {"topic": "ഭൗതികശാസ്ത്രം", "title": "ISRO സ്ഥാപിതമായത് 1969-ൽ", "body": "ഇന്ത്യൻ ബഹിരാകാശ ഗവേഷണ സംഘടന (ISRO) 1969 ഓഗസ്റ്റിൽ, 1962-ൽ രൂപീകരിച്ച INCOSPAR-ന് പകരമായി സ്ഥാപിതമായി. ഇന്ത്യൻ ബഹിരാകാശ പദ്ധതിയുടെ പിതാവ് ഡോ. വിക്രം സാരാഭായ് ആണ്.", "source": "ISRO", "url": "https://www.isro.gov.in/genesis.html"},
  {"topic": "ഭൗതികശാസ്ത്രം", "title": "ആര്യഭട്ട: ഇന്ത്യയുടെ ആദ്യ ഉപഗ്രഹം", "body": "ഇന്ത്യ പൂർണമായി രൂപകൽപ്പന ചെയ്ത് നിർമ്മിച്ച ആദ്യ ഉപഗ്രഹമായ ആര്യഭട്ട 1975 ഏപ്രിൽ 19-ന് സോവിയറ്റ് യൂണിയനിൽനിന്ന് വിക്ഷേപിച്ചു. 360 കി.ഗ്രാം ഭാരം; പ്രശസ്ത ഭാരതീയ ജ്യോതിശാസ്ത്രജ്ഞന്റെ പേരാണ് നൽകിയത്.", "source": "ISRO", "url": "https://www.isro.gov.in/aryabhata_1.html"},
  {"topic": "ഭൗതികശാസ്ത്രം", "title": "ഹോമി ജെ. ഭാഭ: ആണവോർജ കമ്മീഷൻ", "body": "ഇന്ത്യൻ ആണവ പദ്ധതിയുടെ പിതാവായ ഹോമി ജെ. ഭാഭ 1948-ൽ രൂപീകരിച്ച ആറ്റോമിക് എനർജി കമ്മീഷന്റെ ആദ്യ ചെയർമാനായിരുന്നു. 1945-ൽ TIFR സ്ഥാപിച്ചു; മരണശേഷം ട്രോംബെയിലെ സ്ഥാപനത്തിന് BARC എന്ന് പേരിട്ടു.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Homi_J._Bhabha"},
  {"topic": "ഭൗതികശാസ്ത്രം", "title": "സീസ്മോഗ്രാഫ്: ഭൂകമ്പം രേഖപ്പെടുത്താൻ", "body": "ഭൂകമ്പങ്ങൾ, അഗ്നിപർവത സ്ഫോടനങ്ങൾ എന്നിവ മൂലമുള്ള ഭൂചലനം രേഖപ്പെടുത്തുന്ന ഉപകരണമാണ് സീസ്മോഗ്രാഫ്. ഇത് തയ്യാറാക്കുന്ന രേഖയെ സീസ്മോഗ്രാം എന്നു വിളിക്കുന്നു.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Seismometer"},
  {"topic": "ഭൗതികശാസ്ത്രം", "title": "ആർക്കിമിഡീസ് തത്വം: പ്ലവക്ഷമബലം", "body": "ദ്രാവകത്തിൽ പൂർണമായോ ഭാഗികമായോ മുങ്ങിയ വസ്തുവിന് അനുഭവപ്പെടുന്ന മുകളിലേക്കുള്ള തള്ളൽ (പ്ലവക്ഷമബലം) അത് ആദേശം ചെയ്യുന്ന ദ്രാവകത്തിന്റെ ഭാരത്തിന് തുല്യമാണ്. 'ഓൺ ഫ്ലോട്ടിങ് ബോഡീസ്' എന്ന കൃതിയിലാണ് ഇത് വിവരിച്ചത്.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Archimedes%27_principle"},
  {"topic": "ഭൗതികശാസ്ത്രം", "title": "ഹുക്ക് നിയമം: ഇലാസ്തികത", "body": "ഇലാസ്തിക പരിധിക്കുള്ളിൽ ഒരു സ്പ്രിങ്ങിനെ വലിച്ചുനീട്ടാൻ വേണ്ട ബലം നീളത്തിലുണ്ടാകുന്ന മാറ്റത്തിന് ആനുപാതികമാണ് (F = kx). റോബർട്ട് ഹുക്ക് 1678-ൽ 'ut tensio, sic vis' എന്ന രൂപത്തിൽ ഇത് പ്രസിദ്ധീകരിച്ചു.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Hooke%27s_law"},
  {"topic": "ഭൗതികശാസ്ത്രം", "title": "ഹ്രസ്വദൃഷ്ടിക്ക് കോൺകേവ് ലെൻസ്", "body": "ഹ്രസ്വദൃഷ്ടി (മയോപിയ) ഉള്ളവരിൽ ദൂരെയുള്ള വസ്തുക്കളുടെ പ്രതിബിംബം റെറ്റിനയ്ക്ക് മുന്നിൽ രൂപപ്പെടുന്നു. ഇത് പരിഹരിക്കാൻ നെഗറ്റീവ് പവറുള്ള കോൺകേവ് (വിവ്രജന) ലെൻസ് ഉപയോഗിക്കുന്നു.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Near-sightedness"},
  {"topic": "ഭൗതികശാസ്ത്രം", "title": "ടെസ്‌ല: കാന്തിക ഫ്ലക്സ് സാന്ദ്രത", "body": "കാന്തിക ഫ്ലക്സ് സാന്ദ്രതയുടെ (കാന്തികക്ഷേത്ര ശക്തി, B) SI യൂണിറ്റാണ് ടെസ്‌ല (T). 1960-ലെ ഭാരങ്ങൾക്കും അളവുകൾക്കുമുള്ള പൊതുസമ്മേളനത്തിൽ, ശാസ്ത്രജ്ഞൻ നിക്കോള ടെസ്‌ലയുടെ ബഹുമാനാർത്ഥം ഈ പേര് നൽകി.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Tesla_(unit)"},
  {"topic": "ഭൗതികശാസ്ത്രം", "title": "ടെലിഫോൺ: ഗ്രഹാം ബെൽ, 1876", "body": "അലക്സാണ്ടർ ഗ്രഹാം ബെല്ലിന് ടെലിഫോണിന്റെ യു.എസ്. പേറ്റന്റ് ലഭിച്ചത് 1876 മാർച്ച് 7-നാണ്. മാർച്ച് 10-ന് സഹായി തോമസ് വാട്സണോട് 'Mr. Watson, come here, I want to see you' എന്ന് പറഞ്ഞു.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Invention_of_the_telephone"}],
 [{"topic": "രസതന്ത്രം", "title": "ഉറുമ്പിലെ ആസിഡ്: ഫോർമിക് ആസിഡ്", "body": "ഉറുമ്പുകളിൽ കാണുന്ന ആസിഡാണ് ഫോർമിക് ആസിഡ് (HCOOH). 'ഉറുമ്പ്' എന്നർത്ഥമുള്ള ലാറ്റിൻ പദം 'ഫോർമിക്ക'യിൽനിന്നാണ് പേര്. ഏറ്റവും ലളിതമായ കാർബോക്സിലിക് ആസിഡാണിത്.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Formic_acid"},
  {"topic": "രസതന്ത്രം", "title": "ബോക്സൈറ്റ്: അലുമിനിയത്തിന്റെ അയിര്", "body": "അലുമിനിയത്തിന്റെ പ്രധാന അയിരാണ് ബോക്സൈറ്റ്. ബേയർ പ്രക്രിയയിലൂടെ ഇതിൽനിന്ന് അലുമിന വേർതിരിച്ച്, ഹാൾ-ഹെറൂൾട്ട് വൈദ്യുതവിശ്ലേഷണത്തിലൂടെ അലുമിനിയം നിർമ്മിക്കുന്നു. ഫ്രാൻസിലെ ലെ ബോ എന്ന സ്ഥലത്തുനിന്നാണ് പേര്.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Bauxite"},
  {"topic": "രസതന്ത്രം", "title": "ഡ്യൂട്ടീരിയം: ഘനഹൈഡ്രജൻ", "body": "ഒരു പ്രോട്ടോണും ഒരു ന്യൂട്രോണുമുള്ള ഹൈഡ്രജന്റെ ഐസോടോപ്പാണ് ഡ്യൂട്ടീരിയം (ഘനഹൈഡ്രജൻ). 1931-ൽ ഹാരോൾഡ് യൂറി കണ്ടെത്തി. ഇതടങ്ങിയ ഘനജലം (D₂O) ചില ആണവ റിയാക്ടറുകളിൽ മോഡറേറ്ററായി ഉപയോഗിക്കുന്നു.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Deuterium"},
  {"topic": "രസതന്ത്രം", "title": "ഗാൽവനൈസേഷൻ: സിങ്ക് പൂശൽ", "body": "ഇരുമ്പോ സ്റ്റീലോ തുരുമ്പെടുക്കാതിരിക്കാൻ സിങ്ക് പൂശുന്ന പ്രക്രിയയാണ് ഗാൽവനൈസേഷൻ. ഇരുമ്പിനേക്കാൾ ക്രിയാശീലം കൂടിയ സിങ്ക് ആദ്യം നശിച്ച് ഇരുമ്പിനെ സംരക്ഷിക്കുന്നു. ലൂയിജി ഗാൽവനിയുടെ പേരിലാണ് പ്രക്രിയ.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Galvanization"},
  {"topic": "രസതന്ത്രം", "title": "അപ്പക്കാരം: NaHCO₃", "body": "ബേക്കിങ് സോഡ (അപ്പക്കാരം) സോഡിയം ബൈകാർബണേറ്റ് ആണ്; രാസസൂത്രം NaHCO₃. ചൂടാക്കുമ്പോഴോ ആസിഡുമായി ചേരുമ്പോഴോ കാർബൺ ഡൈഓക്സൈഡ് പുറത്തുവിട്ട് മാവ് പൊങ്ങാൻ സഹായിക്കുന്നു. അസിഡിറ്റിക്ക് ആന്റാസിഡായും ഉപയോഗിക്കുന്നു.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Sodium_bicarbonate"},
  {"topic": "രസതന്ത്രം", "title": "അലക്കുകാരം: Na₂CO₃·10H₂O", "body": "വാഷിങ് സോഡ (അലക്കുകാരം) സോഡിയം കാർബണേറ്റ് ഡെക്കാഹൈഡ്രേറ്റ് ആണ്; രാസസൂത്രം Na₂CO₃·10H₂O. ജലത്തിന്റെ കാഠിന്യം നീക്കാനും ഗ്ലാസ് നിർമ്മാണത്തിനും ഉപയോഗിക്കുന്നു. സോൾവേ പ്രക്രിയയിലൂടെ നിർമ്മിക്കുന്നു.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Sodium_carbonate"},
  {"topic": "രസതന്ത്രം", "title": "പ്ലാസ്റ്റർ ഓഫ് പാരിസ്: ജിപ്സത്തിൽനിന്ന്", "body": "ജിപ്സം ചൂടാക്കി നിർമ്മിക്കുന്ന കാൽസ്യം സൾഫേറ്റ് ഹെമിഹൈഡ്രേറ്റ് (CaSO₄·½H₂O) ആണ് പ്ലാസ്റ്റർ ഓഫ് പാരിസ്. വെള്ളം ചേർത്താൽ കട്ടിയാകുന്നതിനാൽ എല്ലുപൊട്ടലിന് പ്ലാസ്റ്ററിടാനും പ്രതിമ നിർമ്മാണത്തിനും ഉപയോഗിക്കുന്നു.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Plaster"},
  {"topic": "രസതന്ത്രം", "title": "ബ്ലീച്ചിങ് പൗഡർ: ക്ലോറിനും ചുണ്ണാമ്പും", "body": "നനഞ്ഞ കാൽസ്യം ഹൈഡ്രോക്സൈഡിലൂടെ (ചുണ്ണാമ്പ്) ക്ലോറിൻ വാതകം കടത്തിവിട്ടാണ് ബ്ലീച്ചിങ് പൗഡർ നിർമ്മിക്കുന്നത്; പ്രധാന ഘടകം കാൽസ്യം ഹൈപ്പോക്ലോറൈറ്റ്. കുടിവെള്ളവും നീന്തൽക്കുളവും അണുവിമുക്തമാക്കാൻ ഉപയോഗിക്കുന്നു.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Calcium_hypochlorite"},
  {"topic": "രസതന്ത്രം", "title": "ക്വിക്ക്‌ലൈം (നീറ്റുകക്ക): CaO", "body": "കാൽസ്യം ഓക്സൈഡ് (CaO) ആണ് ക്വിക്ക്‌ലൈം അഥവാ നീറ്റുകക്ക. ചുണ്ണാമ്പുകല്ല് (CaCO₃) ചൂടാക്കി കാർബൺ ഡൈഓക്സൈഡ് നീക്കിയാണ് നിർമ്മാണം. വെള്ളം ചേർക്കുമ്പോൾ വലിയ താപം പുറത്തുവിട്ട് കാൽസ്യം ഹൈഡ്രോക്സൈഡ് (Ca(OH)₂) ആകുന്നു.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Calcium_oxide"},
  {"topic": "രസതന്ത്രം", "title": "ഡ്രൈ ഐസ്: ഖര കാർബൺ ഡൈഓക്സൈഡ്", "body": "ഖരാവസ്ഥയിലുള്ള കാർബൺ ഡൈഓക്സൈഡാണ് ഡ്രൈ ഐസ്. സാധാരണ അന്തരീക്ഷമർദ്ദത്തിൽ −78.5°C-ൽ ഉരുകാതെ നേരിട്ട് വാതകമാകുന്നു (ഉത്പതനം). അതിനാൽ ദ്രാവകം ബാക്കിവയ്ക്കാത്ത ശീതീകാരിയായി ഉപയോഗിക്കുന്നു.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Dry_ice"}],
 [{"topic": "കല, സാഹിത്യം, കായികം", "title": "ഓട്ടൻതുള്ളൽ: കുഞ്ചൻ നമ്പ്യാർ", "body": "തുള്ളൽ കലാരൂപത്തിന്റെ ഉപജ്ഞാതാവ് കുഞ്ചൻ നമ്പ്യാർ (18-ാം നൂറ്റാണ്ട്). ഓട്ടൻ, ശീതങ്കൻ, പറയൻ എന്നിങ്ങനെ മൂന്ന് തരം തുള്ളലുണ്ട്. പാലക്കാട് കിള്ളിക്കുറിശ്ശിമംഗലത്ത് ജനിച്ച അദ്ദേഹം മാർത്താണ്ഡവർമ്മയുടെ സദസ്സിലെത്തി.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Kunchan_Nambiar"},
  {"topic": "കല, സാഹിത്യം, കായികം", "title": "കഥകളിയുടെ മുൻരൂപം: രാമനാട്ടം", "body": "കഥകളിയുടെ മുൻഗാമിയായ 'രാമനാട്ടം' രാമായണകഥ അവതരിപ്പിക്കാൻ കൊട്ടാരക്കര രാജാവ് (കൊട്ടാരക്കര തമ്പുരാൻ) രൂപപ്പെടുത്തി. കോഴിക്കോട് മാനവേദൻ രാജാവിന്റെ 'കൃഷ്ണനാട്ട'വും കഥകളിയുടെ വേരുകളിലൊന്നാണ്.", "source": "Kerala Tourism", "url": "https://www.keralatourism.org/artforms/kathakali-kerala-theatre/15/"},
  {"topic": "കല, സാഹിത്യം, കായികം", "title": "കേളികൊട്ട്: കഥകളിയുടെ അറിയിപ്പ്", "body": "കഥകളി അവതരണം ഉണ്ടെന്ന് സന്ധ്യയ്ക്ക് അറിയിക്കുന്ന പ്രത്യേക താളവാദ്യ ഭാഗമാണ് 'കേളികൊട്ട്'. കഥകളിയിലെ ആദ്യ ചടങ്ങായി പി.എസ്.സി. പരീക്ഷകളിൽ ചോദിക്കാറുണ്ട്; തുടർന്ന് തോടയം, പുറപ്പാട് എന്നിവ.", "source": "Kerala Tourism", "url": "https://www.keralatourism.org/artforms/kathakali-kerala-theatre/15/"},
  {"topic": "കല, സാഹിത്യം, കായികം", "title": "ശാസ്ത്രീയ നൃത്തങ്ങളും സംസ്ഥാനങ്ങളും", "body": "സംഗീത നാടക അക്കാദമി 8 ശാസ്ത്രീയ നൃത്തങ്ങളെ അംഗീകരിക്കുന്നു: ഭരതനാട്യം (തമിഴ്നാട്), കഥക് (ഉത്തർപ്രദേശ്), കഥകളി, മോഹിനിയാട്ടം (കേരളം), കുച്ചിപ്പുടി (ആന്ധ്ര), മണിപ്പുരി (മണിപ്പൂർ), ഒഡീസി (ഒഡീഷ), സത്രിയ (അസം).", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Indian_classical_dance"},
  {"topic": "കല, സാഹിത്യം, കായികം", "title": "ബാലൻ: ആദ്യ മലയാള ശബ്ദചിത്രം", "body": "1938 ജനുവരി 19-ന് പുറത്തിറങ്ങിയ 'ബാലൻ' ആണ് മലയാളത്തിലെ ആദ്യ ശബ്ദസിനിമ. എസ്. നൊട്ടാണി സംവിധാനം; നിർമ്മാണം മോഡേൺ തിയേറ്റേഴ്സിന്റെ ടി.ആർ. സുന്ദരം. തിരക്കഥയും സംഭാഷണവും മുതുകുളം രാഘവൻപിള്ള.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Balan_(film)"},
  {"topic": "കല, സാഹിത്യം, കായികം", "title": "ചെമ്മീൻ: ആദ്യ ദക്ഷിണേന്ത്യൻ സ്വർണ്ണമെഡൽ", "body": "തകഴിയുടെ നോവലിനെ ആസ്പദമാക്കി രാമു കാര്യാട്ട് സംവിധാനം ചെയ്ത 'ചെമ്മീൻ' 1965-ലെ മികച്ച ചിത്രത്തിനുള്ള രാഷ്ട്രപതിയുടെ സ്വർണ്ണമെഡൽ നേടിയ ആദ്യ ദക്ഷിണേന്ത്യൻ ചിത്രമാണ്. കറുത്തമ്മ, പരീക്കുട്ടി പ്രധാന കഥാപാത്രങ്ങൾ.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Chemmeen"},
  {"topic": "കല, സാഹിത്യം, കായികം", "title": "ദാദാസാഹേബ് ഫാൽക്കെ: ആദ്യം ദേവികാ റാണി", "body": "1969-ൽ ഏർപ്പെടുത്തിയ, ഇന്ത്യൻ സിനിമയിലെ പരമോന്നത ബഹുമതിയായ ദാദാസാഹേബ് ഫാൽക്കെ പുരസ്കാരം ആദ്യം ലഭിച്ചത് നടി ദേവികാ റാണിക്കാണ്. ഫാൽക്കെ നേടിയ ആദ്യ മലയാളി അടൂർ ഗോപാലകൃഷ്ണൻ (2004).", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Dadasaheb_Phalke_Award"},
  {"topic": "കല, സാഹിത്യം, കായികം", "title": "സച്ചിൻ: ഭാരതരത്നം നേടിയ ആദ്യ കായികതാരം", "body": "ഭാരതരത്നം നേടിയ ആദ്യ കായികതാരം ക്രിക്കറ്റ് താരം സച്ചിൻ ടെണ്ടുൽക്കറാണ് (2014-ൽ സമ്മാനിച്ചു; പ്രഖ്യാപനം 2013 നവംബർ). 40-ാം വയസ്സിൽ ലഭിച്ച അദ്ദേഹം ഏറ്റവും പ്രായം കുറഞ്ഞ ഭാരതരത്ന ജേതാവുമാണ്.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Bharat_Ratna"},
  {"topic": "കല, സാഹിത്യം, കായികം", "title": "പി.ടി. ഉഷ: ഐ.ഒ.എ.യുടെ ആദ്യ വനിതാ അധ്യക്ഷ", "body": "2022 ഡിസംബർ 10-ന് എതിരില്ലാതെ തിരഞ്ഞെടുക്കപ്പെട്ട പി.ടി. ഉഷ ഇന്ത്യൻ ഒളിമ്പിക് അസോസിയേഷന്റെ ആദ്യ വനിതാ പ്രസിഡന്റായി. 2022 ജൂലൈയിൽ രാജ്യസഭയിലേക്ക് നാമനിർദ്ദേശം ചെയ്യപ്പെട്ടു.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/P._T._Usha"},
  {"topic": "കല, സാഹിത്യം, കായികം", "title": "പി.ആർ. ശ്രീജേഷ്: രണ്ട് ഒളിമ്പിക് വെങ്കലം", "body": "കൊച്ചി കിഴക്കമ്പലം സ്വദേശിയായ ഹോക്കി ഗോൾകീപ്പർ പി.ആർ. ശ്രീജേഷ് ടോക്യോ 2020, പാരീസ് 2024 ഒളിമ്പിക്സുകളിൽ ഇന്ത്യൻ ടീമിനൊപ്പം വെങ്കലം നേടി. 2021-ൽ ഖേൽരത്ന ലഭിച്ചു; പാരീസിനു ശേഷം വിരമിച്ചു.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/P._R._Sreejesh"}],
 [{"topic": "ജീവശാസ്ത്രവും ആരോഗ്യവും", "title": "ജീവകം E (ടോക്കോഫെറോൾ): പ്രത്യുൽപാദന ജീവകം", "body": "1922-ൽ എലികളിലെ പ്രത്യുൽപാദനശേഷിക്ക് അനിവാര്യമായ ഘടകമായാണ് ജീവകം E കണ്ടെത്തിയത്; അതിനാൽ 'ആന്റി-സ്റ്റെറിലിറ്റി ജീവകം' എന്നറിയപ്പെട്ടു. ഇതിന്റെ രാസനാമം ടോക്കോഫെറോൾ; കോശസ്തരങ്ങളെ സംരക്ഷിക്കുന്ന ആന്റിഓക്സിഡന്റ് കൂടിയാണ്.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Vitamin_E"},
  {"topic": "ജീവശാസ്ത്രവും ആരോഗ്യവും", "title": "ഹീമോഫീലിയ: 'രാജകീയ രോഗം'", "body": "രക്തം കട്ടപിടിക്കാനുള്ള ശേഷി കുറയുന്ന പാരമ്പര്യരോഗമാണ് ഹീമോഫീലിയ. X ക്രോമസോമുമായി ബന്ധപ്പെട്ടതിനാൽ പ്രധാനമായും പുരുഷന്മാരെ ബാധിക്കുന്നു. വിക്ടോറിയ രാജ്ഞിയിൽനിന്ന് യൂറോപ്യൻ രാജകുടുംബങ്ങളിലേക്ക് പകർന്നതിനാൽ 'രാജകീയ രോഗം' എന്നറിയപ്പെടുന്നു.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Haemophilia"},
  {"topic": "ജീവശാസ്ത്രവും ആരോഗ്യവും", "title": "സിക്കിൾ സെൽ അനീമിയ: അരിവാൾ രൂപം", "body": "ചുവന്ന രക്താണുക്കൾ അരിവാൾ (ചന്ദ്രക്കല) ആകൃതിയിലാകുന്ന ജനിതക രോഗമാണ് സിക്കിൾ സെൽ രോഗം. അസാധാരണ ഹീമോഗ്ലോബിനായ HbS ആണ് കാരണം. ഒരു വികലജീൻ മാത്രമുള്ള വാഹകർക്ക് മലമ്പനിക്കെതിരെ ഒരളവുവരെ സംരക്ഷണം ലഭിക്കുന്നു.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Sickle_cell_disease"},
  {"topic": "ജീവശാസ്ത്രവും ആരോഗ്യവും", "title": "മനുഷ്യനിൽ 46 ക്രോമസോമുകൾ; ടർണർ സിൻഡ്രോം", "body": "മിക്ക മനുഷ്യർക്കും 46 ക്രോമസോമുകളാണുള്ളത്. സ്ത്രീകളിൽ രണ്ട് X ക്രോമസോമുകൾക്ക് പകരം ഒന്ന് മാത്രമുള്ള (45,X) അവസ്ഥയാണ് ടർണർ സിൻഡ്രോം; മൊസൈക് അല്ലാത്ത ടർണർ സിൻഡ്രോം സ്ത്രീകളിൽ മാത്രം കാണുന്നു.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Turner_syndrome"},
  {"topic": "ജീവശാസ്ത്രവും ആരോഗ്യവും", "title": "യുറാസിൽ RNA-യിൽ; DNA-യിൽ തൈമിൻ", "body": "അഡിനിൻ, ഗ്വാനിൻ, സൈറ്റോസിൻ, യുറാസിൽ എന്നിവയാണ് RNA-യിലെ നൈട്രജൻ ബേസുകൾ. DNA-യിൽ യുറാസിലിന് പകരം തൈമിൻ ആണുള്ളത്; അതിനാൽ DNA-യിൽ സാധാരണ കാണാത്ത ബേസാണ് യുറാസിൽ. യുറാസിൽ അഡിനിനുമായി ജോടി ചേരുന്നു.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Uracil"},
  {"topic": "ജീവശാസ്ത്രവും ആരോഗ്യവും", "title": "ഗ്രിഗർ മെൻഡൽ: പാരമ്പര്യശാസ്ത്രത്തിന്റെ പിതാവ്", "body": "ഓസ്ട്രിയൻ സന്യാസിയായ ഗ്രിഗർ മെൻഡൽ 1856–1863 കാലത്ത് പയർച്ചെടികളിൽ നടത്തിയ പരീക്ഷണങ്ങളിലൂടെ പാരമ്പര്യനിയമങ്ങൾ (വേർതിരിയൽ നിയമം, സ്വതന്ത്ര അപവ്യൂഹന നിയമം) ആവിഷ്കരിച്ചു. 1900-ൽ ഹ്യൂഗോ ഡി വ്രീസ് ഉൾപ്പെടെയുള്ളവർ ഇത് പുനഃകണ്ടെത്തി.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Gregor_Mendel"},
  {"topic": "ജീവശാസ്ത്രവും ആരോഗ്യവും", "title": "ലൈസോസോം: കോശത്തിലെ 'ആത്മഹത്യാസഞ്ചി'", "body": "ദഹനരസങ്ങളായ ഹൈഡ്രോലിറ്റിക് എൻസൈമുകൾ നിറഞ്ഞ കോശാംഗമാണ് ലൈസോസോം. ഇവ പുറത്തുവന്നാൽ കോശം തന്നെ നശിക്കാമെന്നതിനാൽ കണ്ടെത്തിയ ക്രിസ്റ്റ്യൻ ഡി ഡ്യൂവ് 1959-ൽ ഇവയെ 'സൂയിസൈഡ് ബാഗുകൾ' എന്ന് വിളിച്ചു. സസ്യകോശങ്ങളിൽ ഇവ അപൂർവമാണ്.", "source": "PMC (NIH)", "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC2755904/"},
  {"topic": "ജീവശാസ്ത്രവും ആരോഗ്യവും", "title": "മലമ്പനി: പ്ലാസ്മോഡിയവും അനോഫിലിസും", "body": "മലമ്പനിക്ക് കാരണം പ്ലാസ്മോഡിയം എന്ന പരാദജീവിയാണ്; മനുഷ്യരിൽ രോഗമുണ്ടാക്കുന്ന 5 സ്പീഷീസുകളുണ്ട്. രോഗാണുവുള്ള പെൺ അനോഫിലിസ് കൊതുകുകളുടെ കടിയിലൂടെയാണ് പ്രധാനമായും പകരുന്നത്; ഒരാളിൽനിന്ന് മറ്റൊരാളിലേക്ക് നേരിട്ട് പകരില്ല.", "source": "WHO", "url": "https://www.who.int/news-room/fact-sheets/detail/malaria"},
  {"topic": "ജീവശാസ്ത്രവും ആരോഗ്യവും", "title": "BCG: ക്ഷയരോഗ പ്രതിരോധ വാക്സിൻ", "body": "ക്ഷയരോഗത്തിനെതിരായ വാക്സിനാണ് BCG (ബാസിലസ് കാൽമെറ്റ്–ഗ്വെറിൻ). ഫ്രാൻസിലെ ആൽബർട്ട് കാൽമെറ്റും കാമിൽ ഗ്വെറിനും വികസിപ്പിച്ച ഇത് 1921-ലാണ് മനുഷ്യരിൽ ആദ്യമായി ഉപയോഗിച്ചത്. കുട്ടികളിലെ ഗുരുതരമായ ക്ഷയരോഗരൂപങ്ങൾക്കെതിരെ ഏറ്റവും ഫലപ്രദം.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/BCG_vaccine"},
  {"topic": "ജീവശാസ്ത്രവും ആരോഗ്യവും", "title": "എയ്ഡ്സ്: HIV വൈറസ്", "body": "ശരീരത്തിന്റെ രോഗപ്രതിരോധ സംവിധാനത്തെ ആക്രമിക്കുന്ന ഹ്യൂമൻ ഇമ്മ്യൂണോഡെഫിഷ്യൻസി വൈറസ് (HIV) ആണ് എയ്ഡ്സിന് കാരണം. HIV അണുബാധയുടെ ഏറ്റവും ഗുരുതരമായ ഘട്ടമാണ് എയ്ഡ്സ് (അക്വയേഡ് ഇമ്മ്യൂണോഡെഫിഷ്യൻസി സിൻഡ്രോം).", "source": "WHO", "url": "https://www.who.int/news-room/fact-sheets/detail/hiv-aids"}],
 [{"topic": "ഇന്ത്യൻ ഭരണഘടന", "title": "രാഷ്ട്രപതി: കുറഞ്ഞ പ്രായം 35 (അനു. 58)", "body": "അനുച്ഛേദം 52 രാഷ്ട്രപതി പദവി സ്ഥാപിക്കുന്നു; യൂണിയന്റെ കാര്യനിർവഹണാധികാരം രാഷ്ട്രപതിയിൽ നിക്ഷിപ്തമാണ് (അനു. 53). യോഗ്യതകൾ പറയുന്ന അനുച്ഛേദം 58 പ്രകാരം കുറഞ്ഞത് 35 വയസ്സ് വേണം; കാലാവധി 5 വർഷം (അനു. 56).", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/President_of_India"},
  {"topic": "ഇന്ത്യൻ ഭരണഘടന", "title": "ഉപരാഷ്ട്രപതി: രാജ്യസഭയുടെ അധ്യക്ഷൻ", "body": "അനുച്ഛേദം 64 പ്രകാരം ഉപരാഷ്ട്രപതി രാജ്യസഭയുടെ എക്സ് ഒഫീഷ്യോ ചെയർമാനാണ്. ഉപരാഷ്ട്രപതി രാഷ്ട്രപതിയുടെ ചുമതല വഹിക്കുന്ന സമയത്ത് രാജ്യസഭാ അധ്യക്ഷനായി പ്രവർത്തിക്കുകയോ ചെയർമാന്റെ ശമ്പളം വാങ്ങുകയോ ചെയ്യില്ല.", "source": "constitutionofindia.net", "url": "https://www.constitutionofindia.net/articles/article-64-the-vice-president-to-be-ex-officio-chairman-of-the-council-of-states/"},
  {"topic": "ഇന്ത്യൻ ഭരണഘടന", "title": "രാജ്യസഭ: പരമാവധി 250, നാമനിർദ്ദേശം 12", "body": "അനുച്ഛേദം 80 പ്രകാരം രാജ്യസഭയുടെ പരമാവധി അംഗസംഖ്യ 250; കല, സാഹിത്യം, ശാസ്ത്രം, സാമൂഹികസേവനം എന്നിവയിൽ മികവുള്ള 12 പേരെ രാഷ്ട്രപതി നാമനിർദ്ദേശം ചെയ്യുന്നു. അംഗത്തിന്റെ കാലാവധി 6 വർഷം; രണ്ടുവർഷം കൂടുമ്പോൾ മൂന്നിലൊന്ന് പേർ വിരമിക്കും.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Rajya_Sabha"},
  {"topic": "ഇന്ത്യൻ ഭരണഘടന", "title": "സുപ്രീം കോടതി: അനുച്ഛേദം 124", "body": "അനുച്ഛേദം 124 പ്രകാരം സ്ഥാപിതമായ സുപ്രീം കോടതി 1950 ജനുവരി 28-ന് ഉദ്ഘാടനം ചെയ്തു. തുടക്കത്തിൽ ചീഫ് ജസ്റ്റിസും 7 ജഡ്ജിമാരും; ആദ്യ ചീഫ് ജസ്റ്റിസ് എച്ച്.ജെ. കനിയ. ജഡ്ജിമാരുടെ വിരമിക്കൽ പ്രായം 65.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Supreme_Court_of_India"},
  {"topic": "ഇന്ത്യൻ ഭരണഘടന", "title": "തിരഞ്ഞെടുപ്പ് കമ്മീഷൻ: അനുച്ഛേദം 324", "body": "അനുച്ഛേദം 324 പ്രകാരമുള്ള ഇന്ത്യൻ തിരഞ്ഞെടുപ്പ് കമ്മീഷൻ 1950 ജനുവരി 25-ന് നിലവിൽ വന്നു; ഈ ദിനം ദേശീയ സമ്മതിദായക ദിനമാണ്. മുഖ്യ തിരഞ്ഞെടുപ്പ് കമ്മീഷണറും രണ്ട് കമ്മീഷണർമാരും; ആദ്യ മുഖ്യ കമ്മീഷണർ സുകുമാർ സെൻ.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Election_Commission_of_India"},
  {"topic": "ഇന്ത്യൻ ഭരണഘടന", "title": "ഭരണഘടനാ ഭേദഗതി: അനുച്ഛേദം 368", "body": "ഭാഗം XX-ലെ അനുച്ഛേദം 368 ആണ് ഭരണഘടന ഭേദഗതി ചെയ്യാൻ പാർലമെന്റിന് അധികാരം നൽകുന്നത്. ഓരോ സഭയിലും ആകെ അംഗങ്ങളുടെ ഭൂരിപക്ഷവും ഹാജരായി വോട്ട് ചെയ്യുന്നവരുടെ മൂന്നിൽ രണ്ടും വേണം; ചില വ്യവസ്ഥകൾക്ക് പകുതി സംസ്ഥാനങ്ങളുടെ അംഗീകാരവും വേണം.", "source": "constitutionofindia.net", "url": "https://www.constitutionofindia.net/articles/article-368-power-of-parliament-to-amend-the-constitution-and-procedure-therefor/"},
  {"topic": "ഇന്ത്യൻ ഭരണഘടന", "title": "രാഷ്ട്രപതി ഭരണം: അനുച്ഛേദം 356", "body": "സംസ്ഥാനത്ത് ഭരണഘടനാ സംവിധാനം തകരുമ്പോൾ അനുച്ഛേദം 356 പ്രകാരം രാഷ്ട്രപതി ഭരണം ഏർപ്പെടുത്താം. ആദ്യം ഏർപ്പെടുത്തിയത് പഞ്ചാബിൽ (1951 ജൂൺ 20). 1959 ജൂലൈ 31-ന് കേരളത്തിലെ ഇ.എം.എസ്. സർക്കാരിനെ പിരിച്ചുവിട്ടതും ഇതുപ്രകാരമാണ്.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/President%27s_rule"},
  {"topic": "ഇന്ത്യൻ ഭരണഘടന", "title": "വോട്ടിങ് പ്രായം 18: 61-ാം ഭേദഗതി", "body": "61-ാം ഭരണഘടനാ ഭേദഗതി വോട്ടിങ് പ്രായം 21-ൽനിന്ന് 18 ആയി കുറച്ചു. ഈ ഭേദഗതി 1989 മാർച്ച് 28-ന് പ്രാബല്യത്തിൽ വന്നു; ഇതിലൂടെ 18 വയസ്സ് തികഞ്ഞ എല്ലാ പൗരന്മാർക്കും വോട്ടവകാശം ലഭിച്ചു.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/List_of_amendments_of_the_Constitution_of_India"},
  {"topic": "ഇന്ത്യൻ ഭരണഘടന", "title": "42-ാം ഭേദഗതി: ‘മിനി ഭരണഘടന’", "body": "അടിയന്തരാവസ്ഥക്കാലത്ത് ഇന്ദിരാഗാന്ധി സർക്കാർ കൊണ്ടുവന്ന 1976-ലെ 42-ാം ഭേദഗതിയെ ‘മിനി ഭരണഘടന’ എന്നു വിളിക്കുന്നു. ലോക്‌സഭയുടെയും നിയമസഭകളുടെയും കാലാവധി 5-ൽനിന്ന് 6 വർഷമാക്കി; പിന്നീട് 43, 44 ഭേദഗതികൾ ഇതിൽ പലതും തിരുത്തി.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Forty-second_Amendment_of_the_Constitution_of_India"},
  {"topic": "ഇന്ത്യൻ ഭരണഘടന", "title": "101-ാം ഭേദഗതി: GST", "body": "ചരക്ക് സേവന നികുതി (GST) കൊണ്ടുവന്നത് 2016-ലെ 101-ാം ഭേദഗതിയാണ്; GST 2017 ജൂലൈ 1-ന് നിലവിൽ വന്നു. ബിൽ ആദ്യം അംഗീകരിച്ച സംസ്ഥാനം അസം. അനുച്ഛേദം 279A പ്രകാരമുള്ള GST കൗൺസിലിന്റെ അധ്യക്ഷൻ കേന്ദ്ര ധനമന്ത്രി.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/One_Hundred_and_First_Amendment_of_the_Constitution_of_India"}],
 [{"topic": "ആനുകാലികം", "title": "സ്പേഡെക്സ്: ബഹിരാകാശ ഡോക്കിങ്", "body": "2024 ഡിസംബർ 30-ന് PSLV-C60 വഴി വിക്ഷേപിച്ച SDX01 (ചേസർ), SDX02 (ടാർഗറ്റ്) ഉപഗ്രഹങ്ങളെ 2025 ജനുവരി 16-ന് ബഹിരാകാശത്ത് കൂട്ടിച്ചേർത്തു. തദ്ദേശീയ സാങ്കേതികവിദ്യയിൽ ഡോക്കിങ് നേടുന്ന നാലാമത്തെ രാജ്യമായി ഇന്ത്യ.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/SpaDeX"},
  {"topic": "ആനുകാലികം", "title": "ശുഭാംശു ശുക്ല: ആക്സിയം-4 ദൗത്യം", "body": "ആക്സിയം-4 ദൗത്യത്തിന്റെ പൈലറ്റായി 2025 ജൂൺ 25-ന് യാത്ര തിരിച്ച ശുഭാംശു ശുക്ല ജൂൺ 26-ന് അന്താരാഷ്ട്ര ബഹിരാകാശ നിലയത്തിലെത്തി. ISS-ലെത്തുന്ന ആദ്യ ഇന്ത്യക്കാരൻ; രാകേഷ് ശർമയ്ക്കു (1984) ശേഷം ബഹിരാകാശത്തെത്തിയ ഇന്ത്യക്കാരൻ.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Axiom_Mission_4"},
  {"topic": "ആനുകാലികം", "title": "ആദിത്യ-L1: ഇന്ത്യയുടെ ആദ്യ സൗരദൗത്യം", "body": "2023 സെപ്റ്റംബർ 2-ന് PSLV-C57 വഴി വിക്ഷേപിച്ച ആദിത്യ-L1, 2024 ജനുവരി 6-ന് ഭൂമിയിൽനിന്ന് ഏകദേശം 15 ലക്ഷം കി.മീ. അകലെയുള്ള സൂര്യ–ഭൂമി ലഗ്രാഞ്ച് പോയിന്റ് 1-ലെ ഹാലോ ഭ്രമണപഥത്തിലെത്തി.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Aditya-L1"},
  {"topic": "ആനുകാലികം", "title": "GSLV-F15: ശ്രീഹരിക്കോട്ടയിലെ 100-ാം വിക്ഷേപണം", "body": "2025 ജനുവരി 29-ന് ശ്രീഹരിക്കോട്ടയിൽനിന്ന് GSLV-F15 റോക്കറ്റ് NVS-02 നാവിഗേഷൻ ഉപഗ്രഹവുമായി കുതിച്ചു; 1979-ലെ SLV-3 മുതൽ ശ്രീഹരിക്കോട്ടയിൽനിന്നുള്ള 100-ാമത്തെ വിക്ഷേപണം. പുതിയ ISRO ചെയർമാൻ വി. നാരായണന്റെ ആദ്യ ദൗത്യവും.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/GSLV-F15"},
  {"topic": "ആനുകാലികം", "title": "സൂര്യ കാന്ത്: 53-ാം ചീഫ് ജസ്റ്റിസ്", "body": "ജസ്റ്റിസ് സൂര്യ കാന്ത് 2025 നവംബർ 24-ന് ഇന്ത്യയുടെ 53-ാമത് ചീഫ് ജസ്റ്റിസായി ചുമതലയേറ്റു. മുൻഗാമികൾ: ബി.ആർ. ഗവായ് (52-ാമത്, 2025 മേയ് 14 – നവംബർ 23), സഞ്ജീവ് ഖന്ന (51-ാമത്, 2024 നവംബർ 11 മുതൽ).", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Chief_Justice_of_India"},
  {"topic": "ആനുകാലികം", "title": "ഗ്യാനേഷ് കുമാർ: 26-ാം മുഖ്യ തിര. കമ്മീഷണർ", "body": "ഗ്യാനേഷ് കുമാർ 2025 ഫെബ്രുവരി 19-ന് ഇന്ത്യയുടെ 26-ാമത് മുഖ്യ തിരഞ്ഞെടുപ്പ് കമ്മീഷണറായി ചുമതലയേറ്റു. തിരഞ്ഞെടുപ്പ് കമ്മീഷനെക്കുറിച്ച് പ്രതിപാദിക്കുന്നത് ഭരണഘടനയുടെ അനുച്ഛേദം 324.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Chief_Election_Commissioner_of_India"},
  {"topic": "ആനുകാലികം", "title": "സഞ്ജയ് മൽഹോത്ര: 26-ാം RBI ഗവർണർ", "body": "സഞ്ജയ് മൽഹോത്ര 2024 ഡിസംബർ 11-ന് റിസർവ് ബാങ്ക് ഓഫ് ഇന്ത്യയുടെ 26-ാമത് ഗവർണറായി ചുമതലയേറ്റു. 2018 ഡിസംബർ മുതൽ ഗവർണറായിരുന്ന ശക്തികാന്ത ദാസിന്റെ (25-ാമത്) പിൻഗാമി.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Governor_of_the_Reserve_Bank_of_India"},
  {"topic": "ആനുകാലികം", "title": "സി.പി. രാധാകൃഷ്ണൻ: 15-ാം ഉപരാഷ്ട്രപതി", "body": "ജഗ്ദീപ് ധൻകർ 2025 ജൂലൈ 21-ന് രാജിവെച്ചതിനെത്തുടർന്നുള്ള തിരഞ്ഞെടുപ്പിൽ ജയിച്ച സി.പി. രാധാകൃഷ്ണൻ 2025 സെപ്റ്റംബർ 12-ന് ഇന്ത്യയുടെ 15-ാമത് ഉപരാഷ്ട്രപതിയായി ചുമതലയേറ്റു. ഉപരാഷ്ട്രപതിയാണ് രാജ്യസഭാ ചെയർമാൻ.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Vice_President_of_India"},
  {"topic": "ആനുകാലികം", "title": "വി.ഡി. സതീശൻ കേരള മുഖ്യമന്ത്രി (2026)", "body": "2026 നിയമസഭാ തിരഞ്ഞെടുപ്പിൽ 140-ൽ 102 സീറ്റ് നേടി UDF അധികാരത്തിലെത്തി. കോൺഗ്രസ് നേതാവ് വി.ഡി. സതീശൻ (പറവൂർ) 2026 മേയ് 18-ന് തിരുവനന്തപുരം സെൻട്രൽ സ്റ്റേഡിയത്തിൽ മുഖ്യമന്ത്രിയായി സത്യപ്രതിജ്ഞ ചെയ്തു.", "source": "Indian National Congress", "url": "https://www.outlookindia.com/elections/vd-satheesan-sworn-in-as-kerala-chief-minister-as-udf-returns-to-power"},
  {"topic": "ആനുകാലികം", "title": "സമ്പൂർണ ഡിജിറ്റൽ സാക്ഷരത: കേരളം ആദ്യം", "body": "2025 ഓഗസ്റ്റിൽ 'ഡിജി കേരളം' പദ്ധതിയിലൂടെ കേരളം രാജ്യത്തെ ആദ്യ സമ്പൂർണ ഡിജിറ്റൽ സാക്ഷര സംസ്ഥാനമായി പ്രഖ്യാപിക്കപ്പെട്ടു. 21.87 ലക്ഷം പേർ (99.98%) പരിശീലനം പൂർത്തിയാക്കി; തുടക്കം തിരുവനന്തപുരത്തെ പുല്ലമ്പാറ പഞ്ചായത്തിൽ.", "source": "Outlook India", "url": "https://www.outlookindia.com/national/scrolls-of-change-how-kerala-became-indias-first-digitally-literate-state"}],
 [{"topic": "സാമ്പത്തികശാസ്ത്രം", "title": "തൊഴിലുറപ്പ് നിയമം: 2005", "body": "ദേശീയ ഗ്രാമീണ തൊഴിലുറപ്പ് നിയമത്തിന് 2005 സെപ്റ്റംബർ 5-ന് രാഷ്ട്രപതി അംഗീകാരം നൽകി; 2006 ഫെബ്രുവരി 2-ന് പ്രാബല്യത്തിൽ. ഗ്രാമീണ കുടുംബത്തിന് വർഷം കുറഞ്ഞത് 100 ദിവസം തൊഴിൽ ഉറപ്പ്. 2025-ൽ VB–G RAM G നിയമം ഇതിനെ റദ്ദാക്കി പകരം വന്നു.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/National_Rural_Employment_Guarantee_Act,_2005"},
  {"topic": "സാമ്പത്തികശാസ്ത്രം", "title": "1991-ലെ സാമ്പത്തിക പരിഷ്കാരങ്ങൾ", "body": "വിദേശനാണ്യ ശേഖരം മൂന്നാഴ്ചത്തെ ഇറക്കുമതിക്ക് മാത്രം തികയുന്ന പ്രതിസന്ധിയിൽ, 1991-ൽ പി.വി. നരസിംഹറാവു സർക്കാർ ഉദാരവൽക്കരണം-സ്വകാര്യവൽക്കരണം-ആഗോളവൽക്കരണം (LPG) പരിഷ്കാരങ്ങൾ തുടങ്ങി. 1991 ജൂലൈ 24-ലെ ബജറ്റ് അവതരിപ്പിച്ചത് ധനമന്ത്രി മൻമോഹൻ സിങ്.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Economic_liberalisation_in_India"},
  {"topic": "സാമ്പത്തികശാസ്ത്രം", "title": "പ്ലാൻ ഹോളിഡേ: 1966–69", "body": "മൂന്നാം പദ്ധതിയുടെ (1961–66) പരാജയത്തിനുശേഷം 1966–67, 1967–68, 1968–69 വർഷങ്ങളിൽ മൂന്ന് വാർഷിക പദ്ധതികൾ മാത്രമാണ് നടപ്പാക്കിയത്; ഇതാണ് 'പ്ലാൻ ഹോളിഡേ'. 1962-ലെ ചൈന യുദ്ധവും 1965-ലെ പാക് യുദ്ധവും വരൾച്ചയും തിരിച്ചടിയായി.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Five-Year_Plans_of_India"},
  {"topic": "സാമ്പത്തികശാസ്ത്രം", "title": "CRR: കരുതൽ ധന അനുപാതം", "body": "ഷെഡ്യൂൾഡ് വാണിജ്യബാങ്കുകൾ തങ്ങളുടെ മൊത്തം അറ്റ ഡിമാൻഡ്-ടൈം ബാധ്യതകളുടെ (NDTL) ഒരു നിശ്ചിത ഭാഗം റിസർവ് ബാങ്കിൽ പണമായി സൂക്ഷിക്കണം; ഇതാണ് Cash Reserve Ratio (CRR). RBI Act 1934 പ്രകാരമാണ് ഈ ബാധ്യത.", "source": "Arthapedia (IES)", "url": "https://ies.gov.in/arthapedia/concept/cash-reserve-ratio-crr"},
  {"topic": "സാമ്പത്തികശാസ്ത്രം", "title": "SLR: നിയമപരമായ ദ്രവ്യത അനുപാതം", "body": "ബാങ്കുകൾ വായ്പ നൽകുംമുമ്പ് ബാധ്യതകളുടെ ഒരു നിശ്ചിത ശതമാനം പണം, സ്വർണം, സർക്കാർ കടപ്പത്രങ്ങൾ തുടങ്ങിയ ദ്രവ ആസ്തികളായി സ്വന്തം കൈവശം സൂക്ഷിക്കണം; ഇതാണ് Statutory Liquidity Ratio (SLR). CRR റിസർവ് ബാങ്കിലാണ് സൂക്ഷിക്കുന്നത് എന്നതാണ് വ്യത്യാസം.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Statutory_liquidity_ratio"},
  {"topic": "സാമ്പത്തികശാസ്ത്രം", "title": "SIDBI: 1990, ആസ്ഥാനം ലഖ്നൗ", "body": "ചെറുകിട വ്യവസായങ്ങളുടെ വികസനത്തിനായി SIDBI (Small Industries Development Bank of India) 1990 ഏപ്രിൽ 2-ന് IDBI-യുടെ ഉപസ്ഥാപനമായി സ്ഥാപിച്ചു. ആസ്ഥാനം ഉത്തർപ്രദേശിലെ ലഖ്നൗ.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Small_Industries_Development_Bank_of_India"},
  {"topic": "സാമ്പത്തികശാസ്ത്രം", "title": "SEBI: 1988-ൽ രൂപീകരണം, 1992-ൽ നിയമപദവി", "body": "ഓഹരിവിപണി നിയന്ത്രിക്കുന്ന SEBI 1988 ഏപ്രിൽ 12-ന് ഒരു എക്സിക്യൂട്ടീവ് സ്ഥാപനമായി രൂപംകൊണ്ടു. 1992 ജനുവരി 30-ന് SEBI നിയമത്തിലൂടെ നിയമപരമായ അധികാരം ലഭിച്ചു. ആസ്ഥാനം മുംബൈ.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Securities_and_Exchange_Board_of_India"},
  {"topic": "സാമ്പത്തികശാസ്ത്രം", "title": "GNP, NNP: GDP-യിൽനിന്ന്", "body": "GNP = GDP + വിദേശത്തുനിന്നുള്ള അറ്റ ഘടക വരുമാനം (ലഭിച്ചതിൽനിന്ന് പുറത്തേക്ക് നൽകിയത് കുറച്ചത്). GNP-യിൽനിന്ന് തേയ്മാനം (depreciation) കുറച്ചാൽ NNP ലഭിക്കും. GNP-യെ ഇപ്പോൾ GNI എന്നും വിളിക്കുന്നു.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Gross_national_income"},
  {"topic": "സാമ്പത്തികശാസ്ത്രം", "title": "ടെണ്ടുൽക്കർ കമ്മിറ്റി ദാരിദ്ര്യരേഖ (2009)", "body": "2009-ലെ സുരേഷ് ടെണ്ടുൽക്കർ കമ്മിറ്റി ആളോഹരി ഉപഭോഗച്ചെലവ് അടിസ്ഥാനമാക്കി ദാരിദ്ര്യരേഖ നിർണയിച്ചു: ഗ്രാമങ്ങളിൽ പ്രതിദിനം ₹27 (₹816/മാസം), നഗരങ്ങളിൽ ₹33 (₹1,000/മാസം). 2011–12-ൽ ദരിദ്രർ 21.9%.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Poverty_in_India"},
  {"topic": "സാമ്പത്തികശാസ്ത്രം", "title": "ധവളവിപ്ലവം: ഓപ്പറേഷൻ ഫ്ലഡ്", "body": "ധവളവിപ്ലവം എന്നറിയപ്പെടുന്ന ഓപ്പറേഷൻ ഫ്ലഡ് 1970 ജനുവരി 13-ന് ദേശീയ ക്ഷീരവികസന ബോർഡിന്റെ (NDDB) നേതൃത്വത്തിൽ ആരംഭിച്ചു. ഇതിന്റെ ശില്പി NDDB ചെയർമാനായിരുന്ന ഡോ. വർഗീസ് കുര്യൻ; ആനന്ദിലെ അമുൽ മാതൃകയായിരുന്നു അടിസ്ഥാനം.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Operation_Flood"}],
 [{"topic": "കമ്പ്യൂട്ടർ അടിസ്ഥാനങ്ങൾ", "title": "ബൈനറി സംഖ്യാവ്യവസ്ഥ: ബേസ് 2", "body": "ബൈനറി സംഖ്യാവ്യവസ്ഥയിൽ 0, 1 എന്നീ രണ്ട് അക്കങ്ങൾ മാത്രം (ബേസ് 2); ഓരോ അക്കവും ഒരു ബിറ്റ് (binary digit). ഉദാ: ദശാംശ 5 = ബൈനറി 101. ആധുനിക ബൈനറി വ്യവസ്ഥ ആവിഷ്കരിച്ചത് ഗോട്ട്ഫ്രീഡ് ലൈബ്നിസ് (1703).", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Binary_number"},
  {"topic": "കമ്പ്യൂട്ടർ അടിസ്ഥാനങ്ങൾ", "title": "ARPANET: ഇന്റർനെറ്റിന്റെ മുൻഗാമി", "body": "യു.എസ്. പ്രതിരോധ ഏജൻസി ARPA-യുടെ ARPANET-ൽ 1969 ഒക്ടോബർ 29-ന് ആദ്യ സന്ദേശം ('lo') അയച്ചു. 1983 ജനുവരി 1-ന് TCP/IP ഇതിന്റെ മാനദണ്ഡമായി. TCP/IP രൂപകൽപ്പന ചെയ്ത വിന്റൺ സെർഫും ബോബ് കാനുമാണ് 'ഇന്റർനെറ്റിന്റെ പിതാക്കന്മാർ'.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/ARPANET"},
  {"topic": "കമ്പ്യൂട്ടർ അടിസ്ഥാനങ്ങൾ", "title": "ഇ-മെയിൽ: റേ ടോംലിൻസൺ, 1971", "body": "1971-ൽ ARPANET-ൽ നെറ്റ്‌വർക്കിലെ വ്യത്യസ്ത കമ്പ്യൂട്ടറുകൾക്കിടയിൽ സന്ദേശം അയക്കാവുന്ന ആദ്യ ഇ-മെയിൽ പ്രോഗ്രാം എഴുതിയത് റേ ടോംലിൻസൺ. ഉപയോക്തൃനാമവും കമ്പ്യൂട്ടറിന്റെ പേരും വേർതിരിക്കാൻ '@' ചിഹ്നം തിരഞ്ഞെടുത്തത് അദ്ദേഹമാണ്.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Ray_Tomlinson"},
  {"topic": "കമ്പ്യൂട്ടർ അടിസ്ഥാനങ്ങൾ", "title": "ഇ-മെയിൽ പ്രോട്ടോക്കോളുകൾ: SMTP, POP, IMAP", "body": "ഇ-മെയിൽ അയയ്ക്കാനുള്ള പ്രോട്ടോക്കോൾ SMTP (Simple Mail Transfer Protocol); മെയിൽ സ്വീകരിച്ച് വായിക്കാൻ POP, IMAP. മെയിൽ സെർവറുകൾ തമ്മിലുള്ള SMTP ആശയവിനിമയം സാധാരണ TCP പോർട്ട് 25 വഴിയാണ്.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Simple_Mail_Transfer_Protocol"},
  {"topic": "കമ്പ്യൂട്ടർ അടിസ്ഥാനങ്ങൾ", "title": "കീബോർഡ് കുറുക്കുവഴികൾ (Windows)", "body": "Ctrl+C – കോപ്പി; Ctrl+X – കട്ട്; Ctrl+V – പേസ്റ്റ്; Ctrl+Z – അൺഡു; Ctrl+Y – റീഡു; Ctrl+A – എല്ലാം തിരഞ്ഞെടുക്കുക; Alt+F4 – സജീവ വിൻഡോ അടയ്ക്കുക; Windows+L – PC ലോക്ക് ചെയ്യുക.", "source": "Microsoft", "url": "https://support.microsoft.com/en-us/windows/keyboard-shortcuts-in-windows-dcc61a57-8ff0-cffe-9796-cb9706c75eec"},
  {"topic": "കമ്പ്യൂട്ടർ അടിസ്ഥാനങ്ങൾ", "title": "ഫയൽ എക്സ്റ്റൻഷനുകൾ: .docx, .xlsx, .pptx", "body": "Office 2007 മുതൽ Microsoft Office-ന്റെ സ്ഥിര ഫയൽ രൂപങ്ങൾ: Word – .docx, Excel – .xlsx, PowerPoint – .pptx. ഇവ ZIP-ൽ പൊതിഞ്ഞ XML ഫയലുകളാണ് (Office Open XML). Windows-ൽ പ്രവർത്തിപ്പിക്കാവുന്ന പ്രോഗ്രാമുകൾക്ക് .exe.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Office_Open_XML"}],
 [{"topic": "കേരള ഭൂമിശാസ്ത്രം", "title": "വെല്ലിംഗ്ടൺ ദ്വീപ്: കൃത്രിമ ദ്വീപ്", "body": "കൊച്ചിയിലെ വെല്ലിംഗ്ടൺ ദ്വീപ് ഇന്ത്യയിലെ ഏറ്റവും വലിയ മനുഷ്യനിർമിത ദ്വീപാണ്. കൊച്ചി തുറമുഖത്തിനായി വേമ്പനാട് ആഴംകൂട്ടിയപ്പോൾ ലഭിച്ച മണ്ണുകൊണ്ട് റോബർട്ട് ബ്രിസ്റ്റോയുടെ നേതൃത്വത്തിൽ നിർമിച്ചു; വൈസ്രോയി വെല്ലിംഗ്ടണിന്റെ പേരാണ് നൽകിയത്.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Willingdon_Island"},
  {"topic": "കേരള ഭൂമിശാസ്ത്രം", "title": "പമ്പ: നീളത്തിൽ മൂന്നാമത്തെ നദി", "body": "176 കി.മീ. നീളമുള്ള പമ്പ കേരളത്തിലെ മൂന്നാമത്തെ നീളം കൂടിയ നദിയാണ് (പെരിയാർ, ഭാരതപ്പുഴ കഴിഞ്ഞാൽ). പീരുമേട്ടിലെ പുളച്ചിമലയിൽ ഉത്ഭവിച്ച് വേമ്പനാട്ടിൽ പതിക്കുന്നു; ശബരിമലയും ആറന്മുള വള്ളംകളിയും പമ്പാതീരത്താണ്.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Pamba_River"},
  {"topic": "കേരള ഭൂമിശാസ്ത്രം", "title": "വിഴിഞ്ഞം: ആഴക്കടൽ ട്രാൻസ്ഷിപ്മെന്റ് തുറമുഖം", "body": "തിരുവനന്തപുരത്തെ വിഴിഞ്ഞം ഇന്റർനാഷണൽ സീപോർട്ട് ഇന്ത്യയിലെ ആദ്യ ആഴക്കടൽ ട്രാൻസ്ഷിപ്മെന്റ് തുറമുഖമാണ്. ഏകദേശം 24 മീറ്റർ സ്വാഭാവിക ആഴമുണ്ട്; 2024 ജൂലൈയിൽ ആദ്യ കപ്പലെത്തി, 2025 മെയ് 2-ന് പ്രധാനമന്ത്രി ഉദ്ഘാടനം ചെയ്തു.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Vizhinjam_International_Seaport"}],
 [{"topic": "ഇന്ത്യൻ-ലോക ഭൂമിശാസ്ത്രം", "title": "ജിം കോർബെറ്റ്: ആദ്യ ദേശീയോദ്യാനം", "body": "ഇന്ത്യയിലെ ആദ്യ ദേശീയോദ്യാനം 1936-ൽ ഹെയ്‌ലി നാഷണൽ പാർക്ക് എന്ന പേരിൽ ഉത്തരാഖണ്ഡിൽ സ്ഥാപിച്ചു. പിന്നീട് രാംഗംഗ, തുടർന്ന് ജിം കോർബെറ്റ് എന്നു പേരുമാറ്റി; പ്രോജക്ട് ടൈഗറിന് കീഴിൽ വന്ന ആദ്യ ഉദ്യാനവുമാണ്.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Jim_Corbett_National_Park"},
  {"topic": "ഇന്ത്യൻ-ലോക ഭൂമിശാസ്ത്രം", "title": "ഇന്ദിരാ പോയിന്റ്: ഇന്ത്യയുടെ തെക്കേയറ്റം", "body": "ഗ്രേറ്റ് നിക്കോബാർ ദ്വീപിലെ ഇന്ദിരാ പോയിന്റാണ് ഇന്ത്യൻ ഭൂപ്രദേശത്തിന്റെ തെക്കേയറ്റം. പിഗ്മാലിയൻ പോയിന്റ്, പാഴ്സൺസ് പോയിന്റ് എന്നായിരുന്നു പഴയ പേരുകൾ; 2004-ലെ ഭൂകമ്പത്തിൽ ഈ മുനമ്പ് 4.25 മീറ്റർ താഴ്ന്നു.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Indira_Point"},
  {"topic": "ഇന്ത്യൻ-ലോക ഭൂമിശാസ്ത്രം", "title": "പാക് കടലിടുക്ക്: ഇന്ത്യ-ശ്രീലങ്ക", "body": "തമിഴ്നാട്ടിലെ പാമ്പൻ ദ്വീപിനും ശ്രീലങ്കയിലെ മന്നാർ ദ്വീപിനും ഇടയിലാണ് പാക് കടലിടുക്ക്; ഇത് ബംഗാൾ ഉൾക്കടലിനെ ലക്ഷദ്വീപ് കടലുമായി ബന്ധിപ്പിക്കുന്നു. മദ്രാസ് ഗവർണർ റോബർട്ട് പാക്കിന്റെ പേരാണ്; രാമസേതു (ആഡംസ് ബ്രിഡ്ജ്) ഇതിനോട് ചേർന്നാണ്.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Palk_Strait"},
  {"topic": "ഇന്ത്യൻ-ലോക ഭൂമിശാസ്ത്രം", "title": "പസഫിക്: ഏറ്റവും വലുതും ആഴമേറിയതും", "body": "ലോകത്തിലെ ഏറ്റവും വലുതും ആഴമേറിയതുമായ സമുദ്രമാണ് പസഫിക്; ഭൂമിയിലെ മുഴുവൻ കരയേക്കാളും വലുതാണ്. ‘ശാന്തമായ കടൽ’ എന്നർഥത്തിൽ മഗല്ലൻ പേരിട്ടു. മരിയാന ട്രെഞ്ചിലെ ചലഞ്ചർ ഡീപ്പ് ഭൂമിയിലെ ഏറ്റവും ആഴമേറിയ സ്ഥലമാണ്.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Pacific_Ocean"},
  {"topic": "ഇന്ത്യൻ-ലോക ഭൂമിശാസ്ത്രം", "title": "നൈൽ: ഏറ്റവും നീളം കൂടിയ നദി", "body": "വടക്കുകിഴക്കൻ ആഫ്രിക്കയിലൂടെ വടക്കോട്ടൊഴുകുന്ന നൈൽ ലോകത്തിലെ ഏറ്റവും നീളം കൂടിയ നദിയായി കണക്കാക്കപ്പെടുന്നു. വിക്ടോറിയ തടാകത്തിനടുത്തുനിന്നുള്ള വൈറ്റ് നൈലും താനാ തടാകത്തിൽനിന്നുള്ള ബ്ലൂ നൈലും ഖാർത്തൂമിൽ ചേരുന്നു; മെഡിറ്ററേനിയനിൽ പതിക്കുന്നു.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Nile"},
  {"topic": "ഇന്ത്യൻ-ലോക ഭൂമിശാസ്ത്രം", "title": "സഹാറ: ഏറ്റവും വലിയ ഉഷ്ണമരുഭൂമി", "body": "ഏകദേശം 92 ലക്ഷം ച.കി.മീ. വിസ്തൃതിയുള്ള സഹാറ ലോകത്തിലെ ഏറ്റവും വലിയ ഉഷ്ണമരുഭൂമിയാണ്. എല്ലാ മരുഭൂമികളും ചേർത്താൽ അന്റാർട്ടിക്കയ്ക്കും ആർട്ടിക്കിനും പിന്നിൽ മൂന്നാമത്; ‘സഹാറ’ എന്ന അറബിവാക്കിന്റെ അർഥം മരുഭൂമി.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Sahara"},
  {"topic": "ഇന്ത്യൻ-ലോക ഭൂമിശാസ്ത്രം", "title": "അന്താരാഷ്ട്ര ദിനാങ്കരേഖ: 180°", "body": "അന്താരാഷ്ട്ര ദിനാങ്കരേഖ പസഫിക് സമുദ്രത്തിലൂടെ ഏകദേശം 180° രേഖാംശം പിന്തുടരുന്നു. പടിഞ്ഞാറോട്ട് കടക്കുമ്പോൾ ഒരു ദിവസം കൂടും, കിഴക്കോട്ട് കടക്കുമ്പോൾ ഒരു ദിവസം കുറയും; ദ്വീപുരാജ്യങ്ങളെ ഒഴിവാക്കാൻ രേഖ വളഞ്ഞുപോകുന്നു.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/International_Date_Line"}],
 [{"topic": "ഇന്ത്യൻ ചരിത്രം", "title": "കമ്പോള പരിഷ്കാരം: അലാവുദ്ദീൻ ഖിൽജി", "body": "ഡൽഹി സുൽത്താൻ അലാവുദ്ദീൻ ഖിൽജി (1296–1316) ധാന്യങ്ങൾക്കും തുണിക്കും മറ്റും വില നിശ്ചയിക്കുന്ന കമ്പോള പരിഷ്കാരങ്ങൾ നടപ്പാക്കി. വലിയ സൈന്യത്തിന് കുറഞ്ഞ ശമ്പളം നൽകി നിലനിർത്തുകയായിരുന്നു ലക്ഷ്യമെന്ന് സിയാവുദ്ദീൻ ബറാനി രേഖപ്പെടുത്തുന്നു.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Market_reforms_of_Alauddin_Khalji"},
  {"topic": "ഇന്ത്യൻ ചരിത്രം", "title": "1911: തലസ്ഥാനം കൽക്കത്തയിൽനിന്ന് ഡൽഹിയിലേക്ക്", "body": "1911 ഡിസംബർ 12-ലെ ഡൽഹി ദർബാറിൽ ജോർജ് അഞ്ചാമൻ ചക്രവർത്തി ബ്രിട്ടീഷ് ഇന്ത്യയുടെ തലസ്ഥാനം കൽക്കത്തയിൽനിന്ന് ഡൽഹിയിലേക്ക് മാറ്റുന്നതായി പ്രഖ്യാപിച്ചു. ബംഗാൾ വിഭജനം റദ്ദാക്കിയതും ഇതേ ചടങ്ങിലാണ്.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Delhi_Durbar"},
  {"topic": "ഇന്ത്യൻ ചരിത്രം", "title": "റിപ്പൺ പ്രഭുവും തദ്ദേശ സ്വയംഭരണവും", "body": "വൈസ്രോയി റിപ്പൺ പ്രഭു 1882 മെയ് 18-ന് തദ്ദേശ സ്വയംഭരണ പ്രമേയം പുറപ്പെടുവിച്ചു; തിരഞ്ഞെടുക്കപ്പെട്ട അനൗദ്യോഗിക അംഗങ്ങൾക്ക് ഭൂരിപക്ഷവും അനൗദ്യോഗിക അധ്യക്ഷനുമുള്ള തദ്ദേശസ്ഥാപനങ്ങൾ വേണമെന്ന് നിർദേശിച്ച ഈ പ്രമേയം അധികാര വികേന്ദ്രീകരണത്തിലെ നാഴികക്കല്ലാണ്.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Panchayati_raj"},
  {"topic": "ഇന്ത്യൻ ചരിത്രം", "title": "സതി നിരോധനം 1829: വില്യം ബെന്റിക്", "body": "ഗവർണർ ജനറൽ വില്യം ബെന്റിക് 1829 ഡിസംബർ 4-ന് റെഗുലേഷൻ XVII വഴി ബംഗാളിൽ സതി നിരോധിച്ചു. 1833-ലെ ചാർട്ടർ ആക്ടിലൂടെ അദ്ദേഹം ഇന്ത്യയുടെ ആദ്യ ഗവർണർ ജനറലുമായി.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Lord_William_Bentinck"},
  {"topic": "ഇന്ത്യൻ ചരിത്രം", "title": "ഹാരപ്പ 1921, മോഹൻജൊദാരോ 1922", "body": "സിന്ധുനദീതട സംസ്കാരത്തിലെ ഹാരപ്പയിൽ 1921-ൽ ദയാറാം സാഹ്നി ഉത്ഖനനം തുടങ്ങി; രാവി നദിയുടെ പഴയ തീരത്താണ് ഇത്. സിന്ധു നദിക്കരയിലെ മോഹൻജൊദാരോ 1922-ൽ രാഖൽദാസ് ബാനർജി കണ്ടെത്തി; ഇരുസ്ഥലങ്ങളും ഇന്ന് പാകിസ്താനിൽ.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Harappa"}],
 [{"topic": "കേരള ചരിത്രം", "title": "ചട്ടമ്പിസ്വാമികൾ: ജനനം കണ്ണമ്മൂല, സമാധി പന്മന", "body": "ചട്ടമ്പിസ്വാമികൾ 1853-ൽ തിരുവനന്തപുരം കണ്ണമ്മൂലയിൽ ജനിച്ചു; യഥാർത്ഥ പേര് അയ്യപ്പൻ, ബാല്യനാമം കുഞ്ഞൻപിള്ള. ‘ക്രിസ്തുമതനിരൂപണം’, ‘പ്രാചീനമലയാളം’ എന്നിവ കൃതികൾ. 1924-ൽ പന്മനയിൽ സമാധിയായി.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Chattampi_Swamikal"},
  {"topic": "കേരള ചരിത്രം", "title": "വാഗൺ ട്രാജഡി 1921: മലബാർ കലാപം", "body": "1921 ഓഗസ്റ്റിൽ ആരംഭിച്ച മലബാർ കലാപത്തിൽ പിടിയിലായ നൂറോളം മാപ്പിള തടവുകാരെ അടച്ച ചരക്കുവാഗണിൽ തിരൂരിൽനിന്ന് പോത്തന്നൂരിലേക്ക് കൊണ്ടുപോയി. 1921 നവംബർ 20-ന് വാഗൺ തുറന്നപ്പോൾ 64 പേർ മരിച്ചിരുന്നു; ആകെ മരണം 70.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Wagon_tragedy"},
  {"topic": "കേരള ചരിത്രം", "title": "മലബാർ കലാപം 1921: നേതാക്കൾ", "body": "1921 ഓഗസ്റ്റിൽ ഏറനാട്, വള്ളുവനാട് താലൂക്കുകളിൽ ആരംഭിച്ച മലബാർ കലാപത്തിന്റെ ആദ്യ നേതാവ് ആലി മുസ്ലിയാർ. ഓഗസ്റ്റ് 24-ന് വാരിയൻകുന്നത്ത് കുഞ്ഞഹമ്മദ് ഹാജി നേതൃത്വം ഏറ്റെടുത്തു; ഖിലാഫത്ത് പ്രസ്ഥാനം പശ്ചാത്തലമായി.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Malabar_rebellion"},
  {"topic": "കേരള ചരിത്രം", "title": "നിവർത്തന പ്രക്ഷോഭം: സി. കേശവൻ", "body": "നിയമസഭയിൽ പിന്നാക്കവിഭാഗങ്ങൾക്ക് മതിയായ പ്രാതിനിധ്യം ആവശ്യപ്പെട്ട നിവർത്തന (വിട്ടുനിൽക്കൽ) പ്രക്ഷോഭത്തിലെ പ്രമുഖ നേതാവാണ് സി. കേശവൻ. കോഴഞ്ചേരി പ്രസംഗത്തിന്റെ പേരിൽ 1935 ജൂൺ 7-ന് അറസ്റ്റിലായി; രണ്ടു വർഷം തടവ് ലഭിച്ചു.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/C._Kesavan"},
  {"topic": "കേരള ചരിത്രം", "title": "പയ്യന്നൂർ ഉപ്പുസത്യാഗ്രഹം 1930: കേളപ്പൻ", "body": "1930 ഏപ്രിൽ 13-ന് കെ. കേളപ്പന്റെ നേതൃത്വത്തിൽ 32 അംഗ ജാഥ കോഴിക്കോട്ടുനിന്ന് പുറപ്പെട്ട് ഏപ്രിൽ 21-ന് പയ്യന്നൂരിലെത്തി; ഉളിയത്ത് കടവിൽ ഉപ്പ് കുറുക്കി നിയമം ലംഘിച്ചു. കേരളത്തിലെ ഉപ്പുസത്യാഗ്രഹത്തിന്റെ പ്രധാന വേദി പയ്യന്നൂരായിരുന്നു.", "source": "ETV Bharat", "url": "https://etvbharat.com/english/bharat/75-years-of-independence-kerala-owes-this-remote-land-for-its-glory-in-freedom-struggle/na20211211060338758"},
  {"topic": "കേരള ചരിത്രം", "title": "ഒറ്റപ്പാലം 1921: ആദ്യ കെ.പി.സി.സി. സമ്മേളനം", "body": "കേരള പ്രദേശ് കോൺഗ്രസ് കമ്മിറ്റിയുടെ (KPCC) ആദ്യ സമ്മേളനം 1921-ൽ ഒറ്റപ്പാലത്ത് എ.ഐ.സി.സി. നേതാവ് ടി. പ്രകാശത്തിന്റെ സാന്നിധ്യത്തിൽ നടന്നു. മലബാർ, കൊച്ചി, തിരുവിതാംകൂർ മേഖലകളിൽനിന്നുള്ള പ്രതിനിധികൾ പങ്കെടുത്തു.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Kerala_Pradesh_Congress_Committee"},
  {"topic": "കേരള ചരിത്രം", "title": "വൈക്കം സത്യാഗ്രഹം: 603 ദിവസം, ‘വൈക്കം വീരൻ’", "body": "1924 മാർച്ച് 30 മുതൽ 1925 നവംബർ 23 വരെ, 603 ദിവസം വൈക്കം സത്യാഗ്രഹം നീണ്ടു. രണ്ടുതവണ ജയിലിലായ ഇ.വി. രാമസ്വാമി നായ്ക്കർ (പെരിയാർ) ‘വൈക്കം വീരൻ’ എന്നറിയപ്പെട്ടു; 1925 മാർച്ചിൽ ഗാന്ധിജി വൈക്കം സന്ദർശിച്ചു.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Vaikom_Satyagraha"},
  {"topic": "കേരള ചരിത്രം", "title": "ഗുരുവായൂർ: പൊന്നാനി താലൂക്കിലെ ജനഹിത പരിശോധന", "body": "ഗുരുവായൂർ സത്യാഗ്രഹത്തിന്റെ ഭാഗമായി പൊന്നാനി താലൂക്കിൽ നടത്തിയ ജനഹിത പരിശോധനയിൽ 77 ശതമാനം പേർ എല്ലാ ജാതിക്കാർക്കും ക്ഷേത്രപ്രവേശനം അനുകൂലിച്ചു. 1932 സെപ്റ്റംബർ 22-ന് കേളപ്പൻ ആരംഭിച്ച ഉപവാസം ഗാന്ധിജിയുടെ ഇടപെടലിൽ ഒക്ടോബർ 2-ന് അവസാനിപ്പിച്ചു.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Guruvayur_Satyagraha"},
  {"topic": "കേരള ചരിത്രം", "title": "പാലിയത്തച്ചൻ: കൊച്ചിയിലെ പ്രധാനമന്ത്രി", "body": "കൊച്ചി രാജ്യത്തിന്റെ പാരമ്പര്യ പ്രധാനമന്ത്രി സ്ഥാനം വഹിച്ച പാലിയത്ത് ഗോവിന്ദൻ അച്ചൻ 1808-ൽ ബ്രിട്ടീഷ് റസിഡന്റ് മെക്കാളെയുടെ ആസ്ഥാനം ആക്രമിച്ചു; വേലുത്തമ്പിയോടൊപ്പം ബ്രിട്ടീഷുകാർക്കെതിരെ പോരാടി. പിന്നീട് മദ്രാസിലേക്ക് നാടുകടത്തപ്പെട്ടു.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Paliath_Achan"},
  {"topic": "കേരള ചരിത്രം", "title": "ചാന്നാർ ലഹള: 1813–1859", "body": "മാറുമറയ്ക്കാനുള്ള അവകാശത്തിനായി തിരുവിതാംകൂറിലെ നാടാർ (ചാന്നാർ) സ്ത്രീകൾ 1813 മുതൽ 1859 വരെ നടത്തിയ സമരമാണ് ചാന്നാർ ലഹള (മാറുമറയ്ക്കൽ സമരം). മദ്രാസ് ഗവർണറുടെ സമ്മർദത്തെ തുടർന്ന് 1859-ൽ മേൽവസ്ത്രം ധരിക്കാൻ അനുമതി നൽകുന്ന വിളംബരം വന്നു.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Channar_revolt"}],
 [{"topic": "കേരള ഭരണസംവിധാനം", "title": "കേരള ഭൂപരിഷ്കരണ നിയമം 1963", "body": "കേരള ഭൂപരിഷ്കരണ നിയമം 1963 (1964-ലെ 1-ാം നിയമം) 1963 ഡിസംബർ 31-ന് രാഷ്ട്രപതിയുടെ അനുമതി നേടി. 1969-ലെ 35-ാം നിയമം വഴി വിപുലമായി ഭേദഗതി ചെയ്തു; ഭേദഗതി 1970 ജനുവരി 1 മുതൽ പ്രാബല്യത്തിൽ വന്നു.", "source": "Supreme Court (Legal Authority)", "url": "https://www.legalauthority.in/judgement/chettiam-veettil-ammad-and-anr-vs-taluk-land-board-and-ors-32277"},
  {"topic": "കേരള ഭരണസംവിധാനം", "title": "സേവനാവകാശ നിയമം: 2012", "body": "കേരള നിയമസഭ 2012 ജൂലൈ 25-ന് സേവനാവകാശ ബിൽ പാസാക്കി. നിശ്ചിത സമയപരിധിക്കുള്ളിൽ സർക്കാർ സേവനങ്ങൾ ഉറപ്പാക്കുന്നു; വീഴ്ച വരുത്തുന്ന ഉദ്യോഗസ്ഥന് പിഴ ചുമത്തും.", "source": "Millennium Post", "url": "https://www.millenniumpost.in/right-to-service-becomes-law-in-kerala-5743"},
  {"topic": "കേരള ഭരണസംവിധാനം", "title": "സംസ്ഥാന ആസൂത്രണ ബോർഡ്: 1967", "body": "കേരള സംസ്ഥാന ആസൂത്രണ ബോർഡ് 1967-ൽ രൂപീകരിച്ചു. മുഖ്യമന്ത്രിയാണ് ചെയർമാൻ; ഒരു അനൗദ്യോഗിക അംഗം പാർട്ട്-ടൈം വൈസ് ചെയർമാനും. ആസ്ഥാനം തിരുവനന്തപുരം.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Kerala_State_Planning_Board"},
  {"topic": "കേരള ഭരണസംവിധാനം", "title": "കേരള മോഡൽ: സാക്ഷരതയും സ്ത്രീപുരുഷാനുപാതവും", "body": "2011 സെൻസസ് പ്രകാരം കേരളത്തിന്റെ സാക്ഷരതാ നിരക്ക് 94.59% ആണ് (പുരുഷൻ 97.10%, സ്ത്രീ 92.12%). സ്ത്രീപുരുഷാനുപാതം 1000 പുരുഷന്മാർക്ക് 1084 സ്ത്രീകൾ. ശിശുമരണ നിരക്ക് 7 (2018) – കേരള മോഡലിന്റെ സൂചകങ്ങൾ.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Kerala_model"},
  {"topic": "കേരള ഭരണസംവിധാനം", "title": "എറണാകുളം: ആദ്യ സമ്പൂർണ സാക്ഷരതാ ജില്ല", "body": "1990 ഫെബ്രുവരി 4-ന് പ്രധാനമന്ത്രി വി.പി. സിംഗ് എറണാകുളത്തെ ഇന്ത്യയിലെ ആദ്യ സമ്പൂർണ സാക്ഷരതാ ജില്ലയായി പ്രഖ്യാപിച്ചു. ഈ വിജയമാണ് 1991-ലെ സംസ്ഥാനവ്യാപക സമ്പൂർണ സാക്ഷരതാ പ്രഖ്യാപനത്തിലേക്ക് നയിച്ചത്.", "source": "The South First", "url": "https://thesouthfirst.com/kerala/100-literacy-saare-how-keralas-ernakulam-rewrote-indias-education-map/"},
  {"topic": "കേരള ഭരണസംവിധാനം", "title": "മലബാർ വിഭജനം: 1957 ജനുവരി 1", "body": "1957 ജനുവരി 1-ന് മലബാർ ജില്ല വിഭജിച്ച് കോഴിക്കോട്, പാലക്കാട്, കണ്ണൂർ എന്നീ മൂന്ന് ജില്ലകൾ രൂപീകരിച്ചു. തിരുവനന്തപുരം, കൊല്ലം, കോട്ടയം, തൃശൂർ ജില്ലകൾ 1949-ലെ തിരു-കൊച്ചി കാലം മുതലുള്ളവയാണ്.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/List_of_districts_of_Kerala"},
  {"topic": "കേരള ഭരണസംവിധാനം", "title": "ആലപ്പുഴ ജില്ല: 1957 ഓഗസ്റ്റ് 17", "body": "കേരളപ്പിറവിക്ക് ശേഷം തിരു-കൊച്ചി മേഖലയിൽ രൂപീകരിച്ച ആദ്യ പുതിയ ജില്ലയാണ് ആലപ്പുഴ; 1957 ഓഗസ്റ്റ് 17-നാണ് രൂപീകരണം. തുടർന്ന് 1958 ഏപ്രിൽ 1-ന് എറണാകുളം ജില്ലയും നിലവിൽ വന്നു.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/List_of_districts_of_Kerala"},
  {"topic": "കേരള ഭരണസംവിധാനം", "title": "എറണാകുളം ജില്ല: 1958 ഏപ്രിൽ 1", "body": "എറണാകുളം ജില്ല 1958 ഏപ്രിൽ 1-ന് രൂപീകരിച്ചു. കേരള ഹൈക്കോടതിയുടെ ആസ്ഥാനമായ കൊച്ചി ഈ ജില്ലയിലാണ്. 1990-ൽ രാജ്യത്തെ ആദ്യ സമ്പൂർണ സാക്ഷരതാ ജില്ലയായി പ്രഖ്യാപിക്കപ്പെട്ടതും എറണാകുളമാണ്.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/List_of_districts_of_Kerala"},
  {"topic": "കേരള ഭരണസംവിധാനം", "title": "മലപ്പുറം ജില്ല: 1969 ജൂൺ 16", "body": "മലപ്പുറം ജില്ല 1969 ജൂൺ 16-ന് നിലവിൽ വന്നു; കേരളത്തിലെ 10-ാമത്തെ ജില്ല. 1957-ലെ മലബാർ വിഭജനത്തിനു ശേഷം വടക്കൻ കേരളത്തിൽ രൂപീകരിച്ച ആദ്യ പുതിയ ജില്ലയാണിത്. അക്ഷയ പദ്ധതി ആരംഭിച്ചതും മലപ്പുറത്താണ്.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/List_of_districts_of_Kerala"},
  {"topic": "കേരള ഭരണസംവിധാനം", "title": "ഇടുക്കി ജില്ല: 1972 ജനുവരി 26", "body": "ഇടുക്കി ജില്ല 1972 ജനുവരി 26-ന്, റിപ്പബ്ലിക് ദിനത്തിൽ, രൂപീകരിച്ചു. കേരളത്തിലെ 11-ാമത്തെ ജില്ലയാണ് ഇടുക്കി. 1969-ലെ മലപ്പുറത്തിനു ശേഷം രൂപീകരിച്ച ജില്ലയും ഇതാണ്.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/List_of_districts_of_Kerala"}],
 [{"topic": "ഭൗതികശാസ്ത്രം", "title": "ട്രാൻസിസ്റ്റർ: 1947, ബെൽ ലാബ്സ്", "body": "ആദ്യ ട്രാൻസിസ്റ്റർ (പോയിന്റ്-കോൺടാക്റ്റ്) 1947-ൽ അമേരിക്കയിലെ ബെൽ ലാബ്സിൽ ജോൺ ബാർഡീൻ, വാൾട്ടർ ബ്രാറ്റെയ്ൻ, വില്യം ഷോക്ലി എന്നിവർ വികസിപ്പിച്ചു. മൂവരും 1956-ലെ ഭൗതികശാസ്ത്ര നൊബേൽ പങ്കിട്ടു.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Transistor"},
  {"topic": "ഭൗതികശാസ്ത്രം", "title": "സി.വി. രാമൻ: 1930-ലെ നൊബേൽ", "body": "പ്രകാശത്തിന്റെ വിസരണത്തെക്കുറിച്ചുള്ള പഠനത്തിനും 'രാമൻ പ്രഭാവം' കണ്ടെത്തിയതിനും സി.വി. രാമന് 1930-ൽ ഭൗതികശാസ്ത്ര നൊബേൽ ലഭിച്ചു. ഈ നേട്ടം കൈവരിച്ച ആദ്യ ഏഷ്യക്കാരനാണ് അദ്ദേഹം; 1954-ൽ ഭാരതരത്നം ലഭിച്ചു.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/C._V._Raman"},
  {"topic": "ഭൗതികശാസ്ത്രം", "title": "ദേശീയ ശാസ്ത്രദിനം: ഫെബ്രുവരി 28", "body": "സി.വി. രാമൻ 1928-ൽ 'രാമൻ പ്രഭാവം' കണ്ടെത്തിയതിന്റെ സ്മരണയ്ക്കായി ഇന്ത്യ എല്ലാ വർഷവും ഫെബ്രുവരി 28 ദേശീയ ശാസ്ത്രദിനമായി ആചരിക്കുന്നു. ആദ്യ ദേശീയ ശാസ്ത്രദിനം 1987-ലായിരുന്നു.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/National_Science_Day"},
  {"topic": "ഭൗതികശാസ്ത്രം", "title": "തുമ്പ: ആദ്യ റോക്കറ്റ് വിക്ഷേപണം 1963", "body": "1963 നവംബർ 21-ന് തിരുവനന്തപുരത്തെ തുമ്പ ഇക്വറ്റോറിയൽ റോക്കറ്റ് ലോഞ്ചിങ് സ്റ്റേഷനിൽ (TERLS) നിന്ന് നൈക്ക്-അപ്പാച്ചി റോക്കറ്റ് വിക്ഷേപിച്ചു. ഭൂകാന്തിക മധ്യരേഖയോടുള്ള സാമീപ്യമാണ് തുമ്പയെ തിരഞ്ഞെടുക്കാൻ കാരണം.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Thumba_Equatorial_Rocket_Launching_Station"},
  {"topic": "ഭൗതികശാസ്ത്രം", "title": "മംഗൾയാൻ: ചൊവ്വയിലെത്തിയ ആദ്യ ഏഷ്യൻ രാജ്യം", "body": "മാർസ് ഓർബിറ്റർ മിഷൻ (മംഗൾയാൻ) 2013 നവംബർ 5-ന് PSLV-C25 ഉപയോഗിച്ച് ശ്രീഹരിക്കോട്ടയിൽനിന്ന് വിക്ഷേപിച്ചു. 2014 സെപ്റ്റംബർ 24-ന് ചൊവ്വയുടെ ഭ്രമണപഥത്തിലെത്തിയതോടെ ഇത് നേടിയ ആദ്യ ഏഷ്യൻ രാജ്യമായി ഇന്ത്യ.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Mars_Orbiter_Mission"},
  {"topic": "ഭൗതികശാസ്ത്രം", "title": "താരാപ്പൂർ: ആദ്യ വാണിജ്യ ആണവനിലയം", "body": "ഇന്ത്യയിലെ ആദ്യ വാണിജ്യ ആണവ വൈദ്യുതനിലയമാണ് മഹാരാഷ്ട്രയിലെ (പാൽഘർ ജില്ല) താരാപ്പൂർ. ആദ്യ രണ്ട് യൂണിറ്റുകൾ 1969 ഒക്ടോബർ 28-ന് വാണിജ്യ ഉൽപ്പാദനം തുടങ്ങി; യു.എസ്. കമ്പനികളായ GE, ബെക്ടൽ എന്നിവയാണ് നിർമ്മിച്ചത്.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Tarapur_Atomic_Power_Station"}],
 [{"topic": "രസതന്ത്രം", "title": "വിനാഗിരി: അസറ്റിക് ആസിഡ്", "body": "വിനാഗിരിയിലെ പ്രധാന ആസിഡ് അസറ്റിക് ആസിഡാണ്; നേർപ്പിച്ച അസറ്റിക് ആസിഡ് ലായനിയാണ് വിനാഗിരി. സാധാരണ വെളുത്ത വിനാഗിരിയിൽ 5–8% അസറ്റിക് ആസിഡ് അടങ്ങിയിരിക്കുന്നു.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Vinegar"},
  {"topic": "രസതന്ത്രം", "title": "പിച്ചള: ചെമ്പും സിങ്കും", "body": "ചെമ്പും (കോപ്പർ) സിങ്കും ചേർന്ന ലോഹസങ്കരമാണ് പിച്ചള (ബ്രാസ്). ഇവയുടെ അനുപാതം മാറ്റി വ്യത്യസ്ത നിറവും ഗുണങ്ങളും നേടാം. ഓടിൽ (ബ്രോൺസ്) സിങ്കിന് പകരം ടിൻ ആണ് ചേർക്കുന്നത്.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Brass"},
  {"topic": "രസതന്ത്രം", "title": "ഓട് (ബ്രോൺസ്): ചെമ്പും ടിന്നും", "body": "പ്രധാനമായും ചെമ്പും ഏകദേശം 12% ടിന്നും ചേർന്ന ലോഹസങ്കരമാണ് ഓട് (ബ്രോൺസ്). ഓട് ഏറ്റവും കടുപ്പമേറിയ ലോഹമായി വ്യാപകമായി ഉപയോഗിച്ചിരുന്ന പുരാവസ്തു കാലഘട്ടമാണ് 'വെങ്കലയുഗം' (Bronze Age).", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Bronze"},
  {"topic": "രസതന്ത്രം", "title": "LPG: പ്രൊപ്പേനും ബ്യൂട്ടേനും", "body": "പാചകവാതകമായ LPG (ലിക്വിഫൈഡ് പെട്രോളിയം ഗ്യാസ്) പ്രധാനമായും പ്രൊപ്പേൻ, ബ്യൂട്ടേൻ എന്നിവയുടെ മിശ്രിതമാണ്. ചോർച്ച എളുപ്പം തിരിച്ചറിയാൻ രൂക്ഷഗന്ധമുള്ള ഈഥെയ്ൻതയോൾ (ഈഥൈൽ മെർകാപ്റ്റൻ) ചേർക്കുന്നു.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Liquefied_petroleum_gas"},
  {"topic": "രസതന്ത്രം", "title": "CNG: പ്രധാന ഘടകം മീഥേൻ", "body": "CNG (കംപ്രസ്ഡ് നാച്ചുറൽ ഗ്യാസ്) പ്രധാനമായും മീഥേൻ (CH₄) ആണ്. ഏകദേശം 200–250 ബാർ മർദ്ദത്തിൽ സംഭരിക്കുന്ന ഇത് വാഹനങ്ങളിൽ പെട്രോളിന് പകരമുള്ള ഇന്ധനമായി ഉപയോഗിക്കുന്നു.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Compressed_natural_gas"}],
 [{"topic": "കല, സാഹിത്യം, കായികം", "title": "ഹോക്കി: 8 ഒളിമ്പിക് സ്വർണ്ണം", "body": "ഇന്ത്യൻ പുരുഷ ഹോക്കി ടീം റെക്കോർഡ് 8 ഒളിമ്പിക് സ്വർണ്ണം നേടി; ആദ്യത്തേത് 1928 ആംസ്റ്റർഡാമിൽ, അവസാനത്തേത് 1980 മോസ്കോയിൽ. 41 വർഷത്തിനു ശേഷം ടോക്യോ 2020-ൽ വെങ്കലം നേടി.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/India_men%27s_national_field_hockey_team"},
  {"topic": "കല, സാഹിത്യം, കായികം", "title": "ദേശീയ കായിക ദിനം: ഓഗസ്റ്റ് 29", "body": "ഹോക്കി ഇതിഹാസം മേജർ ധ്യാൻചന്ദിന്റെ ജന്മദിനമായ ഓഗസ്റ്റ് 29 ഇന്ത്യയിൽ ദേശീയ കായിക ദിനമായി ആചരിക്കുന്നു. പരമോന്നത കായിക ബഹുമതിയായ ഖേൽരത്ന 2021 മുതൽ 'മേജർ ധ്യാൻചന്ദ് ഖേൽരത്ന' എന്നാണ്.", "source": "All India Radio News", "url": "https://newsonair.gov.in/national-sports-day-being-observed-today-prime-minister-modi-pays-tribute-to-major-dhyan-chand/"},
  {"topic": "കല, സാഹിത്യം, കായികം", "title": "കേരള കായിക ദിനം: ഒക്ടോബർ 13", "body": "കേരള കായികരംഗത്തിന്റെ പിതാവായ കേണൽ ജി.വി. രാജയുടെ ജന്മദിനമായ ഒക്ടോബർ 13 കേരള കായിക ദിനമായി ആചരിക്കുന്നു. കേരള സ്പോർട്സ് കൗൺസിലിന്റെ സ്ഥാപക പ്രസിഡന്റായിരുന്നു; 1971-ൽ വിമാനാപകടത്തിൽ മരിച്ചു.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/G._V._Raja"},
  {"topic": "കല, സാഹിത്യം, കായികം", "title": "ഒ.എം. നമ്പ്യാർ: ആദ്യ മലയാളി ദ്രോണാചാര്യ", "body": "1985-ൽ ഏർപ്പെടുത്തിയ ദ്രോണാചാര്യ അവാർഡിന്റെ ആദ്യ ജേതാക്കളിൽ ഒരാളായ ഒ.എം. നമ്പ്യാർ (അത്‌ലറ്റിക്സ്) ഈ ബഹുമതി നേടിയ ആദ്യ മലയാളിയാണ്. പി.ടി. ഉഷയുടെ പരിശീലകനായിരുന്നു; 2021-ൽ പത്മശ്രീ.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/O._M._Nambiar"},
  {"topic": "കല, സാഹിത്യം, കായികം", "title": "നെഹ്റു ട്രോഫി: പുന്നമടക്കായൽ", "body": "ആലപ്പുഴ പുന്നമടക്കായലിൽ ഓഗസ്റ്റിലെ രണ്ടാം ശനിയാഴ്ച നടക്കുന്ന ചുണ്ടൻവള്ളംകളിയാണ് നെഹ്റു ട്രോഫി. 1952-ൽ ആലപ്പുഴ സന്ദർശിച്ച നെഹ്റു വെള്ളിയിൽ തീർത്ത ചുണ്ടൻവള്ള മാതൃക ട്രോഫിയായി സമ്മാനിച്ചു.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Nehru_Trophy_Boat_Race"},
  {"topic": "കല, സാഹിത്യം, കായികം", "title": "രഞ്ജി ട്രോഫി: ക്രിക്കറ്റ്, 1934", "body": "ഇന്ത്യയിലെ ദേശീയ ഫസ്റ്റ് ക്ലാസ് ക്രിക്കറ്റ് ചാമ്പ്യൻഷിപ്പാണ് രഞ്ജി ട്രോഫി; ആദ്യ സീസൺ 1934–35. അന്താരാഷ്ട്ര ക്രിക്കറ്റ് കളിച്ച ആദ്യ ഇന്ത്യക്കാരനായ രഞ്ജിത്സിങ്ജിയുടെ പേരിലാണ്. ആദ്യ ജേതാക്കൾ ബോംബെ.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Ranji_Trophy"},
  {"topic": "കല, സാഹിത്യം, കായികം", "title": "കുന്ദലത: മലയാളത്തിലെ ആദ്യ നോവൽ", "body": "അപ്പു നെടുങ്ങാടി 1887-ൽ പ്രസിദ്ധീകരിച്ച 'കുന്ദലത' മലയാളത്തിലെ ആദ്യ നോവലായി കണക്കാക്കപ്പെടുന്നു. ലക്ഷണമൊത്ത ആദ്യ നോവൽ എന്ന ബഹുമതി 1889-ലെ ഒ. ചന്തുമേനോന്റെ 'ഇന്ദുലേഖ'യ്ക്കാണ്.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Kundalatha"},
  {"topic": "കല, സാഹിത്യം, കായികം", "title": "ഇന്ദുലേഖ: ഒ. ചന്തുമേനോൻ, 1889", "body": "ഒ. ചന്തുമേനോൻ 1889 ഡിസംബർ 9-ന് പ്രസിദ്ധീകരിച്ച 'ഇന്ദുലേഖ' മലയാളത്തിലെ ആദ്യത്തെ ലക്ഷണമൊത്ത പ്രധാന നോവലാണ്. ഇന്ദുലേഖ, മാധവൻ, സൂരി നമ്പൂതിരിപ്പാട്, പഞ്ചുമേനോൻ എന്നിവർ പ്രധാന കഥാപാത്രങ്ങൾ.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Indulekha_(novel)"},
  {"topic": "കല, സാഹിത്യം, കായികം", "title": "എഴുത്തച്ഛൻ: ആധുനിക മലയാളത്തിന്റെ പിതാവ്", "body": "തുഞ്ചത്ത് രാമാനുജൻ എഴുത്തച്ഛനെ ആധുനിക മലയാള ഭാഷയുടെ/സാഹിത്യത്തിന്റെ പിതാവ് എന്ന് വിളിക്കുന്നു. പ്രധാന കൃതി 'അദ്ധ്യാത്മരാമായണം കിളിപ്പാട്ട്'. ജന്മസ്ഥലമായ തുഞ്ചൻപറമ്പ് മലപ്പുറം ജില്ലയിലെ തിരൂരിലാണ്; കാലം 16-ാം നൂറ്റാണ്ട്.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Thunchaththu_Ramanujan_Ezhuthachan"},
  {"topic": "കല, സാഹിത്യം, കായികം", "title": "വീണപൂവ്: കുമാരനാശാൻ, 1907", "body": "കുമാരനാശാന്റെ 'വീണപൂവ്' 1907 ഡിസംബറിൽ മൂർക്കോത്ത് കുമാരന്റെ 'മിതവാദി'യിൽ പ്രസിദ്ധീകരിച്ചു. 1922-ൽ മദ്രാസ് സർവകലാശാല ആശാന് 'മഹാകവി' പട്ടം നൽകി. 1924-ൽ പല്ലനയാറ്റിലെ ബോട്ടപകടത്തിൽ (റെഡീമർ) അന്തരിച്ചു.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Kumaran_Asan"}],
 [{"topic": "ജീവശാസ്ത്രവും ആരോഗ്യവും", "title": "ഡെങ്കിപ്പനി: വൈറസും ഈഡിസ് കൊതുകും", "body": "ഡെങ്കിപ്പനി കൊതുകുകളിൽനിന്ന് മനുഷ്യരിലേക്ക് പകരുന്ന വൈറസ് രോഗമാണ്. ഈഡിസ് ഈജിപ്റ്റി കൊതുകാണ് പ്രധാന രോഗവാഹകർ; ഈഡിസ് ആൽബോപിക്റ്റസും രോഗം പരത്തുന്നു.", "source": "WHO", "url": "https://www.who.int/news-room/fact-sheets/detail/dengue-and-severe-dengue"},
  {"topic": "ജീവശാസ്ത്രവും ആരോഗ്യവും", "title": "കോളറ: വിബ്രിയോ കോളറേ ബാക്ടീരിയ", "body": "മലിനമായ ഭക്ഷണത്തിലൂടെയും ജലത്തിലൂടെയും പകരുന്ന, കടുത്ത വയറിളക്കമുണ്ടാക്കുന്ന ബാക്ടീരിയ രോഗമാണ് കോളറ; കാരണം വിബ്രിയോ കോളറേ. മിക്ക രോഗികൾക്കും ഒ.ആർ.എസ്. (ORS) ലായനി മതിയായ ചികിത്സയാണ്.", "source": "WHO", "url": "https://www.who.int/news-room/fact-sheets/detail/cholera"},
  {"topic": "ജീവശാസ്ത്രവും ആരോഗ്യവും", "title": "നിപ: കേരളത്തിൽ ആദ്യം 2018-ൽ", "body": "പഴംതീനി വവ്വാലുകൾ (ടെറോപോഡിഡേ കുടുംബം) സ്വാഭാവിക വാഹകരായ, ജന്തുക്കളിൽനിന്ന് പകരുന്ന (സൂണോട്ടിക്) വൈറസ് രോഗമാണ് നിപ. കേരളത്തിലെ ആദ്യ നിപ രോഗബാധ 2018 മേയിൽ കോഴിക്കോട്-മലപ്പുറം ജില്ലകളിലായിരുന്നു; 17 പേർ മരിച്ചു.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/2018_Nipah_virus_outbreak_in_Kerala"},
  {"topic": "ജീവശാസ്ത്രവും ആരോഗ്യവും", "title": "എഡ്വേർഡ് ജെന്നർ: ആദ്യ വാക്സിൻ", "body": "1796 മേയ് 14-ന് ഇംഗ്ലീഷ് ഡോക്ടർ എഡ്വേർഡ് ജെന്നർ ഗോവസൂരി (കൗപോക്സ്) കുരുവിലെ ദ്രവം ജെയിംസ് ഫിപ്സ് എന്ന ബാലനിൽ കുത്തിവച്ച് വസൂരിക്കെതിരായ ലോകത്തിലെ ആദ്യ വാക്സിൻ വികസിപ്പിച്ചു. 'പ്രതിരോധശാസ്ത്രത്തിന്റെ പിതാവ്' എന്നറിയപ്പെടുന്നു.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Edward_Jenner"},
  {"topic": "ജീവശാസ്ത്രവും ആരോഗ്യവും", "title": "ലൂയി പാസ്ചർ: പേവിഷ വാക്സിൻ", "body": "ഫ്രഞ്ച് ശാസ്ത്രജ്ഞൻ ലൂയി പാസ്ചറുടെ ലബോറട്ടറി 1885 ജൂലൈ 6-ന് ജോസഫ് മീസ്റ്റർ എന്ന ബാലന് പേവിഷബാധ (റാബീസ്) വാക്സിൻ നൽകി. ദ്രാവകങ്ങൾ ചൂടാക്കി അണുക്കളെ നശിപ്പിക്കുന്ന 'പാസ്ചറൈസേഷൻ' അദ്ദേഹത്തിന്റെ പേരിലാണ്.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Louis_Pasteur"},
  {"topic": "ജീവശാസ്ത്രവും ആരോഗ്യവും", "title": "പോളിയോ വാക്സിൻ: സാൽക്കും സാബിനും", "body": "ജൊനാസ് സാൽക്ക് വികസിപ്പിച്ച നിർജ്ജീവ പോളിയോ വാക്സിൻ (IPV) കുത്തിവയ്പായി നൽകുന്നു; 1955-ൽ ഇതിന് അംഗീകാരം ലഭിച്ചു. ആൽബർട്ട് സാബിന്റെ വായിലൂടെ നൽകുന്ന തുള്ളിമരുന്ന് (OPV) 1961-ൽ ഉപയോഗത്തിൽ വന്നു.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Polio_vaccine"},
  {"topic": "ജീവശാസ്ത്രവും ആരോഗ്യവും", "title": "ഓക്സിൻ: ആദ്യം കണ്ടെത്തിയ സസ്യഹോർമോൺ", "body": "ആദ്യം കണ്ടെത്തിയ പ്രധാന സസ്യഹോർമോണാണ് ഓക്സിൻ; ഇൻഡോൾ-3-അസറ്റിക് ആസിഡ് (IAA) ആണ് പ്രധാന ഓക്സിൻ. ഓക്സിന്റെ അസമവിതരണം കാരണമാണ് തണ്ട് പ്രകാശത്തിലേക്ക് വളയുന്നതും (പ്രകാശാനുവർത്തനം) വേരുകൾ ഗുരുത്വാകർഷണത്തോട് പ്രതികരിക്കുന്നതും.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Auxin"},
  {"topic": "ജീവശാസ്ത്രവും ആരോഗ്യവും", "title": "ലോകാരോഗ്യ സംഘടന: 1948 ഏപ്രിൽ 7", "body": "ലോകാരോഗ്യ സംഘടന (WHO) നിലവിൽ വന്നത് 1948 ഏപ്രിൽ 7-നാണ്; അതിന്റെ സ്മരണയ്ക്കായി ഏപ്രിൽ 7 ലോകാരോഗ്യദിനമായി ആചരിക്കുന്നു. സ്വിറ്റ്സർലൻഡിലെ ജനീവയാണ് ആസ്ഥാനം.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/World_Health_Organization"},
  {"topic": "ജീവശാസ്ത്രവും ആരോഗ്യവും", "title": "ദേശീയ ആരോഗ്യ ദൗത്യം (NHM): 2013", "body": "2005 ഏപ്രിൽ 12-ന് ദേശീയ ഗ്രാമീണ ആരോഗ്യ ദൗത്യം (NRHM) ആരംഭിച്ചു. 2013-ൽ NRHM-ഉം ദേശീയ നഗര ആരോഗ്യ ദൗത്യവും (NUHM) ഉൾപ്പെടുത്തി ദേശീയ ആരോഗ്യ ദൗത്യം (NHM) രൂപീകരിച്ചു. ഗ്രാമങ്ങളിലെ ആശാ (ASHA) പ്രവർത്തകർ ഇതിന്റെ ഭാഗമാണ്.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/National_Health_Mission"},
  {"topic": "ജീവശാസ്ത്രവും ആരോഗ്യവും", "title": "DNA ഇരട്ടപ്പിരിയൻ ഘടന: വാട്സണും ക്രിക്കും", "body": "DNA-യുടെ ഇരട്ടപ്പിരിയൻ (ഡബിൾ ഹെലിക്സ്) മാതൃക 1953-ൽ 'നേച്ചർ' മാസികയിൽ പ്രസിദ്ധീകരിച്ചത് ജെയിംസ് വാട്സണും ഫ്രാൻസിസ് ക്രിക്കുമാണ്. റോസലിൻഡ് ഫ്രാങ്ക്ലിന്റെ 'ഫോട്ടോ 51' നിർണായകമായി; 1962-ൽ വാട്സൺ, ക്രിക്ക്, മോറിസ് വിൽക്കിൻസ് എന്നിവർക്ക് നൊബേൽ ലഭിച്ചു.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Nucleic_acid_double_helix"}],
 [{"topic": "ഇന്ത്യൻ ഭരണഘടന", "title": "ദേശീയ മനുഷ്യാവകാശ കമ്മീഷൻ: 1993", "body": "1993-ലെ മനുഷ്യാവകാശ സംരക്ഷണ നിയമപ്രകാരമുള്ള സ്റ്റാറ്റ്യൂട്ടറി സ്ഥാപനമായ ദേശീയ മനുഷ്യാവകാശ കമ്മീഷൻ (NHRC) 1993 ഒക്ടോബർ 12-ന് നിലവിൽ വന്നു. ആസ്ഥാനം ന്യൂഡൽഹി; ആദ്യ അധ്യക്ഷൻ ജസ്റ്റിസ് രംഗനാഥ് മിശ്ര.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/National_Human_Rights_Commission_of_India"},
  {"topic": "ഇന്ത്യൻ ഭരണഘടന", "title": "കേന്ദ്ര വിജിലൻസ് കമ്മീഷൻ: 1964", "body": "കെ. സന്താനം അധ്യക്ഷനായ അഴിമതി നിരോധന സമിതിയുടെ ശുപാർശപ്രകാരം 1964 ഫെബ്രുവരി 11-ന് കേന്ദ്ര വിജിലൻസ് കമ്മീഷൻ (CVC) രൂപീകരിച്ചു. 2003-ലെ CVC നിയമം ഇതിന് സ്റ്റാറ്റ്യൂട്ടറി പദവി നൽകി; ആദ്യ CVC എൻ. ശ്രീനിവാസ റാവു.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Central_Vigilance_Commission"},
  {"topic": "ഇന്ത്യൻ ഭരണഘടന", "title": "വിവരാവകാശ നിയമം: 2005", "body": "വിവരാവകാശ നിയമം 2005 ജൂൺ 15-ന് പാർലമെന്റ് പാസാക്കി; 2005 ഒക്ടോബർ 12-ന് പൂർണമായി പ്രാബല്യത്തിൽ വന്നു. സാധാരണ 30 ദിവസത്തിനകം മറുപടി നൽകണം; വ്യക്തിയുടെ ജീവനോ സ്വാതന്ത്ര്യമോ ഉൾപ്പെട്ടാൽ 48 മണിക്കൂറിനകം.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Right_to_Information_Act,_2005"},
  {"topic": "ഇന്ത്യൻ ഭരണഘടന", "title": "ലക്ഷ്യപ്രമേയം: നെഹ്റു, 1946 ഡിസംബർ 13", "body": "1946 ഡിസംബർ 13-ന് ജവഹർലാൽ നെഹ്റു നിർമാണസഭയിൽ ലക്ഷ്യപ്രമേയം (Objectives Resolution) അവതരിപ്പിച്ചു. 1947 ജനുവരി 22-ന് സഭ അത് ഏകകണ്ഠമായി അംഗീകരിച്ചു; ഈ പ്രമേയമാണ് പിന്നീട് ഭരണഘടനയുടെ ആമുഖമായി മാറിയത്.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Constituent_Assembly_of_India"},
  {"topic": "ഇന്ത്യൻ ഭരണഘടന", "title": "എട്ടാം പട്ടിക: 22 ഭാഷകൾ", "body": "എട്ടാം പട്ടികയിൽ തുടക്കത്തിൽ 14 ഭാഷകളായിരുന്നു; ഇപ്പോൾ 22. 1967-ൽ 21-ാം ഭേദഗതി സിന്ധി ചേർത്തു; 1992-ൽ 71-ാം ഭേദഗതി കൊങ്കണി, മണിപ്പൂരി, നേപ്പാളി; 2003-ൽ 92-ാം ഭേദഗതി ബോഡോ, ഡോഗ്രി, മൈഥിലി, സന്താലി എന്നിവ ചേർത്തു.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Eighth_Schedule_to_the_Constitution_of_India"},
  {"topic": "ഇന്ത്യൻ ഭരണഘടന", "title": "ഒന്നാം ഭേദഗതി (1951): ഒൻപതാം പട്ടിക", "body": "1951-ലെ ഒന്നാം ഭരണഘടനാ ഭേദഗതിയാണ് ഒൻപതാം പട്ടിക കൂട്ടിച്ചേർത്തത്; ഇതിൽ ഉൾപ്പെടുത്തുന്ന നിയമങ്ങളെ കോടതിയിലെ വെല്ലുവിളിയിൽനിന്ന് സംരക്ഷിക്കാനായിരുന്നു ലക്ഷ്യം. പിന്നാക്ക വിഭാഗങ്ങൾക്കും പട്ടികജാതി-വർഗങ്ങൾക്കും പ്രത്യേക വ്യവസ്ഥകളും ഇത് ചേർത്തു.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/List_of_amendments_of_the_Constitution_of_India"},
  {"topic": "ഇന്ത്യൻ ഭരണഘടന", "title": "അനുച്ഛേദം 21A: വിദ്യാഭ്യാസ അവകാശം", "body": "2002-ലെ 86-ാം ഭേദഗതി അനുച്ഛേദം 21A ചേർത്തു; 6 മുതൽ 14 വയസ്സുവരെയുള്ള കുട്ടികൾക്ക് സൗജന്യവും നിർബന്ധിതവുമായ വിദ്യാഭ്യാസം മൗലികാവകാശമായി. 86-ാം ഭേദഗതി 2002 ഡിസംബർ 12-ന് പ്രാബല്യത്തിൽ വന്നു.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/List_of_amendments_of_the_Constitution_of_India"},
  {"topic": "ഇന്ത്യൻ ഭരണഘടന", "title": "അറ്റോർണി ജനറൽ: അനുച്ഛേദം 76", "body": "കേന്ദ്രസർക്കാരിന്റെ മുഖ്യ നിയമോപദേഷ്ടാവായ അറ്റോർണി ജനറലിനെ അനുച്ഛേദം 76 പ്രകാരം രാഷ്ട്രപതി നിയമിക്കുന്നു; സുപ്രീം കോടതി ജഡ്ജിയാകാനുള്ള യോഗ്യത വേണം. പാർലമെന്റ് നടപടികളിൽ പങ്കെടുക്കാം, വോട്ടവകാശമില്ല. ആദ്യ അറ്റോർണി ജനറൽ എം.സി. സെതൽവാദ്.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Attorney_General_for_India"},
  {"topic": "ഇന്ത്യൻ ഭരണഘടന", "title": "അഡ്വക്കേറ്റ് ജനറൽ: അനുച്ഛേദം 165", "body": "സംസ്ഥാന സർക്കാരിന്റെ നിയമോപദേഷ്ടാവായ അഡ്വക്കേറ്റ് ജനറലിന്റെ പദവി അനുച്ഛേദം 165 പ്രകാരമാണ്. ഹൈക്കോടതി ജഡ്ജിയാകാൻ യോഗ്യതയുള്ളയാളെ ഗവർണർ നിയമിക്കുന്നു; കേന്ദ്രത്തിലെ അറ്റോർണി ജനറലിന് തുല്യമായ സംസ്ഥാന പദവിയാണിത്.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Advocate_general_(India)"},
  {"topic": "ഇന്ത്യൻ ഭരണഘടന", "title": "ഹൈക്കോടതികൾ: അനുച്ഛേദം 214", "body": "‘ഓരോ സംസ്ഥാനത്തിനും ഒരു ഹൈക്കോടതി ഉണ്ടായിരിക്കും’ എന്ന് അനുച്ഛേദം 214 പറയുന്നു. ഹൈക്കോടതികളെക്കുറിച്ചുള്ള അധ്യായം അനുച്ഛേദം 214 മുതൽ 231 വരെയാണ്; രണ്ടോ അതിലധികമോ സംസ്ഥാനങ്ങൾക്ക് പൊതു ഹൈക്കോടതി അനുവദിക്കുന്നത് അനുച്ഛേദം 231.", "source": "constitutionofindia.net", "url": "https://www.constitutionofindia.net/articles/article-214-high-courts-for-states/"}],
 [{"topic": "ആനുകാലികം", "title": "60-ാം ജ്ഞാനപീഠം: വൈരമുത്തു", "body": "2025-ലെ 60-ാമത് ജ്ഞാനപീഠ പുരസ്കാരം തമിഴ് കവിയും ഗാനരചയിതാവുമായ ആർ. വൈരമുത്തുവിന്; 2026 മാർച്ച് 14-ന് പ്രഖ്യാപിച്ചു. അഖിലൻ (1975), ജയകാന്തൻ (2002) എന്നിവർക്കുശേഷം ജ്ഞാനപീഠം നേടുന്ന മൂന്നാമത്തെ തമിഴ് എഴുത്തുകാരൻ.", "source": "The Tribune", "url": "https://www.tribuneindia.com/news/india/tamil-poet-vairamuthu-wins-60th-jnanpith-award/"},
  {"topic": "ആനുകാലികം", "title": "2024-ൽ അഞ്ചുപേർക്ക് ഭാരതരത്നം", "body": "2024-ൽ അഞ്ചുപേർക്ക് ഭാരതരത്നം സമ്മാനിച്ചു: എൽ.കെ. അദ്വാനി, കർപ്പൂരി ഠാക്കൂർ, ചരൺ സിങ്, പി.വി. നരസിംഹ റാവു, എം.എസ്. സ്വാമിനാഥൻ (അദ്വാനി ഒഴികെയുള്ളവർക്ക് മരണാനന്തരം). ഇതോടെ ആകെ ജേതാക്കൾ 53.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/List_of_Bharat_Ratna_recipients"},
  {"topic": "ആനുകാലികം", "title": "എം.ടി.ക്ക് മരണാനന്തര പത്മവിഭൂഷൺ", "body": "2024 ഡിസംബർ 25-ന് അന്തരിച്ച എം.ടി. വാസുദേവൻ നായർക്ക് 2025-ൽ മരണാനന്തര ബഹുമതിയായി പത്മവിഭൂഷൺ ലഭിച്ചു. 1995-ൽ ജ്ഞാനപീഠം നേടിയ അദ്ദേഹം മലയാളത്തിന്റെ പ്രമുഖ കഥാകാരനും തിരക്കഥാകൃത്തുമായിരുന്നു.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/M._T._Vasudevan_Nair"},
  {"topic": "ആനുകാലികം", "title": "2026 എഴുത്തച്ഛൻ പുരസ്കാരം: മേതിൽ", "body": "കേരള സർക്കാരിന്റെ പരമോന്നത സാഹിത്യ ബഹുമതിയായ എഴുത്തച്ഛൻ പുരസ്കാരം (₹5 ലക്ഷം) 2026-ൽ മേതിൽ രാധാകൃഷ്ണന്; 2026 നവംബർ 1-ന് പ്രഖ്യാപിച്ചു. 2025-ൽ കെ.ജി. ശങ്കരപ്പിള്ളയ്ക്കും 2024-ൽ എൻ.എസ്. മാധവനുമായിരുന്നു പുരസ്കാരം.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Ezhuthachan_Puraskaram"},
  {"topic": "ആനുകാലികം", "title": "മോഹൻലാലിന് ദാദാസാഹേബ് ഫാൽക്കെ പുരസ്കാരം", "body": "ഇന്ത്യൻ സിനിമയിലെ പരമോന്നത ബഹുമതിയായ ദാദാസാഹേബ് ഫാൽക്കെ പുരസ്കാരം മോഹൻലാലിന്. 2025 സെപ്റ്റംബർ 23-ന് ന്യൂഡൽഹി വിജ്ഞാൻ ഭവനിൽ നടന്ന 71-ാം ദേശീയ ചലച്ചിത്ര പുരസ്കാര ചടങ്ങിൽ രാഷ്ട്രപതി ദ്രൗപദി മുർമു സമ്മാനിച്ചു.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/71st_National_Film_Awards"},
  {"topic": "ആനുകാലികം", "title": "സംസ്ഥാന ചലച്ചിത്ര പുരസ്കാരം: മമ്മൂട്ടി", "body": "55-ാമത് കേരള സംസ്ഥാന ചലച്ചിത്ര പുരസ്കാരങ്ങൾ (2024-ലെ സിനിമകൾ) 2025 നവംബർ 3-ന് തൃശൂരിൽ പ്രഖ്യാപിച്ചു. 'ഭ്രമയുഗ'ത്തിന് മമ്മൂട്ടി മികച്ച നടൻ; ഷംല ഹംസ ('ഫെമിനിച്ചി ഫാത്തിമ') മികച്ച നടി; മികച്ച ചിത്രം 'മഞ്ഞുമ്മൽ ബോയ്സ്'.", "source": "The News Minute", "url": "https://www.thenewsminute.com/flix/kerala-film-awards-manjummel-boys-sweeps-mammootty-shamla-hamza-are-best-actors"},
  {"topic": "ആനുകാലികം", "title": "ബാനു മുഷ്താഖ്: ഇന്റർനാഷണൽ ബുക്കർ", "body": "കന്നഡ എഴുത്തുകാരി ബാനു മുഷ്താഖിന്റെ ചെറുകഥാസമാഹാരം 'ഹാർട്ട് ലാമ്പ്' 2025 മേയിൽ ഇന്റർനാഷണൽ ബുക്കർ പുരസ്കാരം നേടി; വിവർത്തനം ദീപ ഭസ്തി. ഈ പുരസ്കാരം നേടുന്ന ആദ്യ കന്നഡ കൃതിയും ആദ്യ ചെറുകഥാസമാഹാരവും.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Heart_Lamp"},
  {"topic": "ആനുകാലികം", "title": "ലിയോ പതിനാലാമൻ: ആദ്യ അമേരിക്കൻ മാർപാപ്പ", "body": "ഫ്രാൻസിസ് മാർപാപ്പയുടെ പിൻഗാമിയായി 2025 മേയ് 8-ന് കർദിനാൾ റോബർട്ട് ഫ്രാൻസിസ് പ്രെവോസ്റ്റ് 'ലിയോ പതിനാലാമൻ' എന്ന പേരിൽ മാർപാപ്പയായി. യു.എസിൽനിന്നുള്ള ആദ്യ മാർപാപ്പ; അഗസ്റ്റീനിയൻ സഭയിൽനിന്നുള്ള ആദ്യത്തെയാളും.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Pope_Leo_XIV"}],
 [{"topic": "സാമ്പത്തികശാസ്ത്രം", "title": "കിഫ്ബി (KIIFB): 1999", "body": "കേരളത്തിലെ വൻകിട അടിസ്ഥാനസൗകര്യ പദ്ധതികൾക്ക് ധനസഹായം നൽകുന്ന KIIFB 1999 നവംബർ 11-ന് Kerala Infrastructure Investment Fund Act 1999 പ്രകാരം സ്ഥാപിച്ചു. 2016-ലെ ഭേദഗതി നിയമം ഇതിന്റെ പ്രവർത്തനം വിപുലമാക്കി; മുഖ്യമന്ത്രിയാണ് ചെയർപേഴ്സൺ.", "source": "KIIFB", "url": "https://kiifb.org/"}],
 [{"topic": "കേരള ചരിത്രം", "title": "മലയാളി മെമ്മോറിയൽ: 1891", "body": "1891 ജനുവരി 1-ന് 10,028 പേർ ഒപ്പിട്ട മലയാളി മെമ്മോറിയൽ തിരുവിതാംകൂർ സർക്കാരിന് സമർപ്പിച്ചു. ഉന്നത ഉദ്യോഗങ്ങളിൽ നാട്ടുകാർക്ക് ജാതിമതഭേദമില്ലാതെ മുൻഗണന വേണമെന്നായിരുന്നു ആവശ്യം; നേതൃത്വം ബാരിസ്റ്റർ ജി.പി. പിള്ള.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Malayali_Memorial"},
  {"topic": "കേരള ചരിത്രം", "title": "ഈഴവ മെമ്മോറിയൽ: 1896, ഡോ. പല്പു", "body": "ഡോ. പല്പുവിന്റെ നേതൃത്വത്തിൽ 13,176 പേർ ഒപ്പിട്ട ഈഴവ മെമ്മോറിയൽ 1896 സെപ്റ്റംബർ 3-ന് ശ്രീമൂലം തിരുനാൾ മഹാരാജാവിന് സമർപ്പിച്ചു. ഈഴവർക്ക് സർക്കാർ ജോലിയും വിദ്യാഭ്യാസ അവകാശങ്ങളും ആയിരുന്നു ആവശ്യം.", "source": "Kerala Tourism", "url": "https://www.keralatourism.org/sreenarayanaguru/disciples/householders/dr-palpu"}],
 [{"topic": "കേരള ഭരണസംവിധാനം", "title": "വയനാട് ജില്ല: 1980 നവംബർ 1", "body": "വയനാട് ജില്ല 1980 നവംബർ 1-ന്, കേരളപ്പിറവി ദിനത്തിൽ, രൂപീകരിച്ചു; കേരളത്തിലെ 12-ാമത്തെ ജില്ല. 1972-ലെ ഇടുക്കിക്ക് ശേഷം എട്ട് വർഷം കഴിഞ്ഞാണ് പുതിയൊരു ജില്ല നിലവിൽ വന്നത്.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/List_of_districts_of_Kerala"},
  {"topic": "കേരള ഭരണസംവിധാനം", "title": "പത്തനംതിട്ട ജില്ല: 1982 നവംബർ 1", "body": "പത്തനംതിട്ട ജില്ല 1982 നവംബർ 1-ന് നിലവിൽ വന്നു; കേരളത്തിലെ 13-ാമത്തെ ജില്ല. വയനാടിനെപ്പോലെ (1980) കേരളപ്പിറവി ദിനത്തിലാണ് പത്തനംതിട്ടയുടെയും രൂപീകരണം.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/List_of_districts_of_Kerala"},
  {"topic": "കേരള ഭരണസംവിധാനം", "title": "ഒന്നാം നിയമസഭ: 1957 ഏപ്രിൽ 1", "body": "ഒന്നാം കേരള നിയമസഭ 1957 ഏപ്രിൽ 1-ന് രൂപീകൃതമായി; ആദ്യ സമ്മേളനം 1957 ഏപ്രിൽ 27-ന് ചേർന്നു. 1959 ജൂലൈ 31-ന് സഭ പിരിച്ചുവിടപ്പെട്ടു.", "source": "കേരള നിയമസഭ", "url": "https://www.niyamasabha.org/codes/ginfo_11.htm"},
  {"topic": "കേരള ഭരണസംവിധാനം", "title": "ആദ്യ സ്പീക്കർ: ആർ. ശങ്കരനാരായണൻ തമ്പി", "body": "കേരള നിയമസഭയുടെ ആദ്യ സ്പീക്കർ ആർ. ശങ്കരനാരായണൻ തമ്പിയാണ് (1957 ഏപ്രിൽ 27 – 1959 ജൂലൈ 31). രണ്ടാമത്തെ സ്പീക്കർ കെ.എം. സീതി സാഹിബ് (1960).", "source": "കേരള നിയമസഭ", "url": "https://www.niyamasabha.org/codes/ginfo_7.htm"},
  {"topic": "കേരള ഭരണസംവിധാനം", "title": "ആദ്യ ഡെപ്യൂട്ടി സ്പീക്കർ: കെ.ഒ. ഐഷാ ബായി", "body": "കേരള നിയമസഭയുടെ ആദ്യ ഡെപ്യൂട്ടി സ്പീക്കർ കെ.ഒ. ഐഷാ ബായിയാണ് (1957 മേയ് 6 – 1959 ജൂലൈ 31). രണ്ടാമത്തെ ഡെപ്യൂട്ടി സ്പീക്കറും വനിതയായിരുന്നു – എ. നബീസത്ത് ബീവി.", "source": "കേരള നിയമസഭ", "url": "https://www.niyamasabha.org/codes/dyspeakers.htm"},
  {"topic": "കേരള ഭരണസംവിധാനം", "title": "റോസമ്മ പുന്നൂസ്: ആദ്യ പ്രോടേം സ്പീക്കർ", "body": "കേരള നിയമസഭയുടെ ആദ്യ പ്രോടേം സ്പീക്കർ റോസമ്മ പുന്നൂസാണ്; നിയമസഭാംഗമായി ആദ്യം സത്യപ്രതിജ്ഞ ചെയ്തതും അവരാണ്. 1958-ൽ നിയമസഭയിലേക്കുള്ള ആദ്യ ഉപതിരഞ്ഞെടുപ്പിൽ ജയിച്ചതും റോസമ്മ പുന്നൂസ് തന്നെ.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Rosamma_Punnoose"},
  {"topic": "കേരള ഭരണസംവിധാനം", "title": "കെ.ആർ. ഗൗരി: കാർഷിക ബന്ധ ബിൽ (1957)", "body": "ആദ്യ ഇ.എം.എസ്. മന്ത്രിസഭയിലെ റവന്യൂ മന്ത്രി കെ.ആർ. ഗൗരി 1957 ഡിസംബറിൽ കാർഷിക ബന്ധ ബിൽ അവതരിപ്പിച്ചു. കുടിയായ്മ അവസാനിപ്പിക്കൽ, ഭൂപരിധി, ലാൻഡ് ട്രിബ്യൂണലുകൾ എന്നിവ ലക്ഷ്യമിട്ട ബിൽ 1959 ജൂണിൽ പാസായെങ്കിലും രാഷ്ട്രപതി അനുമതി നൽകിയില്ല.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/K._R._Gouri_Amma"},
  {"topic": "കേരള ഭരണസംവിധാനം", "title": "ആദ്യ പ്രതിപക്ഷ നേതാവ്: പി.ടി. ചാക്കോ", "body": "ഒന്നാം കേരള നിയമസഭയിൽ (1957) പ്രതിപക്ഷ നേതാവ് കോൺഗ്രസിലെ പി.ടി. ചാക്കോയായിരുന്നു. 1957-ലെ ആദ്യ നിയമസഭയിൽ ഒരു നാമനിർദേശ അംഗം ഉൾപ്പെടെ 127 അംഗങ്ങളാണ് ഉണ്ടായിരുന്നത്.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Kerala_Legislative_Assembly"},
  {"topic": "കേരള ഭരണസംവിധാനം", "title": "ആദ്യ രാഷ്ട്രപതി ഭരണം: 1959 ജൂലൈ 31", "body": "1959 ജൂലൈ 31-ന് ഇ.എം.എസ്. സർക്കാരിനെ പിരിച്ചുവിട്ട് കേരളത്തിൽ രാഷ്ട്രപതി ഭരണം ഏർപ്പെടുത്തി; 1960 ഫെബ്രുവരി 22 വരെ തുടർന്നു. കേരളത്തിലെ ആദ്യ നിയമസഭ കാലാവധി തികയ്ക്കാതെ പിരിഞ്ഞത് ഇങ്ങനെയാണ്.", "source": "കേരള നിയമസഭ", "url": "https://www.niyamasabha.org/codes/ginfo_10.htm"},
  {"topic": "കേരള ഭരണസംവിധാനം", "title": "കെ. കരുണാകരൻ: ഏറ്റവും കുറഞ്ഞ കാലാവധി", "body": "1977 മാർച്ച് 25 മുതൽ ഏപ്രിൽ 27 വരെ 33 ദിവസം മാത്രം മുഖ്യമന്ത്രിയായിരുന്ന കെ. കരുണാകരന്റേതാണ് ഏറ്റവും ചുരുങ്ങിയ കാലാവധി. 1979-ൽ 53 ദിവസം ഭരിച്ച സി.എച്ച്. മുഹമ്മദ് കോയയാണ് രണ്ടാമത്.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/List_of_chief_ministers_of_Kerala"}],
 [{"topic": "കല, സാഹിത്യം, കായികം", "title": "കേരള കലാമണ്ഡലം: വള്ളത്തോൾ, 1930", "body": "മഹാകവി വള്ളത്തോൾ നാരായണമേനോനും മുകുന്ദരാജയും ചേർന്ന് 1930-ൽ കുന്നംകുളത്ത് കലാമണ്ഡലം ആരംഭിച്ചു. 1936-ൽ ഭാരതപ്പുഴയോരത്തെ ചെറുതുരുത്തിയിലേക്ക് മാറി. 2006-ൽ കല്പിത സർവകലാശാല പദവി ലഭിച്ചു.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Kerala_Kalamandalam"},
  {"topic": "കല, സാഹിത്യം, കായികം", "title": "കൂടിയാട്ടം: യുനെസ്കോ അംഗീകാരം 2001", "body": "സംസ്കൃത നാടകവേദിയുടെ ഇന്നും നിലനിൽക്കുന്ന ഏക കലാരൂപമായ കൂടിയാട്ടത്തെ 2001-ൽ യുനെസ്കോ 'മാനവരാശിയുടെ വാമൊഴി-അദൃശ്യ പൈതൃകത്തിന്റെ മാസ്റ്റർപീസ്' ആയി പ്രഖ്യാപിച്ചു. ക്ഷേത്രങ്ങളിലെ കൂത്തമ്പലങ്ങളിലാണ് അവതരണം.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Koodiyattam"},
  {"topic": "കല, സാഹിത്യം, കായികം", "title": "വിഗതകുമാരൻ: ആദ്യ മലയാള സിനിമ", "body": "ജെ.സി. ഡാനിയൽ രചനയും നിർമ്മാണവും സംവിധാനവും നിർവഹിച്ച് നായകനായി അഭിനയിച്ച 'വിഗതകുമാരൻ' (1928) ആദ്യ മലയാള ചലച്ചിത്രമാണ് (നിശ്ശബ്ദ സിനിമ). നായിക പി.കെ. റോസി. ഡാനിയൽ മലയാള സിനിമയുടെ പിതാവ്.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Vigathakumaran"},
  {"topic": "കല, സാഹിത്യം, കായികം", "title": "ജെ.സി. ഡാനിയൽ പുരസ്കാരം: 1992", "body": "മലയാള സിനിമയ്ക്കുള്ള സമഗ്ര സംഭാവനയ്ക്ക് കേരള സർക്കാർ നൽകുന്ന പരമോന്നത ചലച്ചിത്ര ബഹുമതിയാണ് ജെ.സി. ഡാനിയൽ പുരസ്കാരം. 1992-ൽ ആരംഭിച്ചു; ആദ്യ ജേതാവ് നിർമ്മാതാവ് ടി.ഇ. വാസുദേവൻ.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/J._C._Daniel_Award"},
  {"topic": "കല, സാഹിത്യം, കായികം", "title": "പി.ടി. ഉഷ: 1984-ലെ ഒളിമ്പിക് ഫൈനൽ", "body": "1984 ലോസ് ആഞ്ചലസ് ഒളിമ്പിക്സിലെ 400 മീ. ഹർഡിൽസ് ഫൈനലിൽ പി.ടി. ഉഷ 55.42 സെക്കൻഡിൽ നാലാമതെത്തി; വെങ്കലം നഷ്ടമായത് സെക്കൻഡിന്റെ നൂറിലൊന്ന് വ്യത്യാസത്തിൽ. 'പയ്യോളി എക്സ്പ്രസ്', 'ഗോൾഡൻ ഗേൾ' എന്നറിയപ്പെടുന്നു.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/P._T._Usha"},
  {"topic": "കല, സാഹിത്യം, കായികം", "title": "അഞ്ജു ബോബി ജോർജ്: 2003 ലോക മെഡൽ", "body": "2003-ൽ പാരീസിലെ ലോക അത്‌ലറ്റിക്സ് ചാമ്പ്യൻഷിപ്പിൽ ലോങ്ജമ്പിൽ വെങ്കലം നേടിയ അഞ്ജു ബോബി ജോർജ്, ലോക ചാമ്പ്യൻഷിപ്പിൽ മെഡൽ നേടിയ ആദ്യ ഇന്ത്യക്കാരിയാണ്. കോട്ടയം ജില്ലയിലെ ചീരഞ്ചിറ സ്വദേശി; 2003-ൽ ഖേൽരത്ന.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Anju_Bobby_George"},
  {"topic": "കല, സാഹിത്യം, കായികം", "title": "കെ.ഡി. ജാദവ്: ആദ്യ വ്യക്തിഗത ഒളിമ്പിക് മെഡൽ", "body": "1952 ഹെൽസിങ്കി ഒളിമ്പിക്സിൽ ഗുസ്തിയിൽ (ഫ്രീസ്റ്റൈൽ ബാന്റംവെയ്റ്റ്) വെങ്കലം നേടിയ ഖശാബ ദാദാസാഹേബ് ജാദവ് സ്വതന്ത്ര ഇന്ത്യയുടെ ആദ്യ വ്യക്തിഗത ഒളിമ്പിക് മെഡൽ ജേതാവാണ്.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Khashaba_Dadasaheb_Jadhav"},
  {"topic": "കല, സാഹിത്യം, കായികം", "title": "അഭിനവ് ബിന്ദ്ര: ആദ്യ വ്യക്തിഗത സ്വർണ്ണം", "body": "2008 ബെയ്ജിങ് ഒളിമ്പിക്സിൽ 10 മീറ്റർ എയർ റൈഫിളിൽ സ്വർണ്ണം നേടിയ അഭിനവ് ബിന്ദ്ര ഒളിമ്പിക്സിൽ വ്യക്തിഗത സ്വർണ്ണം നേടിയ ആദ്യ ഇന്ത്യക്കാരനാണ് (ഷൂട്ടിങ്).", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Abhinav_Bindra"},
  {"topic": "കല, സാഹിത്യം, കായികം", "title": "നീരജ് ചോപ്ര: അത്‌ലറ്റിക്സിലെ ആദ്യ സ്വർണ്ണം", "body": "ടോക്യോ 2020 ഒളിമ്പിക്സിൽ ജാവലിൻ ത്രോയിൽ 87.58 മീറ്റർ എറിഞ്ഞ് സ്വർണ്ണം നേടിയ നീരജ് ചോപ്ര, ഒളിമ്പിക് അത്‌ലറ്റിക്സിൽ സ്വർണ്ണം നേടിയ ആദ്യ ഇന്ത്യക്കാരനാണ്. പാരീസ് 2024-ൽ വെള്ളി നേടി.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Neeraj_Chopra"},
  {"topic": "കല, സാഹിത്യം, കായികം", "title": "സന്തോഷ് ട്രോഫി: കേരളത്തിന്റെ ആദ്യ കിരീടം", "body": "1941-ൽ ആരംഭിച്ച ദേശീയ ഫുട്ബോൾ ചാമ്പ്യൻഷിപ്പായ സന്തോഷ് ട്രോഫി കേരളം ആദ്യമായി നേടിയത് 1973–74-ൽ എറണാകുളത്ത്, ഫൈനലിൽ റെയിൽവേസിനെ 3–2ന് തോൽപ്പിച്ചാണ്. ബംഗാളാണ് ഏറ്റവും കൂടുതൽ കിരീടം നേടിയത്.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Santosh_Trophy"}],
 [{"topic": "ജീവശാസ്ത്രവും ആരോഗ്യവും", "title": "റൊണാൾഡ് റോസ്: കൊതുകും മലമ്പനിയും", "body": "ഉത്തരാഖണ്ഡിലെ അൽമോറയിൽ ജനിച്ച റൊണാൾഡ് റോസ് 1897-ൽ സെക്കന്തരാബാദിൽ വച്ച് കൊതുകിന്റെ ഉദരത്തിൽ മലമ്പനി പരാദത്തെ കണ്ടെത്തി, കൊതുകാണ് രോഗം പകർത്തുന്നതെന്ന് സ്ഥാപിച്ചു. ഇതിന് 1902-ലെ വൈദ്യശാസ്ത്ര നൊബേൽ ലഭിച്ചു.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Ronald_Ross"},
  {"topic": "ജീവശാസ്ത്രവും ആരോഗ്യവും", "title": "ക്ഷയരോഗാണു: റോബർട്ട് കോക്ക്, 1882", "body": "1882 മാർച്ച് 24-ന് റോബർട്ട് കോക്ക് ക്ഷയരോഗത്തിന് കാരണം മൈക്കോബാക്ടീരിയം ട്യൂബർകുലോസിസ് ബാക്ടീരിയയാണെന്ന് പ്രഖ്യാപിച്ചു. ഇതിന്റെ സ്മരണയ്ക്കായി മാർച്ച് 24 ലോക ക്ഷയരോഗദിനമായി ആചരിക്കുന്നു; 1905-ൽ കോക്കിന് നൊബേൽ ലഭിച്ചു.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Robert_Koch"},
  {"topic": "ജീവശാസ്ത്രവും ആരോഗ്യവും", "title": "പെൻസിലിൻ: അലക്സാണ്ടർ ഫ്ലെമിങ്, 1928", "body": "1928 സെപ്റ്റംബറിൽ ലണ്ടനിലെ സെന്റ് മേരീസ് ആശുപത്രിയിൽ സ്കോട്ടിഷ് ശാസ്ത്രജ്ഞൻ അലക്സാണ്ടർ ഫ്ലെമിങ് പെനിസിലിയം എന്ന പൂപ്പലിൽനിന്ന് പെൻസിലിൻ കണ്ടെത്തി. 1945-ലെ നൊബേൽ ഫ്ലെമിങ്, ഫ്ലോറി, ചെയിൻ എന്നിവർ പങ്കിട്ടു.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Penicillin"},
  {"topic": "ജീവശാസ്ത്രവും ആരോഗ്യവും", "title": "വസൂരി നിർമ്മാർജ്ജനം: 1980", "body": "വേരിയോള വൈറസ് മൂലമുള്ള വസൂരി (സ്മോൾപോക്സ്) ലോകത്തുനിന്ന് നിർമ്മാർജ്ജനം ചെയ്തതായി ലോകാരോഗ്യ സംഘടന 1980-ൽ സാക്ഷ്യപ്പെടുത്തി. സ്വാഭാവികമായ അവസാന കേസ് 1977 ഒക്ടോബറിലായിരുന്നു; നിർമ്മാർജ്ജനം ചെയ്യപ്പെട്ട ഏക മനുഷ്യരോഗമാണിത്.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Smallpox"},
  {"topic": "ജീവശാസ്ത്രവും ആരോഗ്യവും", "title": "ഇന്ത്യ പോളിയോമുക്തം: 2014 മാർച്ച് 27", "body": "1995-ൽ പൾസ് പോളിയോ പരിപാടി ആരംഭിച്ച ഇന്ത്യയിൽ അവസാന വൈൽഡ് പോളിയോ കേസ് റിപ്പോർട്ട് ചെയ്തത് 2011 ജനുവരി 13-നാണ്. 2014 മാർച്ച് 27-ന് ലോകാരോഗ്യ സംഘടന ഇന്ത്യയെ പോളിയോമുക്ത രാജ്യമായി പ്രഖ്യാപിച്ചു.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Pulse_Polio"},
  {"topic": "ജീവശാസ്ത്രവും ആരോഗ്യവും", "title": "മിഷൻ ഇന്ദ്രധനുഷ്: 2014 ഡിസംബർ 25", "body": "വാക്സിൻ കൊണ്ട് തടയാവുന്ന രോഗങ്ങൾക്കെതിരെ പ്രതിരോധ കുത്തിവയ്പ് വ്യാപിപ്പിക്കാൻ കേന്ദ്ര ആരോഗ്യ-കുടുംബക്ഷേമ മന്ത്രാലയം 2014 ഡിസംബർ 25-ന് ആരംഭിച്ച ദൗത്യമാണ് മിഷൻ ഇന്ദ്രധനുഷ്; അന്നത്തെ കേന്ദ്ര ആരോഗ്യമന്ത്രി ജെ.പി. നദ്ദയാണ് ഉദ്ഘാടനം ചെയ്തത്.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Mission_Indradhanush"}],
 [{"topic": "ഇന്ത്യൻ ഭരണഘടന", "title": "CAG: അനുച്ഛേദം 148", "body": "കംട്രോളർ ആൻഡ് ഓഡിറ്റർ ജനറൽ (CAG) എന്ന പദവി അനുച്ഛേദം 148 പ്രകാരമാണ്; രാജ്യത്തെ പരമോന്നത ഓഡിറ്റ് സ്ഥാപനമാണിത്. രാഷ്ട്രപതി നിയമിക്കുന്നു; കാലാവധി 6 വർഷം അല്ലെങ്കിൽ 65 വയസ്സ്. ആദ്യ CAG വി. നരഹരി റാവു.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Comptroller_and_Auditor_General_of_India"},
  {"topic": "ഇന്ത്യൻ ഭരണഘടന", "title": "ധനകാര്യ കമ്മീഷൻ: അനുച്ഛേദം 280", "body": "അനുച്ഛേദം 280 പ്രകാരം രാഷ്ട്രപതി അഞ്ചു വർഷം കൂടുമ്പോൾ (ആവശ്യമെങ്കിൽ നേരത്തെ) ധനകാര്യ കമ്മീഷൻ രൂപീകരിക്കുന്നു; ചെയർമാനും 4 അംഗങ്ങളും. ആദ്യ ധനകാര്യ കമ്മീഷൻ 1951-ൽ, ചെയർമാൻ കെ.സി. നിയോഗി. 16-ാം കമ്മീഷൻ (2023) ചെയർമാൻ അരവിന്ദ് പനഗരിയ.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Finance_Commission_of_India"},
  {"topic": "ഇന്ത്യൻ ഭരണഘടന", "title": "UPSC: അനുച്ഛേദം 315", "body": "യൂണിയനും സംസ്ഥാനങ്ങൾക്കും പബ്ലിക് സർവീസ് കമ്മീഷൻ വേണമെന്ന് അനുച്ഛേദം 315 (ഭാഗം XIV) പറയുന്നു. 1926 ഒക്ടോബർ 1-ന് പബ്ലിക് സർവീസ് കമ്മീഷനായി തുടങ്ങിയ UPSC-ക്ക് 1950 ജനുവരി 26-ന് ഭരണഘടനാ പദവി ലഭിച്ചു; ആസ്ഥാനം ഡൽഹിയിലെ ധോൽപൂർ ഹൗസ്.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Union_Public_Service_Commission"},
  {"topic": "ഇന്ത്യൻ ഭരണഘടന", "title": "ഔദ്യോഗിക ഭാഷ: ദേവനാഗരിയിൽ ഹിന്ദി (343)", "body": "അനുച്ഛേദം 343 പ്രകാരം യൂണിയന്റെ ഔദ്യോഗിക ഭാഷ ദേവനാഗരി ലിപിയിലുള്ള ഹിന്ദിയാണ്; അക്കങ്ങൾ ഇന്ത്യൻ അക്കങ്ങളുടെ അന്താരാഷ്ട്ര രൂപം. ഭരണഘടന നിലവിൽ വന്ന് 15 വർഷത്തേക്ക് ഇംഗ്ലീഷും തുടരുമെന്ന് വ്യവസ്ഥ ചെയ്തു; 1949 സെപ്റ്റംബർ 14-ന് നിർമാണസഭ ഇത് അംഗീകരിച്ചു.", "source": "constitutionofindia.net", "url": "https://www.constitutionofindia.net/articles/article-343-official-language-of-the-union/"},
  {"topic": "ഇന്ത്യൻ ഭരണഘടന", "title": "ദേശീയ അടിയന്തരാവസ്ഥ: അനുച്ഛേദം 352", "body": "യുദ്ധം, വിദേശ ആക്രമണം, സായുധ കലാപം എന്നിവയുടെ പേരിലാണ് അനുച്ഛേദം 352 പ്രകാരം ദേശീയ അടിയന്തരാവസ്ഥ. മൂന്നു തവണ പ്രഖ്യാപിച്ചു: 1962 (ചൈന യുദ്ധം), 1971 (പാകിസ്താൻ യുദ്ധം), 1975 (ആഭ്യന്തര കലാപം). ഇരുസഭകളും ഒരു മാസത്തിനകം അംഗീകരിക്കണം.", "source": "ClearIAS", "url": "https://www.clearias.com/emergency-provisions/"},
  {"topic": "ഇന്ത്യൻ ഭരണഘടന", "title": "സാമ്പത്തിക അടിയന്തരാവസ്ഥ: അനുച്ഛേദം 360", "body": "ഇന്ത്യയുടെ സാമ്പത്തിക സ്ഥിരതയോ വായ്പാവിശ്വാസ്യതയോ ഭീഷണിയിലാകുമ്പോൾ അനുച്ഛേദം 360 പ്രകാരം സാമ്പത്തിക അടിയന്തരാവസ്ഥ പ്രഖ്യാപിക്കാം. ഇന്ത്യയിൽ ഇതുവരെ ഒരിക്കലും സാമ്പത്തിക അടിയന്തരാവസ്ഥ പ്രഖ്യാപിച്ചിട്ടില്ല.", "source": "iPleaders", "url": "https://blog.ipleaders.in/emergency-provisions-history-types-duration-india/"},
  {"topic": "ഇന്ത്യൻ ഭരണഘടന", "title": "103-ാം ഭേദഗതി: EWS-ന് 10% സംവരണം", "body": "2019-ലെ 103-ാം ഭേദഗതി സാമ്പത്തികമായി പിന്നാക്കം നിൽക്കുന്ന വിഭാഗങ്ങൾക്ക് (EWS) വിദ്യാഭ്യാസത്തിലും കേന്ദ്രസർക്കാർ ജോലികളിലും 10% വരെ സംവരണം നൽകി. 2019 ജനുവരി 14-ന് പ്രാബല്യത്തിൽ; 2022-ൽ സുപ്രീം കോടതി 3–2 വിധിയിലൂടെ ഇത് ശരിവച്ചു.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/One_Hundred_and_Third_Amendment_of_the_Constitution_of_India"},
  {"topic": "ഇന്ത്യൻ ഭരണഘടന", "title": "106-ാം ഭേദഗതി: വനിതകൾക്ക് മൂന്നിലൊന്ന് സീറ്റ്", "body": "‘നാരീശക്തി വന്ദൻ അധിനിയം’ എന്നറിയപ്പെടുന്ന 106-ാം ഭേദഗതി ലോക്‌സഭയിലും നിയമസഭകളിലും ഡൽഹി നിയമസഭയിലും മൂന്നിലൊന്ന് സീറ്റ് വനിതകൾക്ക് സംവരണം ചെയ്യുന്നു. 2023 സെപ്റ്റംബർ 28-ന് രാഷ്ട്രപതി അംഗീകാരം നൽകി; സെൻസസിനും മണ്ഡലപുനർനിർണയത്തിനും ശേഷമാണ് നടപ്പാക്കൽ.", "source": "Vajiram & Ravi", "url": "https://vajiramandravi.com/upsc-exam/106th-constitutional-amendment-act/"},
  {"topic": "ഇന്ത്യൻ ഭരണഘടന", "title": "കേശവാനന്ദ ഭാരതി കേസ്: അടിസ്ഥാന ഘടന", "body": "1973 ഏപ്രിൽ 24-ലെ കേശവാനന്ദ ഭാരതി കേസിൽ 13 അംഗ ബെഞ്ച് 7–6 ഭൂരിപക്ഷത്തിൽ ‘അടിസ്ഥാന ഘടന’ സിദ്ധാന്തം ആവിഷ്കരിച്ചു: ഭരണഘടനയുടെ അടിസ്ഥാന ഘടന പാർലമെന്റിന് മാറ്റാനാവില്ല. ഹർജിക്കാരൻ കാസർകോട് എടനീർ മഠാധിപതി.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Kesavananda_Bharati_v._State_of_Kerala"},
  {"topic": "ഇന്ത്യൻ ഭരണഘടന", "title": "മേനക ഗാന്ധി കേസ് (1978)", "body": "പാസ്പോർട്ട് പിടിച്ചെടുത്തതിനെതിരായ മേനക ഗാന്ധി കേസിൽ (1978) അനുച്ഛേദം 21-ലെ നടപടിക്രമം ന്യായവും നീതിയുക്തവും യുക്തിസഹവുമാകണമെന്ന് സുപ്രീം കോടതി വിധിച്ചു. അനുച്ഛേദങ്ങൾ 14, 19, 21 ചേർന്ന ‘സുവർണ ത്രികോണം’ എന്ന ആശയം ഇതിൽനിന്നാണ്.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Maneka_Gandhi_v._Union_of_India"}],
 [{"topic": "കേരള ഭരണസംവിധാനം", "title": "നിയമസഭയിൽ 140 മണ്ഡലങ്ങൾ", "body": "കേരളത്തിന്റേത് ഏകമണ്ഡല (unicameral) നിയമസഭയാണ്; നിയമനിർമാണ കൗൺസിൽ ഇല്ല. 140 മണ്ഡലങ്ങളിൽ നിന്ന് തിരഞ്ഞെടുക്കുന്ന 140 അംഗങ്ങൾ. ഇതിൽ 14 എണ്ണം പട്ടികജാതിക്കും 2 എണ്ണം പട്ടികവർഗത്തിനും സംവരണം ചെയ്തിരിക്കുന്നു.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Kerala_Legislative_Assembly"},
  {"topic": "കേരള ഭരണസംവിധാനം", "title": "നിയമസഭാ മന്ദിരം: 1998 മേയ് 22", "body": "തിരുവനന്തപുരം പാളയത്തെ പുതിയ നിയമസഭാ മന്ദിരം 1998 മേയ് 22-ന് രാഷ്ട്രപതി കെ.ആർ. നാരായണൻ ഉദ്ഘാടനം ചെയ്തു. 1979-ൽ രാഷ്ട്രപതി നീലം സഞ്ജീവ റെഡ്ഡിയാണ് തറക്കല്ലിട്ടത്.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Niyamasabha_Mandiram"},
  {"topic": "കേരള ഭരണസംവിധാനം", "title": "ആദ്യ ഗവർണർ: ബി. രാമകൃഷ്ണ റാവു", "body": "ഡോ. ബി. രാമകൃഷ്ണ റാവുവാണ് കേരളത്തിന്റെ ആദ്യ ഗവർണർ (1956 നവംബർ 22 – 1960 ജൂലൈ 1). പിന്നീട് രാഷ്ട്രപതിയായ വി.വി. ഗിരിയായിരുന്നു രണ്ടാമത്തെ ഗവർണർ (1960–65).", "source": "കേരള നിയമസഭ", "url": "https://www.niyamasabha.org/codes/ginfo_4.htm"},
  {"topic": "കേരള ഭരണസംവിധാനം", "title": "കേരള ഹൈക്കോടതി: 1956, കൊച്ചി", "body": "കേരള ഹൈക്കോടതി 1956 നവംബർ 1-ന് സ്ഥാപിതമായി; ആസ്ഥാനം കൊച്ചി (എറണാകുളം). കേരളത്തിനു പുറമേ കേന്ദ്രഭരണ പ്രദേശമായ ലക്ഷദ്വീപും ഇതിന്റെ അധികാരപരിധിയിലാണ്. 1949-ൽ കൊച്ചിയിൽ സ്ഥാപിച്ച തിരു-കൊച്ചി ഹൈക്കോടതിയായിരുന്നു മുൻഗാമി.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Kerala_High_Court"},
  {"topic": "കേരള ഭരണസംവിധാനം", "title": "ഹൈക്കോടതി: ആദ്യ ചീഫ് ജസ്റ്റിസ് കെ.ടി. കോശി", "body": "കേരള ഹൈക്കോടതിയുടെ ആദ്യ ചീഫ് ജസ്റ്റിസ് കെ.ടി. കോശി (കൈതയിൽ തോമസ് കോശി) ആണ്. ഹൈക്കോടതിയുടെ പുതിയ മന്ദിരം 2006 ഫെബ്രുവരി 11-ന് ചീഫ് ജസ്റ്റിസ് വൈ.കെ. സഭർവാൾ ഉദ്ഘാടനം ചെയ്തു.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Kerala_High_Court"},
  {"topic": "കേരള ഭരണസംവിധാനം", "title": "തിരുവിതാംകൂർ പി.എസ്.സി.: 1936", "body": "തിരുവിതാംകൂറിൽ 1936 ജൂൺ 14-ന് ജി.ഡി. നോക്സ് ആദ്യ പബ്ലിക് സർവീസ് കമ്മീഷണറായി നിയമിതനായി. ഇതാണ് കേരള പി.എസ്.സി.യുടെ ആദ്യരൂപം. 1947-ൽ കൊച്ചിയിൽ മൂന്നംഗ പബ്ലിക് സർവീസ് കമ്മീഷനും രൂപീകരിച്ചു.", "source": "Kerala PSC", "url": "https://www.keralapsc.gov.in/history"},
  {"topic": "കേരള ഭരണസംവിധാനം", "title": "കേരള പി.എസ്.സി.: 1956 നവംബർ 1", "body": "1949 ജൂലൈ 1-ന് ഓർഡിനൻസ് വഴി രൂപീകരിച്ച തിരു-കൊച്ചി പബ്ലിക് സർവീസ് കമ്മീഷൻ, 1956 നവംബർ 1-ന് കേരള പബ്ലിക് സർവീസ് കമ്മീഷനായി മാറി. ആസ്ഥാനം തിരുവനന്തപുരം പട്ടത്തെ തുളസി ഹിൽസ്.", "source": "Kerala PSC", "url": "https://www.keralapsc.gov.in/history"},
  {"topic": "കേരള ഭരണസംവിധാനം", "title": "ജനകീയാസൂത്രണം: പദ്ധതി വിഹിതത്തിന്റെ 35–40%", "body": "ജനകീയാസൂത്രണത്തിന്റെ ഭാഗമായി ഒമ്പതാം പദ്ധതി അടങ്കലിന്റെ 35–40 ശതമാനം തദ്ദേശ സ്ഥാപനങ്ങൾ തയ്യാറാക്കുന്ന പദ്ധതികൾക്കായി നീക്കിവെക്കാൻ 1996 ജൂലൈയിൽ എൽ.ഡി.എഫ്. സർക്കാർ തീരുമാനിച്ചു. ഇ.കെ. നായനാരായിരുന്നു അന്നത്തെ മുഖ്യമന്ത്രി.", "source": "The South First", "url": "https://thesouthfirst.com/kerala/peoples-plan-at-30-kerala-youth-to-take-forward-revolution-in-local-governance/"},
  {"topic": "കേരള ഭരണസംവിധാനം", "title": "87 മുനിസിപ്പാലിറ്റികൾ, 6 കോർപ്പറേഷനുകൾ", "body": "നഗര തദ്ദേശ ഭരണത്തിനായി കേരളത്തിൽ 87 മുനിസിപ്പാലിറ്റികളും 6 മുനിസിപ്പൽ കോർപ്പറേഷനുകളുമുണ്ട്. ഗ്രാമങ്ങളിലെ ത്രിതല പഞ്ചായത്തിൽ നിന്ന് വ്യത്യസ്തമായി നഗരങ്ങളിൽ ഏകതല സംവിധാനമാണ്. 2015 ഓടെയാണ് കോർപ്പറേഷനുകളുടെ എണ്ണം 6 ആയത്.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Local_government_in_Kerala"},
  {"topic": "കേരള ഭരണസംവിധാനം", "title": "കുടുംബശ്രീയുടെ ത്രിതല ഘടന", "body": "കുടുംബശ്രീക്ക് ത്രിതല ഘടനയാണ്: അയൽക്കൂട്ടം (NHG), ഏരിയ ഡെവലപ്മെന്റ് സൊസൈറ്റി (ADS), കമ്മ്യൂണിറ്റി ഡെവലപ്മെന്റ് സൊസൈറ്റി (CDS). തദ്ദേശ സ്വയംഭരണ വകുപ്പിന് കീഴിൽ ചാരിറ്റബിൾ സൊസൈറ്റിയായി രജിസ്റ്റർ ചെയ്തിരിക്കുന്നു.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Kudumbashree"}],
 [{"topic": "ഇന്ത്യൻ ഭരണഘടന", "title": "മിനർവ മിൽസ് കേസ് (1980)", "body": "1980 ജൂലൈ 31-ലെ മിനർവ മിൽസ് കേസിൽ 42-ാം ഭേദഗതി അനുച്ഛേദം 368-ൽ ചേർത്ത ഉപവകുപ്പുകൾ (4), (5) സുപ്രീം കോടതി റദ്ദാക്കി. പാർലമെന്റിന്റെ ഭേദഗതി അധികാരം പരിമിതമാണെന്നും അതുതന്നെ അടിസ്ഥാന ഘടനയുടെ ഭാഗമാണെന്നും കോടതി വ്യക്തമാക്കി.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Minerva_Mills_v._Union_of_India"},
  {"topic": "ഇന്ത്യൻ ഭരണഘടന", "title": "ലോക്പാൽ നിയമം: 2013", "body": "ലോക്പാൽ-ലോകായുക്ത നിയമം 2013-ന് 2014 ജനുവരി 1-ന് രാഷ്ട്രപതി അംഗീകാരം നൽകി; 2014 ജനുവരി 16-ന് പ്രാബല്യത്തിൽ. ചെയർപേഴ്സണും പരമാവധി 8 അംഗങ്ങളും; ആദ്യ ലോക്പാൽ ജസ്റ്റിസ് പിനാകി ചന്ദ്ര ഘോഷ് (2019). ‘ലോക്പാൽ’ എന്ന പദം 1963-ൽ എൽ.എം. സിങ്‌വിയുടേത്.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Lokpal_and_Lokayuktas_Act,_2013"}],
 [{"topic": "കേരള ഭരണസംവിധാനം", "title": "കേരള ലോകായുക്ത: 1999-ലെ നിയമം", "body": "കേരള ലോകായുക്ത നിയമം 1999-ലാണ് (രാഷ്ട്രപതിയുടെ അനുമതി 1999 മാർച്ച് 4). പൊതുസേവകർക്കെതിരായ അഴിമതി ആരോപണങ്ങൾ അന്വേഷിക്കുന്നു. ആദ്യ ലോകായുക്ത ജസ്റ്റിസ് പി.സി. ബാലകൃഷ്ണമേനോൻ (1998–2003).", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Kerala_Lokayukta"},
  {"topic": "കേരള ഭരണസംവിധാനം", "title": "നവകേരള മിഷൻ: 2016 നവംബർ 10", "body": "നവകേരള മിഷൻ 2016 നവംബർ 10-ന് ഗവർണർ പി. സദാശിവം തിരുവനന്തപുരത്ത് ഉദ്ഘാടനം ചെയ്തു. ആരോഗ്യം, വിദ്യാഭ്യാസം, കൃഷി, ഭവനം എന്നീ നാല് മേഖലകൾക്കായി ഹരിതകേരളം, ആർദ്രം, ലൈഫ്, പൊതുവിദ്യാഭ്യാസ സംരക്ഷണം എന്നീ നാല് മിഷനുകൾ.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Nava_Kerala_Mission"},
  {"topic": "കേരള ഭരണസംവിധാനം", "title": "ലൈഫ് മിഷൻ: എല്ലാവർക്കും വീട്", "body": "നവകേരള മിഷന്റെ ഭാഗമായ ലൈഫ് (LIFE) മിഷൻ ഭവനരഹിതർക്ക് വീട് ഉറപ്പാക്കുന്ന ഭവന പദ്ധതിയാണ്. ഭൂമിയോ വീടോ ഇല്ലാത്ത ഏകദേശം 4.32 ലക്ഷം കുടുംബങ്ങളെയാണ് ലക്ഷ്യമിട്ടത്.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Nava_Kerala_Mission"},
  {"topic": "കേരള ഭരണസംവിധാനം", "title": "ഹരിതകേരളം മിഷൻ: ശുചിത്വവും കൃഷിയും", "body": "നവകേരള മിഷന്റെ ഭാഗമായ ഹരിതകേരളം മാലിന്യ സംസ്കരണം, ശുചിത്വം, ജലസ്രോതസ്സ് സംരക്ഷണം, ജൈവകൃഷി ഉൾപ്പെടെയുള്ള കാർഷിക വികസനം എന്നിവ ലക്ഷ്യമിടുന്നു.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Nava_Kerala_Mission"},
  {"topic": "കേരള ഭരണസംവിധാനം", "title": "ആർദ്രം മിഷൻ: ആരോഗ്യമേഖല", "body": "നവകേരള മിഷന്റെ ഭാഗമായ ആർദ്രം മിഷൻ സർക്കാർ ആശുപത്രികളുടെ സൗകര്യങ്ങൾ മെച്ചപ്പെടുത്തി ചുരുങ്ങിയ ചെലവിൽ ചികിത്സ ഉറപ്പാക്കാൻ ലക്ഷ്യമിടുന്ന ആരോഗ്യ പദ്ധതിയാണ്.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Nava_Kerala_Mission"},
  {"topic": "കേരള ഭരണസംവിധാനം", "title": "കേരളത്തിന്റെ ഔദ്യോഗിക മൃഗവും പക്ഷിയും", "body": "കേരളത്തിന്റെ സംസ്ഥാന മൃഗം ഇന്ത്യൻ ആനയും സംസ്ഥാന പക്ഷി മലമുഴക്കി വേഴാമ്പലും (Great hornbill) ആണ്. സംസ്ഥാന ഉഭയജീവി മലബാർ പറക്കും തവളയാണ്.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/List_of_Kerala_state_symbols"},
  {"topic": "കേരള ഭരണസംവിധാനം", "title": "ഔദ്യോഗിക പുഷ്പം കണിക്കൊന്ന, വൃക്ഷം തെങ്ങ്", "body": "കേരളത്തിന്റെ സംസ്ഥാന പുഷ്പം കണിക്കൊന്നയും (Golden shower) സംസ്ഥാന വൃക്ഷം തെങ്ങുമാണ്. കേരളത്തിന് ഔദ്യോഗികമായി അംഗീകരിച്ച സംസ്ഥാന പതാകയില്ല.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/List_of_Kerala_state_symbols"},
  {"topic": "കേരള ഭരണസംവിധാനം", "title": "ചക്ക: സംസ്ഥാന ഫലം (2018)", "body": "കൃഷി വകുപ്പിന്റെ നിർദേശപ്രകാരം 2018 മാർച്ച് 21-ന് ചക്ക കേരളത്തിന്റെ സംസ്ഥാന ഫലമായി പ്രഖ്യാപിച്ചു. സംസ്ഥാന ശലഭം പശ്ചിമഘട്ടത്തിലെ തദ്ദേശീയ ഇനമായ മലബാർ ബാൻഡഡ് പീകോക്ക് (ബുദ്ധമയൂരി) ആണ്.", "source": "Wikipedia", "url": "https://en.wikipedia.org/wiki/List_of_Kerala_state_symbols"},
  {"topic": "കേരള ഭരണസംവിധാനം", "title": "സമ്പൂർണ സാക്ഷര സംസ്ഥാനം: 1991 ഏപ്രിൽ 18", "body": "1991 ഏപ്രിൽ 18-ന് കോഴിക്കോട് മാനാഞ്ചിറ മൈതാനത്ത് കേരളത്തെ ഇന്ത്യയിലെ ആദ്യ സമ്പൂർണ സാക്ഷര സംസ്ഥാനമായി പ്രഖ്യാപിച്ചു. എറണാകുളം ജില്ലയുടെ വിജയമാണ് സംസ്ഥാനവ്യാപക കാമ്പെയ്നിന് വഴിതുറന്നത്.", "source": "The South First", "url": "https://thesouthfirst.com/kerala/100-literacy-saare-how-keralas-ernakulam-rewrote-indias-education-map/"},
  {"topic": "കേരള ഭരണസംവിധാനം", "title": "അതിദാരിദ്ര്യമുക്ത സംസ്ഥാനം: 2025 നവംബർ 1", "body": "2025 നവംബർ 1-ന് (കേരളപ്പിറവി ദിനം) നിയമസഭയുടെ പ്രത്യേക സമ്മേളനത്തിൽ കേരളത്തെ അതിദാരിദ്ര്യമുക്ത സംസ്ഥാനമായി പ്രഖ്യാപിച്ചു. അതിദാരിദ്ര്യ നിർമാർജന പദ്ധതി (EPEP) വഴി 64,006 കുടുംബങ്ങളെ കണ്ടെത്തി സഹായിച്ചു.", "source": "Business Today", "url": "https://www.businesstoday.in/india/story/kerala-becomes-first-indian-state-to-eradicate-extreme-poverty-says-cm-pinarayi-vijayan-500442-2025-11-01"}]
];
